        SeedEntry(matchers: ["dharana", "dhyana", "meditation", "antar mauna", "sukhasana", "pratyahara guidee", "samadhi"],
            fr: ExerciseExplanation(steps: ["Assieds-toi en position stable, jambes croisées, sur un bloc si le bassin bascule.", "Allonge la colonne, relâche les épaules et pose les mains sur les genoux.", "Pour la concentration (Dharana), porte l'attention sur un point : le souffle, un mantra ou un point fixe.", "Pour la méditation (Dhyana), laisse l'attention s'élargir en observation simple.", "Si des pensées arrivent, observe-les sans t'y attacher et reviens à ton point d'ancrage."], equipment: ["bloc", "couverture"], commonMistakes: "Chercher un résultat précis : laisse l'observation se faire sans attente."),
            en: ExerciseExplanation(steps: ["Sit in a stable position, cross-legged, on a block if the pelvis tilts back.", "Lengthen the spine, release the shoulders and rest the hands on the knees.", "For concentration (Dharana), bring attention to one point: the breath, a mantra or a fixed point.", "For meditation (Dhyana), let the attention widen into simple observation.", "If thoughts arise, notice them without attaching and return to your anchor."], equipment: ["block", "blanket"], commonMistakes: "Chasing a specific result: let the observation unfold without expectation.")),
        SeedEntry(matchers: ["etude yamas", "etude niyamas", "etude yoga sutras", "etude astanga", "etude pratyahara", "autoevaluation", "etude"],
            fr: ExerciseExplanation(steps: ["Installe-toi en assise stable, au calme.", "Lis le passage choisi des Yoga Sutras de Patanjali ou le thème du jour.", "Prends quelques notes courtes sur ce qui résonne pour toi.", "Relie le thème à ta pratique de la semaine, sans jugement.", "Termine par quelques respirations calmes en observation simple."], equipment: [], commonMistakes: "Vouloir tout retenir d'un coup : retiens une idée et laisse-la infuser dans ta pratique."),
            en: ExerciseExplanation(steps: ["Settle into a stable seat, in a quiet space.", "Read the chosen passage of Patanjali's Yoga Sutras or the day's theme.", "Take a few short notes on what resonates for you.", "Connect the theme to your week's practice, without judgement.", "Finish with a few calm breaths in simple observation."], equipment: [], commonMistakes: "Trying to retain everything at once: keep one idea and let it infuse your practice.")),
        SeedEntry(matchers: ["standing sequence", "sequence debout"],
            fr: ExerciseExplanation(steps: ["Enchaîne les postures debout en gardant le souffle Ujjayi régulier.", "Tiens environ 5 respirations dans chaque posture.", "Soigne les appuis des pieds et l'alignement avant de tenir.", "Place le regard juste pour stabiliser l'équilibre.", "Relie les côtés par une transition fluide, sans précipiter."], equipment: ["tapis", "bloc"], commonMistakes: "Enchaîner trop vite au détriment de l'alignement : prends le temps de t'installer dans chaque posture."),
            en: ExerciseExplanation(steps: ["Flow through the standing postures keeping the Ujjayi breath steady.", "Hold about 5 breaths in each posture.", "Set the foot grounding and alignment before holding.", "Place the gaze to stabilise balance.", "Link the sides with a smooth transition, without rushing."], equipment: ["mat", "block"], commonMistakes: "Flowing too fast at the cost of alignment: take time to settle into each posture.")),
        SeedEntry(matchers: ["virabhadrasana i", "guerrier i", "warrior i", "warrior 1"],
            fr: ExerciseExplanation(steps: ["Depuis une fente, oriente le pied arrière à 45 degrés et ancre le talon.", "Amène les hanches face à l'avant du tapis.", "Plie le genou avant au-dessus de la cheville.", "Tends les bras vers le ciel, paumes face à face, épaules basses.", "Engage les fessiers et allonge la colonne, regard droit ou légèrement haut."], equipment: ["tapis"], commonMistakes: "Laisser le talon arrière décoller : garde-le bien ancré au sol."),
            en: ExerciseExplanation(steps: ["From a lunge, turn the back foot to 45 degrees and ground the heel.", "Bring the hips to face the front of the mat.", "Bend the front knee over the ankle.", "Reach the arms up, palms facing each other, shoulders relaxed.", "Engage the glutes and lengthen the spine, gaze forward or slightly up."], equipment: ["mat"], commonMistakes: "Letting the back heel lift: keep it firmly grounded.")),
        SeedEntry(matchers: ["viparita karani", "jambes au mur", "legs up the wall"],
            fr: ExerciseExplanation(steps: ["Assieds-toi de côté près d'un mur, fessiers proches du mur.", "Pivote et allonge-toi sur le dos, jambes verticales contre le mur.", "Pose les bras en croix ou sur le ventre.", "Relâche complètement les jambes et les épaules.", "Ferme les yeux et laisse la respiration ralentir."], equipment: ["tapis", "mur"], commonMistakes: "Crisper les jambes contre le mur : laisse-les se relâcher complètement."),
            en: ExerciseExplanation(steps: ["Sit sideways near a wall, hips close to the wall.", "Pivot and lie back, legs vertical against the wall.", "Rest the arms wide or on the belly.", "Fully release the legs and shoulders.", "Close the eyes and let the breath slow down."], equipment: ["mat", "wall"], commonMistakes: "Tensing the legs against the wall: let them fully relax.")),
        SeedEntry(matchers: ["padmasana", "garbha pindasana", "kukkutasana", "yoga mudra", "tolasana", "urdhva padmasana", "pindasana", "lotus"],
            fr: ExerciseExplanation(steps: ["Assieds-toi et place un pied puis l'autre sur la cuisse opposée (demi-lotus si le lotus complet n'est pas accessible).", "Allonge la colonne et pose les mains sur les genoux.", "Pour le balancement (Garbha Pindasana), glisse les bras entre cuisses et mollets et équilibre sur les ischions.", "Pour l'élévation (Tolasana ou Kukkutasana), pose les paumes au sol et soulève le bassin.", "Garde le bas-ventre engagé et la respiration régulière."], equipment: ["tapis"], commonMistakes: "Forcer le genou en lotus : reste sur le demi-lotus ou jambes croisées simples si l'ouverture manque."),
            en: ExerciseExplanation(steps: ["Sit and place one foot then the other on the opposite thigh (half lotus if full lotus is not accessible).", "Lengthen the spine and rest the hands on the knees.", "For the rolling version (Garbha Pindasana), slide the arms between thighs and calves and balance on the sit bones.", "For the lift (Tolasana or Kukkutasana), place the palms on the floor and lift the hips.", "Keep the lower belly engaged and the breath steady."], equipment: ["mat"], commonMistakes: "Forcing the knee into lotus: stay in half lotus or simple cross-legged if the opening is not there.")),
        SeedEntry(matchers: ["balasana", "salamba balasana", "enfant", "child"],
            fr: ExerciseExplanation(steps: ["Pars à genoux, gros orteils joints, genoux ouverts ou serrés au choix.", "Assieds les fessiers vers les talons.", "Pose le front au sol et relâche la nuque.", "Tends les bras vers l'avant ou laisse-les le long du corps.", "Respire lentement dans le dos et relâche les épaules."], equipment: ["tapis"], commonMistakes: "Crisper les épaules vers les oreilles : laisse-les fondre vers le sol."),
            en: ExerciseExplanation(steps: ["Start kneeling, big toes together, knees open or close as you prefer.", "Sit the hips back toward the heels.", "Rest the forehead on the floor and release the neck.", "Reach the arms forward or let them rest alongside the body.", "Breathe slowly into the back and release the shoulders."], equipment: ["mat"], commonMistakes: "Tensing the shoulders toward the ears: let them melt toward the floor.")),
        SeedEntry(matchers: ["kapalabhati", "bhastrika", "souffle de feu", "souffle du crane"],
            fr: ExerciseExplanation(steps: ["Assieds-toi en position stable, épaules relâchées.", "Pour Kapalabhati, fais des expulsions actives et brèves par le nez, le ventre qui pompe, les inspirations passives.", "Pour Bhastrika, rends inspirations et expirations également vigoureuses par le nez.", "Garde les épaules détendues, seul le bas-ventre travaille.", "Entre les cycles, reviens à une respiration Dirgha lente et complète."], equipment: ["bloc"], commonMistakes: "Engager les épaules à chaque souffle : isole le mouvement au bas-ventre. En cas d'étourdissement, reviens à une respiration calme."),
            en: ExerciseExplanation(steps: ["Sit in a stable position, shoulders relaxed.", "For Kapalabhati, make short active exhales through the nose, the belly pumping, with passive inhales.", "For Bhastrika, make inhales and exhales equally vigorous through the nose.", "Keep the shoulders relaxed, only the lower belly works.", "Between cycles, return to a slow, full Dirgha breath."], equipment: ["block"], commonMistakes: "Engaging the shoulders on each breath: isolate the movement to the lower belly. If you feel lightheaded, return to calm breathing.")),
        SeedEntry(matchers: ["kumbhaka", "retention pleine"],
            fr: ExerciseExplanation(steps: ["Assieds-toi en position stable, colonne allongée.", "Inspire calmement sur un compte doux, par exemple 4 temps.", "Retiens le souffle plein quelques temps, par exemple 4, sans crisper la gorge.", "Expire lentement et plus longuement, par exemple 8 temps.", "Garde le visage et les épaules détendus tout du long. En cas de gêne, reviens à une respiration Dirgha simple."], equipment: ["bloc"], commonMistakes: "Bloquer la gorge en retenant : garde la rétention souple et le buste détendu."),
            en: ExerciseExplanation(steps: ["Sit in a stable position, spine lengthened.", "Inhale calmly on a gentle count, for example 4.", "Hold the full breath for a few counts, for example 4, without tensing the throat.", "Exhale slowly and longer, for example 8 counts.", "Keep the face and shoulders relaxed throughout. If anything feels off, return to a simple Dirgha breath."], equipment: ["block"], commonMistakes: "Clamping the throat while holding: keep the retention soft and the torso relaxed.")),
        SeedEntry(matchers: ["baddha konasana", "papillon", "bound angle"],
            fr: ExerciseExplanation(steps: ["Assieds-toi, plantes des pieds réunies, talons proches du bassin.", "Tiens les pieds ou les chevilles avec les mains.", "Allonge la colonne à l'inspire, sommet du crâne vers le ciel.", "Expire et plie doucement vers l'avant depuis les hanches.", "Laisse les genoux s'ouvrir vers le sol sans les forcer."], equipment: ["tapis"], commonMistakes: "Pousser fort sur les genoux : laisse-les descendre à leur rythme."),
            en: ExerciseExplanation(steps: ["Sit with the soles of the feet together, heels close to the pelvis.", "Hold the feet or ankles with the hands.", "Lengthen the spine on the inhale, crown of the head to the sky.", "Exhale and gently fold forward from the hips.", "Let the knees open toward the floor without forcing them."], equipment: ["mat"], commonMistakes: "Pressing hard on the knees: let them lower at their own pace.")),
        SeedEntry(matchers: ["purvottanasana", "uttana padasana", "plan incline"],
            fr: ExerciseExplanation(steps: ["Assieds-toi, jambes tendues, mains derrière les hanches doigts vers les pieds.", "Pieds joints, ancre les paumes au sol.", "Inspire et soulève le bassin, jambes tendues.", "Ouvre la poitrine et laisse la tête se relâcher en arrière si le cou est à l'aise.", "Engage les fessiers pour soutenir le bassin."], equipment: ["tapis"], commonMistakes: "Laisser le bassin s'affaisser : pousse activement les mains et les pieds."),
            en: ExerciseExplanation(steps: ["Sit with legs extended, hands behind the hips, fingers toward the feet.", "Feet together, anchor the palms to the floor.", "Inhale and lift the hips, legs straight.", "Open the chest and let the head release back if the neck is comfortable.", "Engage the glutes to support the hips."], equipment: ["mat"], commonMistakes: "Letting the hips sag: actively press through the hands and feet.")),
        SeedEntry(matchers: ["parsvakonasana", "angle lateral"],
            fr: ExerciseExplanation(steps: ["Depuis le Guerrier II, pose l'avant-bras sur la cuisse avant ou la main au sol ou sur un bloc.", "Tends le bras haut au-dessus de l'oreille pour former une longue diagonale.", "Garde le genou avant à 90 degrés, aligné sur la cheville.", "Étire tout le côté du tronc, de la hanche à la main haute.", "Pose le regard vers le bras haut."], equipment: ["tapis", "bloc"], commonMistakes: "Affaisser la poitrine vers le sol : garde l'ouverture du buste vers le ciel."),
            en: ExerciseExplanation(steps: ["From Warrior II, rest the forearm on the front thigh or the hand on the floor or a block.", "Reach the top arm over the ear to form a long diagonal.", "Keep the front knee at 90 degrees, aligned over the ankle.", "Stretch the entire side body, from hip to top hand.", "Set the gaze toward the top arm."], equipment: ["mat", "block"], commonMistakes: "Collapsing the chest toward the floor: keep the torso open toward the sky.")),
        SeedEntry(matchers: ["janu sirsasana", "tete au genou", "triang mukha"],
            fr: ExerciseExplanation(steps: ["Assieds-toi, une jambe tendue, l'autre pied contre la cuisse interne.", "Carre le buste vers la jambe tendue.", "Inspire et allonge la colonne.", "Expire et plie vers l'avant depuis la hanche, attrape le pied ou une sangle.", "Garde le genou plié relâché sur le côté."], equipment: ["tapis", "sangle"], commonMistakes: "Tirer sur le cou et les épaules : avance plutôt depuis les hanches."),
            en: ExerciseExplanation(steps: ["Sit with one leg extended, the other foot against the inner thigh.", "Square the torso toward the extended leg.", "Inhale and lengthen the spine.", "Exhale and fold forward from the hip, holding the foot or a strap.", "Keep the bent knee relaxed out to the side."], equipment: ["mat", "strap"], commonMistakes: "Pulling on the neck and shoulders: move forward from the hips instead.")),
        SeedEntry(matchers: ["tadasana", "montagne", "mountain pose"],
            fr: ExerciseExplanation(steps: ["Tiens-toi debout, pieds écart bassin et parallèles.", "Enracine trois appuis : gros orteil, petit orteil et talon.", "Engage doucement les cuisses et garde le bassin neutre.", "Allonge la colonne et tire le sommet du crâne vers le ciel.", "Relâche les épaules vers le bas, regard droit devant."], equipment: [], commonMistakes: "Verrouiller les genoux : garde-les souples et actifs."),
            en: ExerciseExplanation(steps: ["Stand with feet hip-width and parallel.", "Ground three points: big toe, little toe and heel.", "Gently engage the thighs and keep the pelvis neutral.", "Lengthen the spine and draw the crown of the head toward the sky.", "Release the shoulders down, gaze straight ahead."], equipment: [], commonMistakes: "Locking the knees: keep them soft and active.")),
        SeedEntry(matchers: ["phalakasana", "planche", "plank", "forearm plank", "dolphin"],
            fr: ExerciseExplanation(steps: ["Place les mains sous les épaules, doigts écartés (avant-bras au sol pour la version planche basse).", "Étends les jambes en arrière, corps en une seule ligne.", "Engage le bas-ventre et serre légèrement les fessiers.", "Pousse activement le sol pour élargir le haut du dos.", "Garde le regard entre les mains, nuque longue."], equipment: ["tapis"], commonMistakes: "Laisser le bassin s'affaisser : garde le corps aligné en une seule ligne."),
            en: ExerciseExplanation(steps: ["Place the hands under the shoulders, fingers spread (forearms on the floor for the low plank version).", "Extend the legs back, body in one straight line.", "Engage the lower belly and gently squeeze the glutes.", "Actively press the floor to broaden the upper back.", "Keep the gaze between the hands, neck long."], equipment: ["mat"], commonMistakes: "Letting the hips sag: keep the body aligned in one straight line.")),
        SeedEntry(matchers: ["sarvangasana", "chandelle", "shoulderstand"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le dos, une couverture pliée sous les épaules.", "Soulève les jambes et le bassin, mains sur le bas du dos pour soutenir.", "Garde les coudes largeur épaules et les jambes tendues vers le ciel.", "Allonge le cou en glissant les épaules sous le bord de la couverture.", "Garde le regard vers le nombril, sans tourner la tête."], equipment: ["tapis", "couverture"], commonMistakes: "Tourner la tête en équilibre : garde-la immobile et le cou long."),
            en: ExerciseExplanation(steps: ["Lie on your back, a folded blanket under the shoulders.", "Lift the legs and hips, hands on the lower back for support.", "Keep the elbows shoulder-width and the legs extended to the sky.", "Lengthen the neck by sliding the shoulders under the edge of the blanket.", "Keep the gaze toward the navel, without turning the head."], equipment: ["mat", "blanket"], commonMistakes: "Turning the head while balancing: keep it still and the neck long.")),
        SeedEntry(matchers: ["halasana", "charrue", "plough", "karnapidasana"],
            fr: ExerciseExplanation(steps: ["Depuis la chandelle, descends les jambes tendues au-dessus de la tête.", "Pose les orteils au sol, ou un bloc derrière la tête si les pieds n'atteignent pas.", "Soutiens le bas du dos avec les mains, ou entrelace les bras au sol.", "Pour la variante genoux aux oreilles, plie les genoux vers le sol.", "Garde le regard vers le nombril et le cou immobile."], equipment: ["tapis", "couverture", "bloc"], commonMistakes: "Tourner la tête sur le côté : garde le cou neutre et stable."),
            en: ExerciseExplanation(steps: ["From shoulderstand, lower the extended legs over the head.", "Set the toes on the floor, or a block behind the head if the feet do not reach.", "Support the lower back with the hands, or interlace the arms on the floor.", "For the knees-to-ears variation, bend the knees toward the floor.", "Keep the gaze toward the navel and the neck still."], equipment: ["mat", "blanket", "block"], commonMistakes: "Turning the head to the side: keep the neck neutral and stable.")),
        SeedEntry(matchers: ["anjaneyasana", "fente basse", "low lunge", "croissant"],
            fr: ExerciseExplanation(steps: ["Pose le genou arrière au sol, une couverture dessous pour le confort.", "Place le pied avant entre les mains, genou au-dessus de la cheville.", "Recule doucement les hanches vers le bas pour allonger l'avant de la hanche arrière.", "Tends les bras vers le ciel ou joins les mains au coeur.", "Garde le bas du dos long et le bas-ventre engagé."], equipment: ["tapis", "couverture"], commonMistakes: "Pousser le genou avant trop loin devant la cheville : garde-le aligné au-dessus."),
            en: ExerciseExplanation(steps: ["Set the back knee on the floor, a blanket underneath for comfort.", "Place the front foot between the hands, knee over the ankle.", "Gently sink the hips down to lengthen the front of the back hip.", "Reach the arms to the sky or join the hands at the heart.", "Keep the lower back long and the lower belly engaged."], equipment: ["mat", "blanket"], commonMistakes: "Pushing the front knee past the ankle: keep it stacked above.")),
        SeedEntry(matchers: ["marjaryasana", "bitilasana", "cat-cow", "cat cow", "chat-vache"],
            fr: ExerciseExplanation(steps: ["Pars à quatre pattes, poignets sous les épaules, genoux sous les hanches.", "Inspire : laisse le ventre descendre, ouvre la poitrine, regard léger vers l'avant.", "Expire : arrondis le dos vers le ciel, rentre le menton.", "Laisse une respiration guider chaque mouvement.", "Enchaîne lentement sur une dizaine de cycles."], equipment: ["tapis"], commonMistakes: "Forcer l'amplitude du cou : garde le mouvement fluide de la base jusqu'à la nuque."),
            en: ExerciseExplanation(steps: ["Start on all fours, wrists under shoulders, knees under hips.", "Inhale: let the belly drop, open the chest, gaze slightly forward.", "Exhale: round the back toward the sky, tuck the chin.", "Let one breath guide each movement.", "Flow slowly through about ten cycles."], equipment: ["mat"], commonMistakes: "Forcing the neck's range: keep the movement flowing from the base up to the neck.")),
        SeedEntry(matchers: ["marichyasana"],
            fr: ExerciseExplanation(steps: ["Assieds-toi, une jambe tendue, l'autre genou plié pied au sol près du fessier.", "Inspire et allonge la colonne.", "Pour la flexion : passe le bras autour de la jambe pliée et joins les doigts dans le dos.", "Pour la torsion : pivote le buste vers le genou plié, ancre le bras à l'extérieur.", "Garde le regard dans le prolongement de la torsion."], equipment: ["tapis", "sangle"], commonMistakes: "Forcer le nouage des mains : une sangle relie les mains si elles ne se rejoignent pas."),
            en: ExerciseExplanation(steps: ["Sit with one leg extended, the other knee bent, foot on the floor near the hip.", "Inhale and lengthen the spine.", "For the fold: wrap the arm around the bent leg and bind the fingers behind the back.", "For the twist: rotate the torso toward the bent knee, anchor the arm on the outside.", "Keep the gaze in line with the twist."], equipment: ["mat", "strap"], commonMistakes: "Forcing the hand bind: a strap links the hands if they do not meet.")),
        SeedEntry(matchers: ["trikonasana", "triangle"],
            fr: ExerciseExplanation(steps: ["Depuis le Guerrier II, tends la jambe avant en gardant le genou souple.", "Bascule depuis la hanche, pas depuis la taille.", "Descends la main basse sur le tibia, la cheville ou un bloc.", "Tends le bras haut vers le ciel et ouvre la poitrine.", "Pose le regard vers la main haute si le cou est à l'aise."], equipment: ["tapis", "bloc"], commonMistakes: "Arrondir le buste vers le bas pour toucher le sol : garde la longueur des côtés."),
            en: ExerciseExplanation(steps: ["From Warrior II, straighten the front leg keeping the knee soft.", "Tilt from the hip, not from the waist.", "Lower the bottom hand to the shin, ankle or a block.", "Reach the top arm toward the sky and open the chest.", "Set the gaze toward the top hand if the neck feels comfortable."], equipment: ["mat", "block"], commonMistakes: "Rounding the torso downward to reach the floor: keep length through both sides.")),
        SeedEntry(matchers: ["setu bandha", "pont", "bridge"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le dos, pieds parallèles largeur hanches sous les genoux.", "Pose les bras le long du corps, paumes au sol.", "Pousse les pieds et soulève le bassin vers le ciel.", "Entrelace les mains sous le dos et roule les épaules en dessous.", "Engage doucement les fessiers et garde les genoux écart hanches."], equipment: ["tapis"], commonMistakes: "Laisser les genoux s'écarter : garde-les alignés au-dessus des chevilles."),
            en: ExerciseExplanation(steps: ["Lie on your back, feet parallel hip-width under the knees.", "Place the arms alongside the body, palms down.", "Press the feet and lift the hips toward the sky.", "Interlace the hands under the back and roll the shoulders beneath you.", "Gently engage the glutes and keep the knees hip-width."], equipment: ["mat"], commonMistakes: "Letting the knees splay out: keep them stacked over the ankles.")),
        SeedEntry(matchers: ["salabhasana", "sauterelle", "locust"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le ventre, bras le long du corps.", "Ancre le bassin et engage les fessiers.", "Inspire et soulève le torse, les bras et les jambes en même temps.", "Garde la nuque longue dans le prolongement de la colonne.", "Allonge à travers les orteils et le bout des doigts."], equipment: ["tapis"], commonMistakes: "Casser la nuque vers l'arrière : garde le regard vers le sol et la nuque longue."),
            en: ExerciseExplanation(steps: ["Lie on your belly, arms alongside the body.", "Anchor the pelvis and engage the glutes.", "Inhale and lift the torso, arms and legs at the same time.", "Keep the neck long in line with the spine.", "Reach out through the toes and fingertips."], equipment: ["mat"], commonMistakes: "Cranking the neck back: keep the gaze toward the floor and the neck long.")),
        SeedEntry(matchers: ["dhanurasana", "bow pose"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le ventre, plie les genoux et attrape les chevilles.", "Ancre le bassin et engage les fessiers.", "Inspire et tire les chevilles dans les mains pour soulever le torse et les cuisses.", "Ouvre la poitrine et garde les épaules loin des oreilles.", "Garde une respiration régulière dans la tenue."], equipment: ["tapis"], commonMistakes: "Tirer seulement avec les bras : pousse les chevilles dans les mains pour ouvrir la poitrine."),
            en: ExerciseExplanation(steps: ["Lie on your belly, bend the knees and hold the ankles.", "Anchor the pelvis and engage the glutes.", "Inhale and press the ankles into the hands to lift the torso and thighs.", "Open the chest and keep the shoulders away from the ears.", "Keep a steady breath throughout the hold."], equipment: ["mat"], commonMistakes: "Only pulling with the arms: press the ankles into the hands to open the chest.")),
        SeedEntry(matchers: ["gomukhasana"],
            fr: ExerciseExplanation(steps: ["Lève un bras vers le ciel, plie le coude et pose la main entre les omoplates.", "Amène l'autre bras dans le dos, main qui remonte vers la première.", "Essaie de joindre les doigts, ou relie les mains avec une sangle.", "Garde la poitrine ouverte et le buste droit.", "Respire calmement et garde les épaules basses."], equipment: ["sangle"], commonMistakes: "Cambrer les côtes vers l'avant pour rapprocher les mains : garde le buste droit et utilise une sangle."),
            en: ExerciseExplanation(steps: ["Reach one arm to the sky, bend the elbow and rest the hand between the shoulder blades.", "Bring the other arm behind the back, hand reaching up toward the first.", "Try to clasp the fingers, or link the hands with a strap.", "Keep the chest open and the torso upright.", "Breathe calmly and keep the shoulders low."], equipment: ["strap"], commonMistakes: "Flaring the ribs forward to bring the hands closer: keep the torso upright and use a strap.")),
        SeedEntry(matchers: ["chaturanga"],
            fr: ExerciseExplanation(steps: ["Depuis la planche, avance légèrement sur la pointe des pieds.", "Pose les genoux au sol tant que la version basse n'est pas stable.", "Expire et plie les coudes le long du corps, sans les ouvrir vers l'extérieur.", "Arrête la descente quand les épaules arrivent à hauteur des coudes, environ 90 degrés.", "Garde le bas-ventre engagé et le regard légèrement vers l'avant."], equipment: ["tapis"], commonMistakes: "Laisser les épaules descendre plus bas que les coudes : reste à l'angle de 90 degrés."),
            en: ExerciseExplanation(steps: ["From plank, shift slightly forward onto the balls of the feet.", "Lower the knees to the floor until the low version feels stable.", "Exhale and bend the elbows alongside the ribs, keeping them from flaring out.", "Stop lowering when the shoulders reach elbow height, around 90 degrees.", "Keep the lower belly engaged and the gaze slightly forward."], equipment: ["mat"], commonMistakes: "Letting the shoulders drop below the elbows: stay at the 90-degree angle.")),
        SeedEntry(matchers: ["utkatasana", "chaise", "chair pose"],
            fr: ExerciseExplanation(steps: ["Pieds joints ou écart bassin, plie les genoux comme pour t'asseoir.", "Recule le bassin et garde le poids vers les talons.", "Allonge la colonne et garde le bas du dos long.", "Tends les bras vers le ciel, paumes face à face.", "Engage les cuisses et le bas-ventre, regard droit devant."], equipment: ["tapis"], commonMistakes: "Cambrer fortement le bas du dos : garde le bassin neutre et le bas-ventre actif."),
            en: ExerciseExplanation(steps: ["Feet together or hip-width, bend the knees as if to sit down.", "Send the hips back and keep the weight toward the heels.", "Lengthen the spine and keep the lower back long.", "Reach the arms toward the sky, palms facing each other.", "Engage the thighs and lower belly, gaze straight ahead."], equipment: ["mat"], commonMistakes: "Over-arching the lower back: keep the pelvis neutral and the lower belly active.")),
        SeedEntry(matchers: ["garudasana", "aigle", "eagle pose"],
            fr: ExerciseExplanation(steps: ["Plie légèrement les genoux comme assis sur une chaise.", "Croise une jambe par-dessus l'autre, l'orteil cherchant le mollet.", "Croise les bras, un coude sous l'autre, paumes face à face.", "Lève doucement les coudes et éloigne les mains du visage.", "Fixe un point devant toi et garde le buste droit."], equipment: [], commonMistakes: "Rentrer les épaules vers les oreilles : garde-les basses et la nuque longue."),
            en: ExerciseExplanation(steps: ["Bend the knees slightly as if sitting on a chair.", "Cross one leg over the other, the toe reaching toward the calf.", "Cross the arms, one elbow under the other, palms facing each other.", "Gently lift the elbows and reach the hands away from the face.", "Fix a point in front of you and keep the torso upright."], equipment: [], commonMistakes: "Drawing the shoulders toward the ears: keep them low and the neck long.")),
        SeedEntry(matchers: ["ustrasana", "chameau", "camel pose"],
            fr: ExerciseExplanation(steps: ["À genoux, écart hanches, mains sur le bas du dos.", "Engage les fessiers et allonge le buste vers le haut.", "Ouvre la poitrine vers le ciel avant de te cambrer.", "Descends les mains vers les talons si le cou reste à l'aise.", "Garde les hanches au-dessus des genoux."], equipment: ["tapis"], commonMistakes: "Pousser les hanches en arrière : garde-les empilées au-dessus des genoux."),
            en: ExerciseExplanation(steps: ["Kneel hip-width apart, hands on the lower back.", "Engage the glutes and lengthen the torso upward.", "Open the chest toward the sky before arching.", "Lower the hands toward the heels if the neck stays comfortable.", "Keep the hips stacked over the knees."], equipment: ["mat"], commonMistakes: "Pushing the hips backward: keep them stacked over the knees.")),
        SeedEntry(matchers: ["matsyasana", "poisson", "fish pose"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le dos, mains sous les fessiers paumes au sol.", "Appuie sur les coudes et soulève la cage thoracique.", "Pose doucement le sommet du crâne au sol, sans écraser le cou.", "Garde l'appui réparti entre les coudes et le bassin.", "Ouvre la poitrine vers le ciel, respiration régulière."], equipment: ["tapis"], commonMistakes: "Mettre le poids sur le sommet du crâne : garde l'appui dans les coudes."),
            en: ExerciseExplanation(steps: ["Lie on your back, hands under the hips, palms down.", "Press into the elbows and lift the ribcage.", "Gently rest the crown of the head on the floor, without compressing the neck.", "Keep the support spread between the elbows and the pelvis.", "Open the chest toward the sky, breathing steadily."], equipment: ["mat"], commonMistakes: "Putting the weight on the crown of the head: keep the support in the elbows.")),
        SeedEntry(matchers: ["vrksasana", "arbre", "tree pose"],
            fr: ExerciseExplanation(steps: ["Depuis Tadasana, transfère le poids sur une jambe.", "Pose la plante de l'autre pied sur la cheville interne ou le mollet, jamais sur le genou.", "Engage le fessier de la jambe d'appui pour stabiliser.", "Joins les mains au coeur ou tends les bras vers le ciel.", "Fixe un point immobile devant toi pour l'équilibre."], equipment: [], commonMistakes: "Poser le pied directement sur le genou : place-le au-dessus ou en dessous."),
            en: ExerciseExplanation(steps: ["From Tadasana, transfer the weight onto one leg.", "Place the sole of the other foot on the inner ankle or calf, never on the knee.", "Engage the standing-leg glute to stabilise.", "Join the hands at the heart or reach the arms to the sky.", "Fix a still point in front of you for balance."], equipment: [], commonMistakes: "Placing the foot directly on the knee: set it above or below instead.")),
        SeedEntry(matchers: ["navasana", "bateau", "boat pose"],
            fr: ExerciseExplanation(steps: ["Assieds-toi, jambes tendues devant, mains derrière les hanches.", "Lève les jambes à environ 45 degrés, ou genoux pliés si le bas du dos est sensible.", "Allonge le dos et garde la poitrine ouverte.", "Tends les bras vers l'avant, parallèles au sol.", "Engage le bas-ventre, regard droit devant."], equipment: ["tapis"], commonMistakes: "Arrondir le dos en arrière : garde le sternum levé et la colonne longue."),
            en: ExerciseExplanation(steps: ["Sit with legs extended in front, hands behind the hips.", "Lift the legs to about 45 degrees, or bend the knees if the lower back is sensitive.", "Lengthen the back and keep the chest open.", "Extend the arms forward, parallel to the floor.", "Engage the lower belly, gaze straight ahead."], equipment: ["mat"], commonMistakes: "Rounding the back: keep the sternum lifted and the spine long.")),
        SeedEntry(matchers: ["sirsasana", "headstand"],
            fr: ExerciseExplanation(steps: ["Pose une couverture pliée au sol, place les avant-bras largeur épaules et entrelace les doigts en coupe.", "Pose le sommet du crâne au sol, l'arrière de la tête contre les mains.", "Pousse les avant-bras dans le sol pour éloigner les épaules des oreilles.", "Marche les pieds vers le visage jusqu'à empiler les hanches au-dessus des épaules.", "Garde la plupart du poids dans les avant-bras et monte les jambes une à la fois, ou pratique près d'un mur."], equipment: ["tapis", "couverture", "mur"], commonMistakes: "Charger le sommet du crâne : garde l'essentiel du poids dans les avant-bras."),
            en: ExerciseExplanation(steps: ["Set a folded blanket down, place the forearms shoulder-width and interlace the fingers into a cup.", "Set the crown of the head on the floor, the back of the head against the hands.", "Press the forearms into the floor to draw the shoulders away from the ears.", "Walk the feet toward the face until the hips stack over the shoulders.", "Keep most of the weight in the forearms and lift the legs one at a time, or practise near a wall."], equipment: ["mat", "blanket", "wall"], commonMistakes: "Loading the crown of the head: keep most of the weight in the forearms.")),
        SeedEntry(matchers: ["kurmasana", "tortue", "tortoise"],
            fr: ExerciseExplanation(steps: ["Assieds-toi, jambes écartées et tendues, genoux légèrement pliés.", "Glisse les bras sous les genoux, paumes vers le sol sur les côtés.", "Expire et avance le buste vers le sol entre les jambes.", "Allonge progressivement les jambes tandis que le torse descend.", "Garde la respiration régulière et le regard vers le sol."], equipment: ["tapis"], commonMistakes: "Forcer pour aplatir le torse : avance par petites expirations sans tirer fort."),
            en: ExerciseExplanation(steps: ["Sit with legs wide and extended, knees slightly bent.", "Slide the arms under the knees, palms toward the floor at the sides.", "Exhale and reach the torso toward the floor between the legs.", "Gradually straighten the legs as the chest lowers.", "Keep the breath steady and the gaze toward the floor."], equipment: ["mat"], commonMistakes: "Forcing the chest flat: move forward on small exhales without pulling hard.")),
        SeedEntry(matchers: ["autonomie"],
            fr: ExerciseExplanation(steps: ["Choisis quelques postures dans le répertoire que tu connais bien.", "Compose une séquence équilibrée : une posture debout, un équilibre, un mouvement doux du dos, une flexion avant.", "Tiens chaque posture quelques respirations Ujjayi.", "Soigne les transitions et garde le souffle régulier.", "Termine par un retour au calme assis ou allongé."], equipment: ["tapis", "bloc"], commonMistakes: "Enchaîner sans cohérence : alterne effort et postures plus calmes pour une séquence équilibrée."),
            en: ExerciseExplanation(steps: ["Choose a few postures from the repertoire you know well.", "Build a balanced sequence: a standing posture, a balance, a gentle back movement, a forward fold.", "Hold each posture for a few Ujjayi breaths.", "Mind the transitions and keep the breath steady.", "Finish with a seated or lying cool-down."], equipment: ["mat", "block"], commonMistakes: "Flowing without structure: alternate effort and calmer postures for a balanced sequence.")),
        SeedEntry(matchers: ["bakasana", "crow", "corbeau"],
            fr: ExerciseExplanation(steps: ["Depuis un squat, pose les mains au sol largeur épaules (sur deux briques basses pour débuter).", "Écarte les doigts et regarde légèrement vers l'avant.", "Pose les genoux haut sur l'arrière des bras.", "Transfère le poids progressivement vers les mains.", "Décolle un pied puis l'autre, en gardant le bas-ventre engagé."], equipment: ["tapis", "blocs"], commonMistakes: "Regarder vers les pieds : porte plutôt le regard vers l'avant pour ne pas basculer."),
            en: ExerciseExplanation(steps: ["From a squat, place the hands on the floor shoulder-width (on two low blocks to begin).", "Spread the fingers and look slightly forward.", "Set the knees high onto the backs of the arms.", "Shift the weight gradually toward the hands.", "Lift one foot then the other, keeping the lower belly engaged."], equipment: ["mat", "blocks"], commonMistakes: "Looking toward the feet: gaze forward instead so you do not tip over.")),
        SeedEntry(matchers: ["ujjayi"],
            fr: ExerciseExplanation(steps: ["Assieds-toi confortablement, sur un bloc si besoin, colonne allongée.", "Resserre doucement la gorge pour créer un léger son océanique.", "Inspire et expire par le nez, le son régulier et doux, jamais raclé.", "Vise des inspirations et expirations égales, par exemple 4 à 6 secondes chacune.", "Garde les épaules relâchées et le visage détendu."], equipment: ["bloc"], commonMistakes: "Forcer le son jusqu'à le rendre rauque : garde-le doux et régulier."),
            en: ExerciseExplanation(steps: ["Sit comfortably, on a block if needed, spine lengthened.", "Gently narrow the throat to create a soft ocean-like sound.", "Inhale and exhale through the nose, the sound steady and soft, never scraped.", "Aim for even inhales and exhales, for example 4 to 6 seconds each.", "Keep the shoulders relaxed and the face soft."], equipment: ["block"], commonMistakes: "Forcing the sound until it turns rough: keep it soft and steady.")),

        // MARK: strength-training (42)
        SeedEntry(matchers: ["deadlift conventionnel", "deadlift", "soulevé de terre"],
            fr: ExerciseExplanation(steps: ["Place la barre au-dessus du milieu du pied (au niveau des lacets), pieds largeur de hanches.", "Recule les fesses pour trouver la charnière, fléchis les genoux jusqu'à saisir la barre, dos plat, hanches plus hautes que les genoux.", "Inspire et gaine le tronc, épaules légèrement devant la barre.", "Pousse le sol vers le bas et redresse hanches et poitrine ensemble, la barre reste collée aux jambes."], equipment: ["barre"], commonMistakes: "Laisser les hanches monter en premier, ce qui sort les jambes du mouvement et arrondit le dos."),
            en: ExerciseExplanation(steps: ["Set the bar over the midfoot (around the shoelaces), feet hip-width.", "Send the hips back to find the hinge, bend the knees until you grip the bar, flat back, hips higher than the knees.", "Inhale and brace the trunk, shoulders slightly ahead of the bar.", "Push the floor away and raise hips and chest together, keeping the bar against the legs."], equipment: ["barbell"], commonMistakes: "Letting the hips rise first, which takes the legs out of the movement and rounds the back.")),
        SeedEntry(matchers: ["reverse hyperextension", "reverse hyper"],
            fr: ExerciseExplanation(steps: ["Place le bassin au bord d'un banc, buste en appui, jambes pendantes.", "Élève les jambes vers l'arrière en serrant les fessiers et le bas du dos.", "Monte jusqu'à l'alignement, sans hyperextension excessive.", "Redescends de façon contrôlée."], equipment: ["banc"], commonMistakes: "Monter trop haut en hyperextension au lieu de s'arrêter à l'alignement."),
            en: ExerciseExplanation(steps: ["Place the hips at the edge of a bench, torso supported, legs hanging.", "Raise the legs backward by squeezing the glutes and lower back.", "Lift to alignment, without excessive hyperextension.", "Lower under control."], equipment: ["bench"], commonMistakes: "Lifting too high into hyperextension instead of stopping at alignment.")),
        SeedEntry(matchers: ["bulgarian split squat", "split squat"],
            fr: ExerciseExplanation(steps: ["Pose le pied arrière sur un banc, pied avant à 50-80 cm devant, tronc droit.", "Descends à la verticale, genou arrière vers le sol, sans avancer le buste.", "Garde le genou avant aligné dans l'axe du pied.", "Remonte en poussant sur le talon avant, contrôle la descente."], equipment: ["banc", "haltères"], commonMistakes: "Avancer le buste vers le pied avant au lieu de descendre à la verticale."),
            en: ExerciseExplanation(steps: ["Rest the rear foot on a bench, front foot 50-80 cm ahead, torso tall.", "Lower straight down, rear knee toward the floor, without leaning the torso forward.", "Keep the front knee tracking in line with the foot.", "Drive back up through the front heel, control the descent."], equipment: ["bench", "dumbbells"], commonMistakes: "Leaning the torso toward the front foot instead of lowering straight down.")),
        SeedEntry(matchers: ["bent-over barbell row", "bent-over row", "barbell row", "pendlay"],
            fr: ExerciseExplanation(steps: ["Buste penché à environ 45° (ou parallèle au sol en Pendlay), dos plat, prise en pronation.", "Tire la barre vers le nombril ou le bas du sternum, coudes dans l'axe du tronc.", "Rétracte les omoplates en fin de course, pause 1 seconde.", "Redescends de façon contrôlée, sans à-coup lombaire."], equipment: ["barre"], commonMistakes: "Utiliser un coup de reins pour lancer la barre au lieu de tirer avec le dos."),
            en: ExerciseExplanation(steps: ["Torso bent to about 45° (or parallel to the floor for Pendlay), flat back, overhand grip.", "Pull the bar toward the navel or lower sternum, elbows in line with the trunk.", "Retract the shoulder blades at the end of the range, pause 1 second.", "Lower under control, no low-back jerk."], equipment: ["barbell"], commonMistakes: "Using a low-back heave to launch the bar instead of pulling with the back.")),
        SeedEntry(matchers: ["back squat", "squat poids du corps", "squat barre", "air squat"],
            fr: ExerciseExplanation(steps: ["Place la barre sur le haut du dos (sur les trapèzes en high bar, plus bas sur les deltoïdes arrière en low bar), pieds largeur d'épaules, orteils légèrement ouverts.", "Inspire, gaine le tronc, puis amorce la descente en cassant aux hanches et en reculant les fesses, pas en poussant les genoux en avant.", "Descends jusqu'à cuisses au moins parallèles au sol, genoux alignés dans l'axe des orteils, poitrine ouverte.", "Remonte en poussant le sol avec les pieds, hanches et poitrine montent ensemble, garde le poids sur tout le pied."], equipment: ["barre", "rack"], commonMistakes: "Squatter trop haut sans atteindre la parallèle, ce qui réduit le travail des cuisses et des fessiers."),
            en: ExerciseExplanation(steps: ["Set the bar across the upper back (on the traps for high bar, lower on the rear delts for low bar), feet shoulder-width, toes slightly out.", "Inhale, brace the trunk, then start the descent by breaking at the hips and sending the glutes back rather than pushing the knees forward.", "Lower until the thighs are at least parallel to the floor, knees tracking over the toes, chest open.", "Drive back up by pushing the floor away, hips and chest rising together, keep the weight across the whole foot."], equipment: ["barbell", "rack"], commonMistakes: "Squatting too shallow without reaching parallel, which cuts the work to the quads and glutes.")),
        SeedEntry(matchers: ["incline db bench", "incline db press", "incline bench press", "incline dumbbell"],
            fr: ExerciseExplanation(steps: ["Règle le banc à environ 30° d'inclinaison (au-delà, le mouvement glisse vers le développé épaules).", "Pars haltères au niveau du haut des pectoraux, omoplates rétractées.", "Pousse vers le haut de façon contrôlée, sans entrechoquer les haltères en haut.", "Redescends jusqu'au niveau du haut de la poitrine, sans aller plus bas."], equipment: ["haltères", "banc inclinable"], commonMistakes: "Incliner le banc bien au-delà de 30°, ce qui transforme le mouvement en développé épaules."),
            en: ExerciseExplanation(steps: ["Set the bench to about 30° incline (steeper turns it into a shoulder press).", "Start with the dumbbells at upper-chest level, shoulder blades retracted.", "Press up under control, without clashing the dumbbells at the top.", "Lower back to upper-chest level, without going deeper."], equipment: ["dumbbells", "incline bench"], commonMistakes: "Inclining the bench well past 30°, which turns the move into a shoulder press.")),
        SeedEntry(matchers: ["overhead press", "ohp", "développé militaire", "arnold press", "shoulder press", "seated db shoulder"],
            fr: ExerciseExplanation(steps: ["Barre ou haltères au niveau des épaules, prise un peu plus large que les épaules.", "Gaine le tronc, serre les fessiers, garde le bassin neutre sans cambrer le bas du dos.", "Presse à la verticale, la barre passe près du visage, puis fais passer la tête sous la barre en haut.", "Verrouille bras tendus, barre au-dessus du milieu du crâne, rentre légèrement le menton."], equipment: ["barre", "haltères"], commonMistakes: "Cambrer fortement le bas du dos pour compenser le manque d'amplitude des épaules."),
            en: ExerciseExplanation(steps: ["Bar or dumbbells at shoulder level, grip slightly wider than the shoulders.", "Brace the trunk, squeeze the glutes, keep the hips neutral without arching the lower back.", "Press straight up, the bar passing close to the face, then move the head under the bar at the top.", "Lock out with straight arms, bar over the mid-skull, chin tucked slightly."], equipment: ["barbell", "dumbbells"], commonMistakes: "Strongly arching the lower back to make up for limited shoulder range.")),
        SeedEntry(matchers: ["cable row", "chest-supported row", "chest supported row", "seated row"],
            fr: ExerciseExplanation(steps: ["Saisis la poignée (souvent en V neutre), buste droit ou appuyé sur le support de poitrine.", "Tire vers le nombril, coudes proches du corps.", "Marque une pause 1 seconde en serrant les omoplates.", "Reviens de façon contrôlée, sans balancer le tronc."], equipment: ["poulie", "machine"], commonMistakes: "Balancer le tronc d'avant en arrière pour aider à tirer la charge."),
            en: ExerciseExplanation(steps: ["Grab the handle (often a neutral V grip), torso upright or supported on the chest pad.", "Pull toward the navel, elbows close to the body.", "Hold a 1-second pause while squeezing the shoulder blades.", "Return under control, without swinging the trunk."], equipment: ["cable", "machine"], commonMistakes: "Rocking the trunk back and forth to help pull the load.")),
        SeedEntry(matchers: ["overhead db triceps", "triceps extension", "overhead triceps"],
            fr: ExerciseExplanation(steps: ["Tiens un haltère à deux mains derrière la tête, coudes pointés vers le plafond.", "Étends les bras vers le haut jusqu'à extension complète.", "Garde les coudes proches, sans les écarter largement.", "Reviens de façon contrôlée en sentant l'étirement du triceps."], equipment: ["haltère"], commonMistakes: "Écarter largement les coudes, ce qui réduit le travail du triceps."),
            en: ExerciseExplanation(steps: ["Hold a dumbbell with both hands behind the head, elbows pointing toward the ceiling.", "Extend the arms up to full extension.", "Keep the elbows close, without flaring them wide.", "Return under control while feeling the triceps stretch."], equipment: ["dumbbell"], commonMistakes: "Flaring the elbows wide, which reduces the triceps work.")),
        SeedEntry(matchers: ["lateral raise", "lateral raises", "élévation latérale"],
            fr: ExerciseExplanation(steps: ["Haltères ou poignée de câble le long du corps, légère flexion des coudes.", "Élève les bras sur les côtés jusqu'à hauteur des épaules.", "Garde le tronc stable, sans balancement pour lancer la charge.", "Redescends de façon contrôlée sur 2 secondes."], equipment: ["haltères", "câble"], commonMistakes: "Balancer le buste pour donner de l'élan au lieu d'isoler le deltoïde latéral."),
            en: ExerciseExplanation(steps: ["Dumbbells or cable handle by the sides, slight bend in the elbows.", "Raise the arms out to the sides up to shoulder height.", "Keep the trunk stable, no swinging to launch the weight.", "Lower under control over 2 seconds."], equipment: ["dumbbells", "cable"], commonMistakes: "Swinging the torso to build momentum instead of isolating the side delt.")),
        SeedEntry(matchers: ["romanian deadlift", "rdl", "soulevé roumain"],
            fr: ExerciseExplanation(steps: ["Tiens la barre ou les haltères devant les cuisses, pieds largeur de hanches, légère flexion des genoux.", "Recule les fesses en charnière, dos plat, descends le long des jambes jusqu'à sentir l'étirement des ischio-jambiers (mi-tibia maximum).", "Garde la barre collée aux jambes, comme si tu cherchais à fléchir les lats.", "Remonte en serrant les fessiers, sans cambrer le bas du dos en haut."], equipment: ["barre", "haltères"], commonMistakes: "Descendre plus bas que la mobilité des ischio-jambiers, ce qui fait reprendre le bas du dos."),
            en: ExerciseExplanation(steps: ["Hold the bar or dumbbells in front of the thighs, feet hip-width, slight knee bend.", "Hinge by sending the glutes back, flat back, lower along the legs until you feel the hamstrings stretch (mid-shin at most).", "Keep the bar against the legs, as if engaging the lats to hold it close.", "Stand up by squeezing the glutes, without arching the lower back at the top."], equipment: ["barbell", "dumbbells"], commonMistakes: "Going lower than the hamstrings' range, which shifts the load onto the lower back.")),
        SeedEntry(matchers: ["dumbbell row", "single-arm db row", "db row"],
            fr: ExerciseExplanation(steps: ["Pose un genou et une main sur un banc, l'autre pied au sol, dos plat parallèle au sol.", "Tire l'haltère vers la hanche (pas vers l'épaule), coude proche du corps.", "Garde le tronc stable, sans pivoter ni hausser l'épaule de travail.", "Redescends de façon contrôlée en sentant l'étirement du dos."], equipment: ["haltère", "banc"], commonMistakes: "Pivoter le tronc pour soulever, signe que la charge est trop lourde."),
            en: ExerciseExplanation(steps: ["Place one knee and hand on a bench, the other foot on the floor, flat back parallel to the floor.", "Pull the dumbbell toward the hip (not the shoulder), elbow close to the body.", "Keep the trunk stable, without rotating or shrugging the working shoulder.", "Lower under control while feeling the stretch in the back."], equipment: ["dumbbell", "bench"], commonMistakes: "Rotating the trunk to lift, a sign the load is too heavy.")),
        SeedEntry(matchers: ["dumbbell pullover", "pullover", "y-raise", "y raise"],
            fr: ExerciseExplanation(steps: ["Allongé sur le dos, genoux fléchis, tiens un haltère léger à deux mains au-dessus du sternum.", "Descends l'haltère derrière la tête en inspirant, coudes légèrement fléchis.", "Garde le bas du dos en contact avec le sol.", "Ramène l'haltère au-dessus de la poitrine en expirant."], equipment: ["haltère", "tapis"], commonMistakes: "Cambrer le bas du dos en descendant l'haltère au lieu de le garder plaqué."),
            en: ExerciseExplanation(steps: ["Lie on the back, knees bent, hold a light dumbbell with both hands over the sternum.", "Lower the dumbbell behind the head while inhaling, elbows slightly bent.", "Keep the lower back in contact with the floor.", "Bring the dumbbell back over the chest while exhaling."], equipment: ["dumbbell", "mat"], commonMistakes: "Arching the lower back as the dumbbell lowers instead of keeping it flat.")),
        SeedEntry(matchers: ["woodchopper", "cable woodchopper"],
            fr: ExerciseExplanation(steps: ["Règle le câble en position haute, place-toi de profil, saisis la poignée à deux mains.", "Tire en diagonale vers la hanche opposée, bras tendus.", "Initie la rotation depuis les hanches, pas seulement le tronc.", "Reviens contrôlé en résistant au retour du câble."], equipment: ["câble", "poulie"], commonMistakes: "Tourner uniquement le tronc en gardant les hanches figées."),
            en: ExerciseExplanation(steps: ["Set the cable high, stand sideways, grab the handle with both hands.", "Pull diagonally toward the opposite hip, arms straight.", "Initiate the rotation from the hips, not just the trunk.", "Return under control while resisting the cable's pull-back."], equipment: ["cable", "pulley"], commonMistakes: "Rotating only the trunk while keeping the hips locked.")),
        SeedEntry(matchers: ["hanging leg raise", "crunch inverse", "ab wheel", "crunch"],
            fr: ExerciseExplanation(steps: ["Suspends-toi à la barre (ou allonge-toi pour le crunch inverse), gainage engagé.", "Monte les jambes ou enroule le bassin de façon contrôlée vers la poitrine.", "Évite tout balancement, le mouvement vient des abdominaux.", "Redescends lentement sans relâcher d'un coup."], equipment: ["barre de traction", "tapis"], commonMistakes: "Se balancer pour donner de l'élan au lieu d'enrouler le bassin avec les abdos."),
            en: ExerciseExplanation(steps: ["Hang from the bar (or lie down for the reverse crunch), bracing engaged.", "Raise the legs or curl the pelvis under control toward the chest.", "Avoid any swinging, the movement comes from the abs.", "Lower slowly without releasing suddenly."], equipment: ["pull-up bar", "mat"], commonMistakes: "Swinging for momentum instead of curling the pelvis with the abs.")),
        SeedEntry(matchers: ["mobilité", "mobility", "foam rolling", "stretch", "cat-cow", "chat-vache", "thread the needle", "shoulder cars", "hip 90"],
            fr: ExerciseExplanation(steps: ["Enchaîne les exercices de mobilité prévus à un rythme lent et fluide.", "Sur chaque position, va jusqu'à une amplitude confortable sans forcer.", "Respire amplement et tiens chaque position le temps indiqué.", "Privilégie le contrôle du mouvement à l'amplitude maximale."], equipment: ["tapis", "rouleau"], commonMistakes: "Forcer les amplitudes au-delà du confortable au lieu de rester progressif."),
            en: ExerciseExplanation(steps: ["Flow through the planned mobility drills at a slow, smooth pace.", "In each position, go to a comfortable range without forcing.", "Breathe fully and hold each position for the prescribed time.", "Favor control of the movement over maximum range."], equipment: ["mat", "roller"], commonMistakes: "Forcing ranges beyond comfortable instead of staying progressive.")),
        SeedEntry(matchers: ["triceps pushdown", "pushdown"],
            fr: ExerciseExplanation(steps: ["Saisis la corde ou la barre sur une poulie haute, coudes fixes contre le tronc.", "Étends les bras vers le bas jusqu'à extension complète, écarte la corde en fin.", "Marque une brève contraction en bas.", "Reviens de façon contrôlée sans laisser les coudes partir en avant."], equipment: ["poulie", "corde"], commonMistakes: "Laisser les coudes s'écarter du corps et avancer, ce qui transforme le mouvement."),
            en: ExerciseExplanation(steps: ["Grab the rope or bar on a high pulley, elbows fixed against the trunk.", "Extend the arms down to full extension, spread the rope at the bottom.", "Hold a brief contraction at the bottom.", "Return under control without letting the elbows drift forward."], equipment: ["pulley", "rope"], commonMistakes: "Letting the elbows flare out and move forward, which changes the movement.")),
        SeedEntry(matchers: ["planche ventrale", "plank ventral", "plank", "planche"],
            fr: ExerciseExplanation(steps: ["Place les coudes sous les épaules, avant-bras au sol, appuis sur la pointe des pieds.", "Aligne le corps de la tête aux talons, regard vers le sol.", "Gaine les abdominaux et serre les fessiers pour stabiliser le bassin.", "Maintiens la position sans laisser les hanches monter ni s'affaisser."], equipment: ["tapis"], commonMistakes: "Laisser les hanches s'affaisser ou monter, ce qui sort la tension du tronc."),
            en: ExerciseExplanation(steps: ["Place the elbows under the shoulders, forearms on the floor, weight on the toes.", "Align the body from head to heels, eyes toward the floor.", "Brace the abs and squeeze the glutes to stabilize the hips.", "Hold the position without letting the hips rise or sag."], equipment: ["mat"], commonMistakes: "Letting the hips sag or pike, which takes the tension off the core.")),
        SeedEntry(matchers: ["side plank", "planche latérale"],
            fr: ExerciseExplanation(steps: ["Place le coude sous l'épaule, en appui sur l'avant-bras et le bord du pied du dessous.", "Aligne le corps de la tête aux pieds, hanches montées et alignées.", "Gaine les obliques pour résister à la chute du bassin.", "Maintiens la position, puis change de côté."], equipment: ["tapis"], commonMistakes: "Laisser le bassin tomber vers le sol au lieu de garder la ligne corporelle."),
            en: ExerciseExplanation(steps: ["Place the elbow under the shoulder, supported on the forearm and the edge of the bottom foot.", "Align the body from head to feet, hips lifted and in line.", "Brace the obliques to resist the hips dropping.", "Hold the position, then switch sides."], equipment: ["mat"], commonMistakes: "Letting the hips drop toward the floor instead of keeping the body line.")),
        SeedEntry(matchers: ["activation", "marche active", "scapular pull-up"],
            fr: ExerciseExplanation(steps: ["Enchaîne les mouvements d'activation prévus à intensité très légère.", "Cherche la qualité du geste et le réveil musculaire, pas l'effort.", "Garde un tempo posé et contrôlé sur chaque répétition.", "Termine en te sentant échauffé, pas fatigué."], equipment: [], commonMistakes: "Charger ou accélérer l'activation au lieu de rester sur un éveil léger."),
            en: ExerciseExplanation(steps: ["Flow through the planned activation drills at very light intensity.", "Aim for movement quality and muscle wake-up, not effort.", "Keep a calm, controlled tempo on each rep.", "Finish feeling warmed up, not fatigued."], equipment: [], commonMistakes: "Loading or rushing the activation instead of staying on a light wake-up.")),
        SeedEntry(matchers: ["cable fly", "cable chest fly", "chest fly"],
            fr: ExerciseExplanation(steps: ["Règle les poulies (basses vers le haut, ou hauteur sternum), saisis les poignées, un pied légèrement avancé.", "Garde une légère flexion des coudes fixe tout du long.", "Amène les mains au centre devant la poitrine, contraction 1 seconde.", "Reviens en sentant l'étirement contrôlé des pectoraux."], equipment: ["poulie", "câble"], commonMistakes: "Plier et tendre les coudes comme un développé au lieu de garder l'angle fixe."),
            en: ExerciseExplanation(steps: ["Set the pulleys (low-to-high or sternum height), grab the handles, one foot slightly forward.", "Keep a fixed slight bend in the elbows throughout.", "Bring the hands to the center in front of the chest, hold the contraction 1 second.", "Return while feeling a controlled stretch in the chest."], equipment: ["cable", "pulley"], commonMistakes: "Bending and straightening the elbows like a press instead of keeping the angle fixed.")),
        SeedEntry(matchers: ["curl biceps", "biceps curl", "db curl", "incline db curl", "barbell biceps", "dumbbell curl"],
            fr: ExerciseExplanation(steps: ["Tiens les haltères ou la barre, coudes fixes proches du tronc.", "Fléchis les coudes en montant la charge, supination complète en haut.", "Garde le buste immobile, sans balancement.", "Contrôle la descente sur 2 secondes."], equipment: ["haltères", "barre EZ"], commonMistakes: "Balancer le buste pour donner de l'élan au lieu d'isoler le biceps."),
            en: ExerciseExplanation(steps: ["Hold the dumbbells or bar, elbows fixed close to the trunk.", "Bend the elbows to raise the load, full supination at the top.", "Keep the torso still, no swinging.", "Control the descent over 2 seconds."], equipment: ["dumbbells", "EZ bar"], commonMistakes: "Swinging the torso for momentum instead of isolating the biceps.")),
        SeedEntry(matchers: ["checklist", "autoévaluation", "autoevaluation", "bilan cycle", "autonomie"],
            fr: ExerciseExplanation(steps: ["Prends quelques minutes au calme pour répondre à chaque critère par écrit.", "Compare honnêtement tes résultats actuels à ceux de départ.", "Note les patterns maîtrisés et ceux à consolider au prochain cycle.", "Sers-toi de ce bilan pour orienter tes priorités à venir."], equipment: [], commonMistakes: "Survoler l'autoévaluation au lieu d'y répondre franchement, ce qui en réduit l'intérêt."),
            en: ExerciseExplanation(steps: ["Take a few quiet minutes to answer each criterion in writing.", "Honestly compare your current results to where you started.", "Note the patterns you have mastered and those to consolidate next cycle.", "Use this review to guide your upcoming priorities."], equipment: [], commonMistakes: "Skimming the self-assessment instead of answering frankly, which loses its value.")),
        SeedEntry(matchers: ["walking lunge", "lunge", "fente"],
            fr: ExerciseExplanation(steps: ["Fais un grand pas en avant, tronc vertical, regard devant.", "Descends jusqu'à genou avant à 90° environ, genou arrière qui frôle le sol sans taper.", "Pousse sur le talon avant pour remonter ou enchaîner le pas suivant.", "Garde les hanches stables, sans bascule latérale."], equipment: ["haltères"], commonMistakes: "Laisser le genou avant dépasser largement la pointe du pied en penchant le buste."),
            en: ExerciseExplanation(steps: ["Take a long step forward, torso upright, eyes ahead.", "Lower until the front knee is around 90°, rear knee grazing the floor without tapping.", "Push through the front heel to stand back up or move into the next step.", "Keep the hips stable, no side-to-side tilt."], equipment: ["dumbbells"], commonMistakes: "Letting the front knee drift far past the toes while the torso leans forward.")),
        SeedEntry(matchers: ["leg extension"],
            fr: ExerciseExplanation(steps: ["Règle la machine pour que l'axe de rotation soit aligné avec le genou, dos calé.", "Étends les jambes jusqu'en haut, marque une pause de contraction 1 seconde.", "Redescends de façon contrôlée sur 2 secondes.", "Reste en tension sans laisser claquer la charge en bas."], equipment: ["machine leg extension"], commonMistakes: "Verrouiller le genou en hyperextension brutale en position haute."),
            en: ExerciseExplanation(steps: ["Set the machine so the pivot lines up with the knee, back supported.", "Extend the legs to the top, hold a 1-second contraction.", "Lower under control over 2 seconds.", "Stay under tension without letting the weight slam down."], equipment: ["leg extension machine"], commonMistakes: "Snapping the knee into hard hyperextension at the top position.")),
        SeedEntry(matchers: ["test 1rm", "1rm", "amrap", "top set", "test max", "circuit bilan"],
            fr: ExerciseExplanation(steps: ["Échauffe-toi progressivement par paliers de charge avant le set de test.", "Sur la tentative lourde, garde une technique impeccable et un gainage solide.", "Arrête la série dès que la forme se dégrade nettement (arrondi du dos, perte d'alignement).", "Repose-toi pleinement entre les tentatives et note ton résultat."], equipment: ["barre", "rack"], commonMistakes: "Pousser une tentative au-delà d'une technique propre pour grappiller une répétition."),
            en: ExerciseExplanation(steps: ["Warm up progressively through loading steps before the test set.", "On the heavy attempt, keep technique clean and bracing solid.", "Stop the set as soon as form clearly breaks down (back rounding, loss of alignment).", "Rest fully between attempts and record your result."], equipment: ["barbell", "rack"], commonMistakes: "Pushing an attempt past clean technique just to grab one more rep.")),
        SeedEntry(matchers: ["goblet squat", "goblet"],
            fr: ExerciseExplanation(steps: ["Tiens un haltère verticalement à deux mains contre le sternum, pieds largeur d'épaules.", "Le contrepoids devant t'aide à garder le buste droit : descends en reculant les fesses et en gardant la poitrine haute.", "Vise cuisses parallèles au sol, genoux dans l'axe des orteils.", "Remonte en poussant le sol, garde les coudes proches du corps tout du long."], equipment: ["haltère"], commonMistakes: "Laisser le buste basculer en avant et perdre le placement vertical du tronc."),
            en: ExerciseExplanation(steps: ["Hold a dumbbell vertically with both hands against the sternum, feet shoulder-width.", "The front counterweight helps keep the torso upright: lower by sending the glutes back and keeping the chest tall.", "Aim for thighs parallel to the floor, knees tracking over the toes.", "Stand back up by pushing the floor away, keep the elbows close to the body throughout."], equipment: ["dumbbell"], commonMistakes: "Letting the torso tip forward and losing the upright trunk position.")),
        SeedEntry(matchers: ["hip thrust", "glute bridge", "pont fessier"],
            fr: ExerciseExplanation(steps: ["Cale le haut du dos contre un banc, pose la charge sur le bassin avec un coussin, pieds bien plantés.", "Pousse le bassin vers le plafond en poussant sur les talons.", "Serre les fessiers 1 seconde en haut, tronc et cuisses alignés à l'horizontale.", "Garde les genoux dans l'axe, redescends de façon contrôlée."], equipment: ["banc", "barre", "haltère"], commonMistakes: "Cambrer le bas du dos en haut au lieu de finir le mouvement par les fessiers."),
            en: ExerciseExplanation(steps: ["Rest the upper back against a bench, place the load on the hips with a pad, feet planted firmly.", "Drive the hips toward the ceiling by pushing through the heels.", "Squeeze the glutes for 1 second at the top, trunk and thighs aligned horizontally.", "Keep the knees tracking outward, lower under control."], equipment: ["bench", "barbell", "dumbbell"], commonMistakes: "Arching the lower back at the top instead of finishing the movement with the glutes.")),
        SeedEntry(matchers: ["lat pulldown", "lat pull"],
            fr: ExerciseExplanation(steps: ["Saisis la barre en pronation, cale les cuisses sous les coussins, buste légèrement incliné en arrière.", "Engage les omoplates, puis tire la barre vers le haut du sternum.", "Marque une pause 1 seconde en serrant les omoplates.", "Reviens de façon contrôlée jusqu'aux bras tendus."], equipment: ["machine lat pulldown"], commonMistakes: "Se balancer fortement en arrière pour tirer avec le poids du corps."),
            en: ExerciseExplanation(steps: ["Grip the bar overhand, wedge the thighs under the pads, torso leaning slightly back.", "Engage the shoulder blades, then pull the bar toward the upper sternum.", "Hold a 1-second pause while squeezing the shoulder blades.", "Return under control to straight arms."], equipment: ["lat pulldown machine"], commonMistakes: "Swinging far back to pull with body momentum.")),
        SeedEntry(matchers: ["pallof press", "pallof"],
            fr: ExerciseExplanation(steps: ["Règle un câble à hauteur du sternum, place-toi de profil et saisis la poignée à deux mains.", "Amène la poignée devant la poitrine, puis presse les bras tendus devant toi.", "Résiste à la rotation du tronc imposée par le câble, bassin et épaules fixes.", "Reviens contrôlé, puis change de côté."], equipment: ["câble", "poulie"], commonMistakes: "Laisser le tronc tourner vers le câble au lieu de résister à la rotation."),
            en: ExerciseExplanation(steps: ["Set a cable at sternum height, stand sideways and grab the handle with both hands.", "Bring the handle in front of the chest, then press the arms straight out in front.", "Resist the trunk rotation pulled by the cable, hips and shoulders fixed.", "Return under control, then switch sides."], equipment: ["cable", "pulley"], commonMistakes: "Letting the trunk rotate toward the cable instead of resisting the rotation.")),
        SeedEntry(matchers: ["calf raise", "calf raises", "mollet"],
            fr: ExerciseExplanation(steps: ["Place l'avant des pieds sur le rebord d'une marche ou de la plateforme, talons dans le vide.", "Descends les talons sous le niveau pour étirer le mollet.", "Monte sur la pointe des pieds en amplitude complète, pause 1 seconde en haut.", "Redescends de façon contrôlée, sans rebond."], equipment: ["plateforme", "machine"], commonMistakes: "Faire de petits rebonds rapides au lieu d'une amplitude complète contrôlée."),
            en: ExerciseExplanation(steps: ["Place the balls of the feet on the edge of a step or platform, heels hanging off.", "Drop the heels below the level to stretch the calf.", "Rise onto the toes through the full range, pause 1 second at the top.", "Lower under control, no bouncing."], equipment: ["platform", "machine"], commonMistakes: "Doing fast little bounces instead of a controlled full range of motion.")),
        SeedEntry(matchers: ["bench press", "bench"],
            fr: ExerciseExplanation(steps: ["Allonge-toi, yeux sous la barre, prise un peu plus large que les épaules.", "Rétracte et abaisse les omoplates pour créer une base stable, pieds plantés au sol.", "Descends la barre vers le bas du sternum, coudes à environ 45° du tronc, pas écartés à 90°.", "Pousse la barre vers le haut en gardant les omoplates serrées tout du long."], equipment: ["barre", "banc"], commonMistakes: "Écarter les coudes à 90° du tronc, ce qui sollicite davantage l'avant de l'épaule."),
            en: ExerciseExplanation(steps: ["Lie down, eyes under the bar, grip slightly wider than the shoulders.", "Retract and depress the shoulder blades to build a stable base, feet planted on the floor.", "Lower the bar toward the lower sternum, elbows around 45° from the trunk, not flared to 90°.", "Press the bar up while keeping the shoulder blades squeezed throughout."], equipment: ["barbell", "bench"], commonMistakes: "Flaring the elbows to 90° from the trunk, which loads the front of the shoulder more.")),
        SeedEntry(matchers: ["hammer curl"],
            fr: ExerciseExplanation(steps: ["Tiens les haltères en prise neutre, paumes face à face, coudes proches du tronc.", "Fléchis les coudes en gardant la prise neutre tout du long.", "Garde le buste immobile, sans balancement.", "Contrôle la descente sur 2 secondes."], equipment: ["haltères"], commonMistakes: "Tourner les poignets en supination au lieu de garder la prise neutre."),
            en: ExerciseExplanation(steps: ["Hold the dumbbells with a neutral grip, palms facing each other, elbows close to the trunk.", "Bend the elbows while keeping the neutral grip throughout.", "Keep the torso still, no swinging.", "Control the descent over 2 seconds."], equipment: ["dumbbells"], commonMistakes: "Rotating the wrists into supination instead of keeping the neutral grip.")),
        SeedEntry(matchers: ["leg press"],
            fr: ExerciseExplanation(steps: ["Place les pieds sur la plateforme, largeur d'épaules, dos et bassin bien collés au siège.", "Descends de façon contrôlée jusqu'à environ 90° aux genoux.", "Pousse via les talons sans verrouiller brusquement les genoux en haut.", "Garde le bassin en contact avec le siège tout du long."], equipment: ["machine leg press"], commonMistakes: "Descendre si bas que le bassin se décolle du siège et que le bas du dos s'arrondit."),
            en: ExerciseExplanation(steps: ["Place the feet on the platform, shoulder-width, back and hips firmly against the seat.", "Lower under control until the knees reach about 90°.", "Press through the heels without snapping the knees into lockout at the top.", "Keep the hips in contact with the seat throughout."], equipment: ["leg press machine"], commonMistakes: "Lowering so far that the hips lift off the seat and the lower back rounds.")),
        SeedEntry(matchers: ["box jump", "box jumps"],
            fr: ExerciseExplanation(steps: ["Place-toi face à une box de 40-50 cm, pieds largeur d'épaules.", "Fléchis légèrement les genoux et balance les bras pour armer le saut.", "Saute et atterris en demi-squat souple, des deux pieds, au centre de la box.", "Redescends en marchant (un pied après l'autre), sans sauter depuis la box."], equipment: ["box"], commonMistakes: "Sauter depuis la box pour redescendre au lieu de descendre en marchant."),
            en: ExerciseExplanation(steps: ["Stand facing a 40-50 cm box, feet shoulder-width.", "Bend the knees slightly and swing the arms to load the jump.", "Jump and land in a soft half-squat, both feet, in the center of the box.", "Step back down one foot at a time, without jumping off the box."], equipment: ["box"], commonMistakes: "Jumping off the box to get down instead of stepping down.")),
        SeedEntry(matchers: ["face pull"],
