            en: ExerciseExplanation(steps: ["Set a rope on a pulley at face or forehead height, grab each end.", "Pull the hands toward the ears while spreading the rope apart.", "Finish in external rotation, thumbs back, hands above the shoulders.", "Return under control, shoulder blades sliding forward."], equipment: ["pulley", "rope"], commonMistakes: "Pulling too low toward the chest instead of aiming at the face with external rotation.")),
        SeedEntry(matchers: ["leg curl"],
            fr: ExerciseExplanation(steps: ["Installe-toi sur la machine, l'arrière des chevilles contre le rouleau.", "Fléchis les genoux pour amener les talons vers les fessiers, contraction max en fin de course.", "Garde le pied en flexion dorsale pour mieux cibler les ischio-jambiers.", "Redescends lentement sur 2 à 3 secondes."], equipment: ["machine leg curl"], commonMistakes: "Décoller le bassin pour aider le mouvement au lieu d'isoler les ischio-jambiers."),
            en: ExerciseExplanation(steps: ["Set up on the machine with the back of the ankles against the roller.", "Bend the knees to bring the heels toward the glutes, peak contraction at the end of the range.", "Keep the foot dorsiflexed to better target the hamstrings.", "Lower slowly over 2 to 3 seconds."], equipment: ["leg curl machine"], commonMistakes: "Lifting the hips to assist the movement instead of isolating the hamstrings.")),
        SeedEntry(matchers: ["pull-up", "pull up", "pull-ups", "traction"],
            fr: ExerciseExplanation(steps: ["Saisis la barre en pronation, mains un peu plus larges que les épaules, bras complètement tendus (dead hang).", "Engage d'abord les omoplates (abaisse-les), puis tire jusqu'au menton au-dessus de la barre.", "Évite tout balancement (kipping), reste gainé.", "Redescends de façon contrôlée jusqu'aux bras quasi tendus, amplitude complète."], equipment: ["barre de traction", "bande d'assistance"], commonMistakes: "Écourter l'amplitude en bas au lieu de redescendre bras quasi tendus à chaque rep."),
            en: ExerciseExplanation(steps: ["Grip the bar overhand, hands slightly wider than the shoulders, arms fully extended (dead hang).", "Engage the shoulder blades first (depress them), then pull until the chin is above the bar.", "Avoid any swinging (kipping), stay braced.", "Lower under control to nearly straight arms, full range of motion."], equipment: ["pull-up bar", "assistance band"], commonMistakes: "Cutting the range short at the bottom instead of lowering to nearly straight arms each rep.")),
        SeedEntry(matchers: ["bird-dog", "bird dog"],
            fr: ExerciseExplanation(steps: ["À quatre pattes, mains sous les épaules et genoux sous les hanches, dos neutre.", "Étends simultanément le bras opposé et la jambe opposée jusqu'à l'horizontale.", "Tiens 2 secondes en gardant le bassin stable, sans rotation.", "Reviens contrôlé et alterne les côtés."], equipment: ["tapis"], commonMistakes: "Laisser le bassin basculer ou tourner en tendant les membres."),
            en: ExerciseExplanation(steps: ["On all fours, hands under the shoulders and knees under the hips, neutral back.", "Simultaneously extend the opposite arm and opposite leg to horizontal.", "Hold 2 seconds while keeping the hips stable, no rotation.", "Return under control and alternate sides."], equipment: ["mat"], commonMistakes: "Letting the hips tilt or rotate as the limbs extend.")),
        SeedEntry(matchers: ["dead bug"],
            fr: ExerciseExplanation(steps: ["Allongé sur le dos, bras tendus vers le plafond, genoux fléchis à 90°.", "Descends le bras opposé et la jambe opposée vers le sol en expirant lentement.", "Garde le bas du dos plaqué au sol tout du long.", "Reviens et alterne les côtés."], equipment: ["tapis"], commonMistakes: "Laisser le bas du dos se décoller du sol en descendant les membres."),
            en: ExerciseExplanation(steps: ["Lie on the back, arms extended toward the ceiling, knees bent at 90°.", "Lower the opposite arm and opposite leg toward the floor while exhaling slowly.", "Keep the lower back pressed into the floor throughout.", "Return and alternate sides."], equipment: ["mat"], commonMistakes: "Letting the lower back lift off the floor as the limbs lower.")),
        SeedEntry(matchers: ["pompes", "pompe", "push-up", "push up", "pushup"],
            fr: ExerciseExplanation(steps: ["Mains sous les épaules, légèrement plus larges, corps aligné de la tête aux talons (ou aux genoux en régression).", "Descends de façon contrôlée, coudes à environ 45° du tronc.", "Descends jusqu'à la poitrine proche du sol, gainage maintenu.", "Pousse pour remonter sans laisser les hanches s'affaisser."], equipment: [], commonMistakes: "Laisser le bassin s'affaisser ou monter en cloche au lieu de garder le corps aligné."),
            en: ExerciseExplanation(steps: ["Hands under the shoulders, slightly wider, body aligned from head to heels (or knees as a regression).", "Lower under control, elbows around 45° from the trunk.", "Lower until the chest is near the floor, bracing held.", "Press back up without letting the hips sag."], equipment: [], commonMistakes: "Letting the hips sag or pike up instead of keeping the body in a straight line.")),
        SeedEntry(matchers: ["dips", "dip"],
            fr: ExerciseExplanation(steps: ["Place-toi entre deux barres parallèles, bras tendus, corps légèrement penché en avant.", "Descends de façon contrôlée, coudes proches du corps, jusqu'à l'épaule au niveau du coude.", "Pousse pour remonter jusqu'aux bras tendus.", "Garde les omoplates engagées tout du long."], equipment: ["barres parallèles", "ceinture de lest"], commonMistakes: "Descendre bien plus bas que la mobilité de l'épaule, ce qui charge l'avant de l'articulation."),
            en: ExerciseExplanation(steps: ["Set up between two parallel bars, arms straight, torso leaning slightly forward.", "Lower under control, elbows close to the body, until the shoulder reaches the elbow level.", "Press back up to straight arms.", "Keep the shoulder blades engaged throughout."], equipment: ["parallel bars", "weight belt"], commonMistakes: "Lowering well past the shoulder's range, which loads the front of the joint.")),

        // MARK: hiit (36)
        SeedEntry(matchers: ["repos actif", "repos inter-bloc", "récup inter", "recup inter", "walking-recovery", "repos inter-bloc avec hydratation", "cooldown actif", "marche active"],
            fr: ExerciseExplanation(steps: ["Marche lentement sur place ou autour de toi, sans à-coup.", "Respire profondément par le nez pour retrouver un souffle confortable.", "Hydrate-toi par petites gorgées si une quantité est indiquée.", "Reprends le bloc suivant quand tu peux à nouveau prononcer une phrase entière sans halètement ; ce repos fait partie de la séance."], equipment: [], commonMistakes: "Supprimer ou écourter ce repos alors qu'il fait partie intégrante de l'entraînement."),
            en: ExerciseExplanation(steps: ["Walk slowly in place or around you, smoothly.", "Breathe deeply through the nose to find a comfortable rhythm again.", "Sip water if an amount is indicated.", "Start the next block once you can say a full sentence again without gasping; this rest is part of the session."], equipment: [], commonMistakes: "Skipping or cutting this rest short when it is a core part of the training.")),
        SeedEntry(matchers: ["activation préventive", "activation neuromusculaire", "renforcement préventif", "activation"],
            fr: ExerciseExplanation(steps: ["Enchaîne des mouvements légers pour réveiller les muscles : squat-air lents, push-up genoux, mountain climbers lents.", "Ajoute quelques montées de mollets et tibialis pour préparer les chevilles.", "Reste à intensité modérée, le but est de réveiller les patterns, pas de fatiguer.", "Respire régulièrement et augmente progressivement le rythme vers la séance."], equipment: [], commonMistakes: "Aller trop fort dès l'activation et arriver fatigué sur le bloc principal."),
            en: ExerciseExplanation(steps: ["Flow through light moves to wake up the muscles: slow air squats, knee push-ups, slow mountain climbers.", "Add a few calf and tibialis raises to prepare the ankles.", "Keep the intensity moderate; the goal is to wake the patterns, not to fatigue.", "Breathe steadily and gradually build the pace toward the session."], equipment: [], commonMistakes: "Going too hard during the warm-up and reaching the main block already tired.")),
        SeedEntry(matchers: ["calibration grille rpe", "rappel grille rpe", "grille rpe", "calibration", "rpe hiit", "checklist", "bilan plan", "drill double-unders", "drills atterrissage"],
            fr: ExerciseExplanation(steps: ["Prends une minute pour relire l'échelle d'effort RPE de la séance.", "Repère tes repères : RPE 6-7 = échauffé, tu sors une phrase complète ; RPE 8-9 = soutenu, 2-3 mots possibles entre deux respirations.", "RPE 10 = effort maximal sur quelques secondes ; RPE 1-2 = repos quasi complet.", "Garde ces repères en tête pour ajuster ton intensité round par round."], equipment: [], commonMistakes: "Confondre intensité maximale et perte de forme : la cadence se règle, la technique reste propre."),
            en: ExerciseExplanation(steps: ["Take a minute to review the session's RPE effort scale.", "Anchor your markers: RPE 6-7 = warmed up, full sentence possible; RPE 8-9 = sustained, 2-3 words between breaths.", "RPE 10 = maximal effort for a few seconds; RPE 1-2 = near-full rest.", "Keep these markers in mind to adjust your intensity round by round."], equipment: [], commonMistakes: "Confusing maximal intensity with loss of form: pace the cadence, keep the technique clean.")),
        SeedEntry(matchers: ["core gainage", "planche ventrale", "core final", "core finisher", "core finis", "gainage", "planche", "core léger", "core gainage avancé", "core gainage pic"],
            fr: ExerciseExplanation(steps: ["Pose les avant-bras au sol, coudes juste sous les épaules, mains relâchées.", "Tends les jambes derrière toi en appui sur la pointe des pieds, corps aligné des chevilles aux épaules.", "Serre les fessiers et rentre légèrement le bassin pour garder le bas du dos plat, sans creuser.", "Engage les abdos comme si tu encaissais une légère poussée sur le ventre, respiration calme et continue.", "Tiens la durée prévue ; quand l'alignement bassin-côtes-épaules se relâche, repose-toi."], equipment: ["tapis"], commonMistakes: "Laisser le bassin s'affaisser ou le remonter trop haut casse l'alignement."),
            en: ExerciseExplanation(steps: ["Set the forearms on the floor with elbows directly under the shoulders, hands relaxed.", "Extend the legs behind, weight on the toes, body in one line from ankles to shoulders.", "Squeeze the glutes and gently tuck the pelvis to keep the lower back flat, no arching.", "Brace the abs as if bracing for a light tap on the stomach, breathing calm and steady.", "Hold the planned time; when the pelvis-ribs-shoulders line breaks down, rest."], equipment: ["mat"], commonMistakes: "Letting the hips sag or pike up too high breaks the straight-line position.")),
        SeedEntry(matchers: ["routine mobilité", "mobilité dynamique", "mobilite dynamique", "mobilité globale", "mobilité complète", "mobilité longue", "mobilité hanche", "mobilité finale", "mobilité"],
            fr: ExerciseExplanation(steps: ["Enchaîne des mouvements lents et amples : cercles de hanches, fente basse tenue, deep squat hold, cercles de chevilles.", "Ajoute un étirement des mollets debout et un étirement du piriforme au sol, quelques secondes par côté.", "Reste sur des amplitudes confortables, sans forcer ni chercher l'intensité.", "Respire calmement et garde un relâchement sur toute la routine."], equipment: ["tapis"], commonMistakes: "Forcer une amplitude extrême au lieu de rester sur un mouvement souple et contrôlé."),
            en: ExerciseExplanation(steps: ["Flow through slow, full-range moves: hip circles, low lunge holds, deep squat holds, ankle circles.", "Add a standing calf stretch and a floor piriformis stretch, a few seconds per side.", "Stay within comfortable ranges, without forcing or chasing intensity.", "Breathe calmly and stay relaxed through the whole routine."], equipment: ["mat"], commonMistakes: "Forcing an extreme range instead of staying with a smooth, controlled movement.")),
        SeedEntry(matchers: ["mountain climbers", "mountain climber"],
            fr: ExerciseExplanation(steps: ["Place-toi en position de planche haute, mains sous les épaules, corps gainé.", "Ramène un genou vers la poitrine puis l'autre en alternant, hanches stables.", "Garde le dos plat et les fessiers engagés, sans creuser le bas du dos.", "Adapte la cadence : lente et contrôlée ou soutenue selon le bloc prévu."], equipment: [], commonMistakes: "Laisser les hanches monter trop haut ou le bas du dos se creuser casse le gainage."),
            en: ExerciseExplanation(steps: ["Set up in a high plank, hands under the shoulders, body braced.", "Drive one knee toward the chest then the other, alternating, hips stable.", "Keep the back flat and the glutes engaged, no sagging in the lower back.", "Match the cadence: slow and controlled or brisk depending on the planned block."], equipment: [], commonMistakes: "Letting the hips pike up or the lower back sag breaks the bracing.")),
        SeedEntry(matchers: ["thruster", "dumbbell thruster", "db thruster"],
            fr: ExerciseExplanation(steps: ["Tiens les haltères en front rack, sur le dessus des épaules, coudes hauts.", "Descends en front squat, cuisses parallèles, talons au sol, dos droit.", "Remonte explosivement et enchaîne en poussant les haltères au-dessus de la tête (push-press).", "Verrouille bras tendus en haut, cervicales neutres, puis reviens en front rack pour le rep suivant."], equipment: ["haltères"], commonMistakes: "Séparer le squat et la poussée au lieu d'enchaîner l'élan des jambes vers le haut."),
            en: ExerciseExplanation(steps: ["Hold the dumbbells in the front rack on top of the shoulders, elbows high.", "Lower into a front squat, thighs parallel, heels down, back upright.", "Drive up explosively and press the dumbbells overhead in one motion (push-press).", "Lock out arms overhead, neck neutral, then return to the front rack for the next rep."], equipment: ["dumbbells"], commonMistakes: "Splitting the squat and the press instead of chaining the leg drive into the press.")),
        SeedEntry(matchers: ["rdl", "romanian deadlift", "hip hinge"],
            fr: ExerciseExplanation(steps: ["Debout, pieds largeur hanches, charge devant les cuisses, dos plat et poitrine ouverte.", "Recule le bassin et laisse la charge descendre proche des jambes, genoux à peine fléchis.", "Descends jusqu'à sentir l'étirement des ischio-jambiers en gardant le dos comme une planche.", "Reviens en avançant les hanches et en serrant les fessiers, charge proche du corps."], equipment: ["haltères"], commonMistakes: "Arrondir le dos ou plier trop les genoux transforme le hinge en quart de squat."),
            en: ExerciseExplanation(steps: ["Stand feet hip-width, load in front of the thighs, back flat and chest open.", "Push the hips back and let the load travel close to the legs, knees barely bent.", "Lower until you feel the hamstrings stretch, keeping the back like a plank.", "Return by driving the hips forward and squeezing the glutes, load close to the body."], equipment: ["dumbbells"], commonMistakes: "Rounding the back or bending the knees too much turns the hinge into a quarter-squat.")),
        SeedEntry(matchers: ["power clean", "hang power clean", "hang power snatch", "power snatch"],
            fr: ExerciseExplanation(steps: ["Position de départ charge devant les cuisses (hang), pieds largeur hanches, dos plat.", "Réalise un léger hip hinge puis une extension explosive des hanches (triple extension chevilles-genoux-hanches).", "Tire la charge le long du corps et passe vite les coudes dessous pour la réceptionner en front rack.", "Réceptionne genoux légèrement fléchis, dos gainé, puis repose la charge contrôlé."], equipment: ["haltères", "barre"], commonMistakes: "Tirer avec les bras d'abord au lieu de lancer par l'extension des hanches."),
            en: ExerciseExplanation(steps: ["Start with the load in front of the thighs (hang), feet hip-width, back flat.", "Make a slight hip hinge then an explosive hip extension (triple extension of ankles-knees-hips).", "Pull the load close along the body and snap the elbows under to catch it in the front rack.", "Catch with knees slightly bent, back braced, then lower the load under control."], equipment: ["dumbbells", "barbell"], commonMistakes: "Pulling with the arms first instead of launching through hip extension.")),
        SeedEntry(matchers: ["kb swing", "kb russe", "kettlebell swing", "swing russe", "swing 1"],
            fr: ExerciseExplanation(steps: ["Place la kettlebell devant toi, pieds largeur hanches, et saisis-la à deux mains, dos plat.", "Recule le bassin (hip hinge), épaules au-dessus de la kettlebell, et balance-la sous les cuisses.", "Pousse explosivement par les hanches et serre les fessiers pour projeter la kettlebell vers l'avant.", "Laisse-la flotter jusqu'à hauteur épaule, bras tendus, corps en planche debout, sans la monter avec les bras.", "Laisse-la redescendre librement entre les cuisses et enchaîne le hinge suivant."], equipment: ["kettlebell"], commonMistakes: "Plier les genoux comme un squat ou tirer avec les bras au lieu de pousser par les hanches."),
            en: ExerciseExplanation(steps: ["Set the kettlebell ahead of you, feet hip-width, grip it with both hands, flat back.", "Push the hips back (hip hinge), shoulders over the bell, and hike it under the thighs.", "Drive explosively through the hips and squeeze the glutes to cast the bell forward.", "Let it float to shoulder height, arms straight, body in a standing plank, not lifting with the arms.", "Let it swing back freely between the thighs and chain into the next hinge."], equipment: ["kettlebell"], commonMistakes: "Squatting the movement or pulling with the arms instead of driving through the hips.")),
        SeedEntry(matchers: ["single-leg squat", "single leg squat", "split squat", "bulgare", "bulgarian", "pistol squat", "pistol"],
            fr: ExerciseExplanation(steps: ["Place le pied arrière surélevé sur une box ou un banc, pied avant bien ancré devant.", "Descends en pliant le genou avant jusqu'à cuisse parallèle, buste légèrement penché.", "Garde le genou avant aligné avec la cheville, dans l'axe du pied.", "Remonte en poussant par le talon avant ; pour le pistol, descends sur une jambe vers une chaise stable en appui main si besoin."], equipment: ["box"], commonMistakes: "Laisser le genou avant rentrer vers l'intérieur ou dépasser largement la pointe du pied."),
            en: ExerciseExplanation(steps: ["Place the rear foot elevated on a box or bench, front foot anchored ahead.", "Lower by bending the front knee until the thigh is parallel, torso slightly forward.", "Keep the front knee aligned with the ankle, tracking over the foot.", "Drive up through the front heel; for the pistol, lower on one leg toward a stable chair, using a hand for support if needed."], equipment: ["box"], commonMistakes: "Letting the front knee cave inward or shoot far past the toes.")),
        SeedEntry(matchers: ["pull-up", "pull up", "pullup", "scapular pull-up", "scapular", "db row", "ring row", "rowing erg"],
            fr: ExerciseExplanation(steps: ["Pull-up : suspends-toi à la barre, mains un peu plus larges que les épaules, gaine le tronc.", "Tire les omoplates vers le bas puis monte le menton au niveau de la barre, coudes vers le bas.", "Descends contrôlé jusqu'aux bras tendus sans te balancer.", "Alternatives : ring rows ou DB row penché si pas de barre ; scapular pull-up = déprimer les omoplates bras tendus."], equipment: ["barre de traction"], commonMistakes: "Prendre de l'élan avec les jambes au lieu de tirer avec le dos et les bras."),
            en: ExerciseExplanation(steps: ["Pull-up: hang from the bar, hands slightly wider than the shoulders, brace the torso.", "Pull the shoulder blades down then bring the chin to the bar, elbows driving down.", "Lower under control to straight arms without swinging.", "Alternatives: ring rows or bent-over DB row if no bar; scapular pull-up = depress the shoulder blades with straight arms."], equipment: ["pull-up bar"], commonMistakes: "Kipping with the legs instead of pulling with the back and arms.")),
        SeedEntry(matchers: ["tibialis raises", "tibialis raise", "tibialis"],
            fr: ExerciseExplanation(steps: ["Debout, dos contre un mur, talons à environ 30 cm du mur.", "Garde les talons au sol et lève les pointes de pieds vers les tibias (flexion dorsale de cheville).", "Monte jusqu'à l'amplitude confortable puis redescends lentement, environ 2 secondes.", "Enchaîne les répétitions sur un rythme régulier."], equipment: [], commonMistakes: "Décoller les talons du sol enlève le travail ciblé sur la face avant du tibia."),
            en: ExerciseExplanation(steps: ["Stand with your back against a wall, heels about 30 cm out from it.", "Keep the heels down and lift the toes toward the shins (ankle dorsiflexion).", "Raise to a comfortable range then lower slowly, about 2 seconds.", "Chain the reps at a steady pace."], equipment: [], commonMistakes: "Lifting the heels off the floor removes the targeted work on the front of the shin.")),
        SeedEntry(matchers: ["rowing erg easy", "vélo z2", "z2 endurance", "endurance"],
            fr: ExerciseExplanation(steps: ["Installe-toi sur le rameur ou le vélo, posture droite, prise détendue.", "Trouve une allure régulière en zone aérobie facile où tu peux tenir une phrase complète.", "Garde une cadence moyenne et constante sur toute la durée.", "Vise un effort confortable et soutenu plutôt que des à-coups."], equipment: ["rameur"], commonMistakes: "Partir trop vite au lieu de tenir une allure conversationnelle constante."),
            en: ExerciseExplanation(steps: ["Set up on the rower or bike, upright posture, relaxed grip.", "Find a steady easy aerobic pace where you can hold a full sentence.", "Keep a moderate, constant cadence for the whole duration.", "Aim for a comfortable, sustained effort rather than surges."], equipment: ["rower"], commonMistakes: "Starting too fast instead of holding a steady conversational pace.")),
        SeedEntry(matchers: ["turkish get-up", "turkish get up", "get-up", "get up"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le dos, kettlebell tendue vers le plafond au bout d'un bras verrouillé.", "Roule sur le coude du même côté, puis sur la main, en gardant les yeux sur la kettlebell.", "Monte le bassin en pont, passe la jambe en position genou à terre puis en fente.", "Lève-toi debout en gardant le bras tendu, puis redescends en repassant par chaque position."], equipment: ["kettlebell"], commonMistakes: "Quitter la kettlebell des yeux fait perdre la stabilité de l'épaule en cours de montée."),
            en: ExerciseExplanation(steps: ["Lie on your back, kettlebell pressed toward the ceiling on one locked-out arm.", "Roll onto the elbow of the same side, then onto the hand, keeping your eyes on the bell.", "Bridge the hips up, sweep the leg through to a kneeling position then a lunge.", "Stand up with the arm locked out, then reverse through each position to the floor."], equipment: ["kettlebell"], commonMistakes: "Taking the eyes off the kettlebell loses shoulder stability through the stand.")),
        SeedEntry(matchers: ["bloc 30 · 60", "bloc 30 · 30", "bloc 40 · 20", "30 · 60", "30 · 30", "40 · 20", "bloc 1", "bloc 2", "bloc 3", "bloc finisseur", "bloc test", "bloc 30", "bloc 40"],
            fr: ExerciseExplanation(steps: ["Format work-rest : alterne une phase d'effort et une phase de repos selon le ratio annoncé (par exemple 30 secondes effort, 60 secondes repos).", "Lance un timer audible et installe-toi sur le mouvement du round.", "Sur la phase d'effort, garde une cadence soutenue et une bonne forme ; sur le repos, marche lentement et respire profondément.", "Quand le repos raccourcit (ratio plus serré), sois plus économe sur l'effort pour tenir tous les rounds."], equipment: [], commonMistakes: "Garder la même intensité sur un ratio plus serré au lieu d'ajuster pour tenir la durée."),
            en: ExerciseExplanation(steps: ["Work-rest format: alternate a work phase and a rest phase per the announced ratio (for example 30 seconds work, 60 seconds rest).", "Set an audible timer and get set on the round's movement.", "On the work phase, keep a strong cadence and good form; on the rest, walk slowly and breathe deeply.", "When the rest gets shorter (tighter ratio), pace the effort more so you can hold every round."], equipment: [], commonMistakes: "Keeping the same intensity on a tighter ratio instead of adjusting to last the duration.")),
        SeedEntry(matchers: ["jumping jacks", "jumping jack", "step-jacks", "step jacks", "step-jack"],
            fr: ExerciseExplanation(steps: ["Debout, pieds joints, bras le long du corps.", "Écarte les pieds en sautant tout en levant les bras au-dessus de la tête.", "Reviens à la position de départ d'un mouvement fluide et continu.", "Version step-jacks sans saut : pose un pied sur le côté pendant que tu lèves les bras, puis l'autre, sans décoller du sol."], equipment: [], commonMistakes: "Atterrir jambes raides au lieu de réceptionner sur l'avant du pied genoux souples."),
            en: ExerciseExplanation(steps: ["Stand with feet together, arms by the sides.", "Jump the feet apart while raising the arms overhead.", "Return to the start in one smooth, continuous motion.", "No-jump step-jacks version: step one foot out as you raise the arms, then the other, staying grounded."], equipment: [], commonMistakes: "Landing with stiff legs instead of catching on the forefoot with soft knees.")),
        SeedEntry(matchers: ["wall ball", "slam ball", "medicine-ball", "medicine ball"],
            fr: ExerciseExplanation(steps: ["Wall ball : tiens le medicine-ball contre la poitrine, descends en squat profond.", "Remonte explosivement et lance le ballon vers une cible haute sur le mur (environ 3 m).", "Réceptionne le ballon et enchaîne directement le squat suivant.", "Slam ball : lève le ballon au-dessus de la tête puis claque-le au sol avec force, ramasse et recommence."], equipment: ["medicine-ball"], commonMistakes: "Lancer avec les bras seuls au lieu d'utiliser l'élan des jambes en sortie de squat."),
            en: ExerciseExplanation(steps: ["Wall ball: hold the medicine ball against the chest, lower into a deep squat.", "Drive up explosively and throw the ball to a high target on the wall (about 3 m).", "Catch the ball and flow straight into the next squat.", "Slam ball: raise the ball overhead then slam it to the floor with force, pick up and repeat."], equipment: ["medicine ball"], commonMistakes: "Throwing with the arms alone instead of using the leg drive out of the squat.")),
        SeedEntry(matchers: ["double-unders", "double unders", "double-under"],
            fr: ExerciseExplanation(steps: ["Tiens la corde, poignets bas près des hanches, regard devant.", "Saute droit et compact, jambes peu fléchies, en restant sur l'avant des pieds.", "Donne deux tours de corde par les poignets pendant un seul saut un peu plus haut.", "En développement : enchaîne des sauts simples rapides et insère une double tous les quelques sauts."], equipment: ["corde à sauter"], commonMistakes: "Plier les genoux en arrière pour gagner du temps au lieu de tourner plus vite les poignets."),
            en: ExerciseExplanation(steps: ["Hold the rope, wrists low near the hips, gaze ahead.", "Jump straight and compact, legs barely bent, staying on the forefoot.", "Pass the rope twice with the wrists during a single slightly higher jump.", "While learning: chain fast single jumps and slot in one double every few jumps."], equipment: ["jump rope"], commonMistakes: "Tucking the heels back to buy time instead of spinning the wrists faster.")),
        SeedEntry(matchers: ["dead bug", "bird-dog", "bird dog", "hollow rocks", "hollow rock"],
            fr: ExerciseExplanation(steps: ["Dead bug : allonge-toi sur le dos, bras vers le plafond, jambes pliées à 90° au-dessus du bassin.", "Tends lentement le bras et la jambe opposés vers le sol en gardant le bas du dos collé au tapis.", "Bird-dog : à quatre pattes, tends le bras et la jambe opposés à l'horizontale, dos plat.", "Reviens contrôlé sans tourner le bassin, alterne les côtés sur le rythme prévu."], equipment: ["tapis"], commonMistakes: "Cambrer le bas du dos quand le membre s'éloigne fait perdre le travail anti-extension."),
            en: ExerciseExplanation(steps: ["Dead bug: lie on your back, arms toward the ceiling, legs bent 90° over the hips.", "Slowly extend the opposite arm and leg toward the floor, keeping the lower back pressed into the mat.", "Bird-dog: on all fours, reach the opposite arm and leg out level, back flat.", "Return under control without twisting the pelvis, alternate sides at the set pace."], equipment: ["mat"], commonMistakes: "Arching the lower back as the limb reaches out loses the anti-extension work.")),
        SeedEntry(matchers: ["squat-air", "squat air", "air squat", "goblet squat"],
            fr: ExerciseExplanation(steps: ["Place les pieds largeur d'épaules, pointes légèrement ouvertes, regard devant.", "Recule le bassin et descends jusqu'aux cuisses parallèles (ou la profondeur confortable), talons au sol.", "Garde les genoux dans l'axe des orteils, jamais rentrés vers l'intérieur.", "Remonte en poussant par les talons jusqu'à l'extension complète des hanches.", "Pour le goblet squat : tiens un haltère ou une kettlebell verticale contre la poitrine."], equipment: [], commonMistakes: "Laisser les genoux rentrer vers l'intérieur ou décoller les talons en descente."),
            en: ExerciseExplanation(steps: ["Set the feet shoulder-width, toes slightly out, gaze ahead.", "Push the hips back and lower until the thighs are parallel (or a comfortable depth), heels down.", "Keep the knees tracking over the toes, never caving inward.", "Drive up through the heels to full hip extension.", "For the goblet squat: hold a dumbbell or kettlebell vertical against the chest."], equipment: [], commonMistakes: "Letting the knees cave inward or the heels lift during the descent.")),
        SeedEntry(matchers: ["hip thrust", "glute bridge"],
            fr: ExerciseExplanation(steps: ["Glute bridge : allonge-toi sur le dos, pieds au sol largeur hanches, bras le long du corps.", "Hip thrust : cale les omoplates sur un banc bas et pose la charge sur le bassin (avec une protection souple).", "Pousse fort par les talons pour monter le bassin jusqu'à l'extension complète des hanches.", "Serre les fessiers en haut sans creuser le bas du dos, tiens 1 à 2 secondes puis redescends contrôlé."], equipment: ["haltères", "banc"], commonMistakes: "Monter en creusant le bas du dos au lieu d'activer les fessiers."),
            en: ExerciseExplanation(steps: ["Glute bridge: lie on your back, feet on the floor hip-width, arms by your sides.", "Hip thrust: rest the shoulder blades on a low bench and place the load on the hips (with soft padding).", "Push hard through the heels to lift the hips to full hip extension.", "Squeeze the glutes at the top without arching the lower back, hold 1 to 2 seconds, then lower under control."], equipment: ["dumbbells", "bench"], commonMistakes: "Rising by arching the lower back instead of activating the glutes.")),
        SeedEntry(matchers: ["sled push", "farmer carry", "sled"],
            fr: ExerciseExplanation(steps: ["Sled push : place les mains sur les montants, bras tendus, dos plat, buste incliné vers l'avant.", "Pousse par les jambes en petites foulées puissantes, sans creuser le bas du dos.", "Farmer carry : tiens un haltère lourd dans chaque main, épaules basses, tronc gainé.", "Marche droit et contrôlé sur la distance prévue, sans pencher d'un côté."], equipment: ["haltères"], commonMistakes: "Creuser le bas du dos en poussant ou en portant au lieu de garder le tronc gainé."),
            en: ExerciseExplanation(steps: ["Sled push: hands on the posts, arms straight, back flat, torso leaning forward.", "Drive with the legs in short powerful strides, no arching in the lower back.", "Farmer carry: hold a heavy dumbbell in each hand, shoulders down, torso braced.", "Walk tall and controlled over the planned distance, without leaning to one side."], equipment: ["dumbbells"], commonMistakes: "Arching the lower back while pushing or carrying instead of keeping the torso braced.")),
        SeedEntry(matchers: ["bloc tabata", "tabata 20 · 10", "tabata 20", "tabata"],
            fr: ExerciseExplanation(steps: ["Format Tabata : 20 secondes d'effort intense suivies de 10 secondes de repos, sur 6 à 8 rounds.", "Prépare un timer audible et installe-toi sur le mouvement prévu.", "Sur les 20 secondes, donne un effort soutenu et régulier ; cale-toi à l'arrêt complet sur les 10 secondes.", "Vise une cadence que tu peux tenir : si elle chute de plus de 30% sur les derniers rounds, lève le pied un peu plus tôt."], equipment: [], commonMistakes: "Partir tout-en-haut au round 1 et s'effondrer ensuite au lieu de doser sur tous les rounds."),
            en: ExerciseExplanation(steps: ["Tabata format: 20 seconds of intense work then 10 seconds of rest, over 6 to 8 rounds.", "Set an audible timer and get set on the planned movement.", "During the 20 seconds, give a strong steady effort; settle to a full stop during the 10 seconds.", "Aim for a cadence you can hold: if it drops more than 30% on the last rounds, ease off a touch sooner."], equipment: [], commonMistakes: "Going all-out on round 1 and fading after, instead of pacing across all rounds.")),
        SeedEntry(matchers: ["foam rolling", "foam roller", "auto-massage", "auto massage"],
            fr: ExerciseExplanation(steps: ["Place le foam roller sous le groupe musculaire visé (ischios, mollets, quadriceps, dorsaux).", "Roule lentement d'avant en arrière en répartissant le poids du corps, environ une minute par zone.", "Quand tu trouves un point sensible, ralentis et respire, sans appuyer en force.", "Passe d'une zone à l'autre tranquillement sur la durée prévue."], equipment: ["foam roller"], commonMistakes: "Rouler trop vite en survolant au lieu de ralentir sur chaque zone."),
            en: ExerciseExplanation(steps: ["Place the foam roller under the target muscle group (hamstrings, calves, quads, lats).", "Roll slowly back and forth, sharing your body weight, about one minute per area.", "When you find a tender spot, slow down and breathe, without pressing hard.", "Move from one area to the next calmly over the planned time."], equipment: ["foam roller"], commonMistakes: "Rolling too fast and skimming instead of slowing down on each area.")),
        SeedEntry(matchers: ["squat-jump", "squat jump", "squat-jumps", "broad jump", "depth jump", "depth drop"],
            fr: ExerciseExplanation(steps: ["Descends en squat, bassin reculé, genoux dans l'axe, regard devant.", "Remonte explosivement et décolle du sol en tendant les hanches.", "Atterris en douceur sur l'avant du pied puis tout le pied, genoux fléchis pour amortir.", "Pour le depth jump : descends de la box en step-off (pas de saut vers le bas), réceptionne genoux fléchis puis renvoie un saut court.", "Garde le dos plat tout le long du mouvement."], equipment: [], commonMistakes: "Atterrir jambes raides au lieu de réceptionner genoux fléchis pour amortir."),
            en: ExerciseExplanation(steps: ["Lower into a squat, hips back, knees tracking, gaze ahead.", "Drive up explosively and leave the floor by extending the hips.", "Land softly on the forefoot then full foot, knees bent to absorb.", "For the depth jump: step off the box (don't jump down), land with bent knees then rebound a short jump.", "Keep the back flat throughout."], equipment: [], commonMistakes: "Landing with stiff legs instead of bending the knees to absorb the impact.")),
        SeedEntry(matchers: ["box jump", "box step-up", "box step up", "step-up", "box-jump"],
            fr: ExerciseExplanation(steps: ["Place-toi face à une box stable, pieds largeur hanches, à une distance courte.", "Fléchis légèrement les genoux, balance les bras et saute sur la box.", "Réceptionne en demi-squat, genoux fléchis et souples, hanches et genoux en extension complète une fois en haut.", "Redescends en step-down (un pied après l'autre) plutôt qu'en saut, pour ménager les chevilles.", "Pour le box step-up : monte un pied puis l'autre en poussant par le talon, sans à-coup."], equipment: ["box"], commonMistakes: "Sauter pour redescendre au lieu de step-down ajoute des impacts inutiles sur chevilles et tibias."),
            en: ExerciseExplanation(steps: ["Face a stable box, feet hip-width, a short distance away.", "Bend the knees slightly, swing the arms, and jump onto the box.", "Land in a half-squat, knees bent and soft, then reach full hip and knee extension on top.", "Step down (one foot at a time) rather than jumping down to spare the ankles.", "For the box step-up: step one foot up then the other, driving through the heel, smoothly."], equipment: ["box"], commonMistakes: "Jumping down instead of stepping down adds needless impact on ankles and shins.")),
        SeedEntry(matchers: ["calf raises", "calf raise", "calf "],
            fr: ExerciseExplanation(steps: ["Debout, en appui sur les deux pieds (ou un seul pour la version unipodale), tiens un mur pour l'équilibre.", "Monte sur la pointe des pieds en poussant fort, amplitude complète de la cheville.", "Sur l'avant-pied posé sur une marche, descends lentement le talon en 3 à 4 secondes (version excentrique).", "Remonte en 1 seconde puis enchaîne sur le tempo prévu."], equipment: [], commonMistakes: "Descendre vite et rebondir au lieu de contrôler la phase excentrique lente."),
            en: ExerciseExplanation(steps: ["Stand on both feet (or one for the single-leg version), holding a wall for balance.", "Rise onto the balls of the feet with a strong push, full ankle range.", "With the forefoot on a step, lower the heel slowly over 3 to 4 seconds (eccentric version).", "Rise back in 1 second then continue at the planned tempo."], equipment: [], commonMistakes: "Dropping fast and bouncing instead of controlling the slow eccentric phase.")),
        SeedEntry(matchers: ["nordic curl", "nordic"],
            fr: ExerciseExplanation(steps: ["Agenouille-toi sur un tapis, chevilles bloquées sous un meuble bas ou tenues par un partenaire.", "Garde le corps droit de la tête aux genoux, abdos et fessiers gainés.", "Descends lentement vers l'avant en 3 à 4 secondes en retenant un maximum avec les ischio-jambiers.", "Pose les mains au sol pour amortir la fin puis repousse-toi pour revenir à la position de départ."], equipment: ["tapis"], commonMistakes: "Plier le buste au niveau des hanches au lieu de garder une ligne droite tronc-cuisses."),
            en: ExerciseExplanation(steps: ["Kneel on a mat, ankles anchored under a low piece of furniture or held by a partner.", "Keep the body straight from head to knees, abs and glutes braced.", "Lower slowly forward over 3 to 4 seconds, resisting as much as possible with the hamstrings.", "Place the hands on the floor to cushion the bottom, then push back to the start."], equipment: ["mat"], commonMistakes: "Bending at the hips instead of keeping a straight torso-to-thigh line.")),
        SeedEntry(matchers: ["side plank", "latérale", "copenhagen"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le côté, coude sous l'épaule, avant-bras au sol perpendiculaire au corps.", "Empile les pieds (ou pose le pied du dessus devant) et lève le bassin pour aligner cheville-hanche-épaule.", "Serre les obliques et les fessiers pour garder la hanche haute, sans la laisser redescendre.", "Garde la nuque dans le prolongement du dos, regard neutre devant toi.", "Tiens la durée par côté puis change."], equipment: ["tapis"], commonMistakes: "Laisser la hanche du bas s'affaisser vers le sol réduit le travail des obliques."),
            en: ExerciseExplanation(steps: ["Lie on one side, elbow under the shoulder, forearm flat and across the body.", "Stack the feet (or place the top foot forward) and lift the hips to align ankle-hip-shoulder.", "Brace the obliques and glutes to keep the hip high, without letting it drop.", "Keep the neck in line with the spine, gaze neutral ahead.", "Hold per side, then switch."], equipment: ["mat"], commonMistakes: "Letting the bottom hip drift toward the floor reduces the oblique work.")),
        SeedEntry(matchers: ["push-press", "push press"],
            fr: ExerciseExplanation(steps: ["Tiens les haltères en front rack au-dessus des épaules, pieds largeur hanches.", "Réalise un léger creux des genoux (dip), tronc vertical et gainé.", "Renvoie explosivement par les jambes (drive) pour lancer les haltères vers le haut.", "Termine bras tendus au-dessus de la tête, cervicales neutres, puis reviens contrôlé en front rack."], equipment: ["haltères"], commonMistakes: "Pencher le tronc en avant pendant le dip au lieu de rester vertical."),
            en: ExerciseExplanation(steps: ["Hold the dumbbells in the front rack above the shoulders, feet hip-width.", "Make a small knee dip, torso vertical and braced.", "Drive explosively through the legs to launch the dumbbells overhead.", "Finish arms locked out overhead, neck neutral, then return under control to the front rack."], equipment: ["dumbbells"], commonMistakes: "Leaning the torso forward during the dip instead of staying vertical.")),
        SeedEntry(matchers: ["y-raise", "y raise", "face pull"],
            fr: ExerciseExplanation(steps: ["Fixe une bande élastique à hauteur poitrine, saisis-la à deux mains.", "Face pull : tire la bande vers le menton, coudes hauts et écartés, omoplates serrées.", "Y-raise : monte les bras en forme de Y au-dessus de la tête en gardant les omoplates basses.", "Reviens lentement et contrôlé sur chaque répétition."], equipment: ["bande élastique"], commonMistakes: "Hausser les épaules vers les oreilles au lieu de garder les omoplates basses et serrées."),
            en: ExerciseExplanation(steps: ["Anchor an elastic band at chest height, grip it with both hands.", "Face pull: pull the band toward the chin, elbows high and wide, shoulder blades squeezed.", "Y-raise: raise the arms into a Y overhead while keeping the shoulder blades down.", "Return slowly and under control on each rep."], equipment: ["resistance band"], commonMistakes: "Shrugging the shoulders toward the ears instead of keeping the blades down and back.")),
        SeedEntry(matchers: ["push-up", "push up", "pushup"],
            fr: ExerciseExplanation(steps: ["Mains au sol un peu plus larges que les épaules, corps gainé en ligne des chevilles à la tête.", "Descends en pliant les coudes vers l'arrière (environ 45°), poitrine vers le sol.", "Garde les fessiers et les abdos engagés pour ne pas creuser le bas du dos.", "Repousse jusqu'à l'extension complète des bras.", "Version genoux : pose les genoux au sol en gardant la ligne cuisses-épaules."], equipment: [], commonMistakes: "Laisser le bassin s'affaisser ou écarter les coudes à 90° du tronc."),
            en: ExerciseExplanation(steps: ["Hands on the floor slightly wider than the shoulders, body braced in a line from ankles to head.", "Lower by bending the elbows back (about 45°), chest toward the floor.", "Keep the glutes and abs engaged so the lower back doesn't sag.", "Push back up to full arm extension.", "Knees version: place the knees on the floor, keeping the thigh-to-shoulder line."], equipment: [], commonMistakes: "Letting the hips sag or flaring the elbows out to 90° from the torso.")),
        SeedEntry(matchers: ["burpee"],
            fr: ExerciseExplanation(steps: ["Debout, pose les mains au sol largeur épaules et envoie les pieds en arrière en position de planche.", "Descends la poitrine, les hanches et les cuisses au sol en un seul bloc.", "Repousse, ramène les pieds vers les mains et redresse-toi en extension complète des hanches.", "Termine par un saut bras tendus au-dessus de la tête ; pour une version douce, marche les pieds plutôt que de sauter."], equipment: [], commonMistakes: "Laisser les hanches s'affaisser en planche au lieu de garder le corps gainé."),
            en: ExerciseExplanation(steps: ["From standing, place the hands on the floor shoulder-width and jump the feet back into a plank.", "Lower the chest, hips and thighs to the floor as one unit.", "Push back up, jump the feet toward the hands, and stand to full hip extension.", "Finish with a jump, arms overhead; for a gentle version, step the feet instead of jumping."], equipment: [], commonMistakes: "Letting the hips sag in the plank instead of keeping the body braced.")),
        SeedEntry(matchers: ["amrap", "cindy", "fran"],
            fr: ExerciseExplanation(steps: ["Format AMRAP (As Many Rounds As Possible) : enchaîne le maximum de tours du circuit sur le temps imparti.", "Repère bien l'ordre des mouvements du circuit avant de lancer le chrono.", "Pars autour de 70-75% de ton allure max sur les premiers tours pour tenir jusqu'au bout.", "Garde une cadence régulière et note ton nombre de tours pour comparer aux prochaines séances."], equipment: [], commonMistakes: "Partir trop vite les premières minutes et craquer avant la fin du temps imparti."),
            en: ExerciseExplanation(steps: ["AMRAP format (As Many Rounds As Possible): chain as many circuit rounds as you can in the set time.", "Note the order of the circuit movements before starting the clock.", "Start around 70-75% of your max pace on the first rounds to last the whole time.", "Keep a steady cadence and log your round count to compare with future sessions."], equipment: [], commonMistakes: "Going too fast in the early minutes and burning out before the time is up.")),
        SeedEntry(matchers: ["emom"],
            fr: ExerciseExplanation(steps: ["Format EMOM (Every Minute On the Minute) : au top de chaque minute, tu réalises le nombre de reps prévu.", "Le temps restant dans la minute sert de récupération avant la minute suivante.", "Choisis une cadence qui te laisse un peu de repos chaque minute, surtout en début de bloc.", "Si tu n'arrives plus à finir les reps dans la minute, réduis le nombre de reps plutôt que de tout enchaîner sans répit."], equipment: [], commonMistakes: "Aller trop vite les premières minutes et perdre toute la récup en fin de bloc."),
            en: ExerciseExplanation(steps: ["EMOM format (Every Minute On the Minute): at the top of each minute, do the planned number of reps.", "The time left in the minute is your rest before the next minute.", "Pick a cadence that leaves a little rest each minute, especially early in the block.", "If you can no longer finish the reps within the minute, reduce the reps rather than running with no rest."], equipment: [], commonMistakes: "Going too fast in the first minutes and losing all the rest by the end of the block.")),

        // MARK: tennis (35)
        SeedEntry(matchers: ["set partiel", "set d'entraînement", "set entraînement", "set entrainement", "set complet", "match-test", "match-simulation", "match tournoi", "tie-break", "tie break", "drill panier match-simulation", "11 points"],
            fr: ExerciseExplanation(steps: ["Joue les points en conditions réelles : score officiel, changements de côté, service alterné.", "Mets en place un rituel pré-service court et un rituel entre les points de 16 à 20 secondes.", "Sur chaque échange, applique tes patterns travaillés plutôt que d'improviser.", "Reste focalisé point par point, sans te projeter sur le score global.", "Note tes repères après coup : régularité, gestion des points sous pression, dérive technique."], equipment: ["raquette", "balles", "court", "partenaire"], commonMistakes: "Enchaîner les points sans rituel ni replacement mental, ce qui fait perdre la concentration."),
            en: ExerciseExplanation(steps: ["Play points in real conditions: official score, side changes, alternating serve.", "Set up a short pre-serve ritual and a 16 to 20 second between-points ritual.", "On each rally, apply your trained patterns rather than improvising.", "Stay focused point by point, without projecting onto the overall score.", "Note your markers afterward: consistency, handling pressure points, technical drift."], equipment: ["racket", "balls", "court", "partner"], commonMistakes: "Rushing through points with no ritual or mental reset, which costs concentration.")),
        SeedEntry(matchers: ["service ciblé", "service cible", "service en cible", "service variété", "service variete", "service en cible — précision", "service précision", "service precision", "placement t et extérieur"],
            fr: ExerciseExplanation(steps: ["Pose des cônes ou repères dans les zones visées (T, extérieur, corps) de chaque carré.", "Garde le même rituel et le même lancer quelle que soit la cible pour ne pas te trahir.", "Pour le slice, brosse le côté de la balle ; pour le kick, brosse de bas en haut et de gauche à droite.", "Compte les services réussis en zone et note ton pourcentage par série pour suivre tes progrès."], equipment: ["raquette", "balles", "cônes ou repères"], commonMistakes: "Changer son lancer selon la cible visée, ce qui annonce la direction à l'adversaire."),
            en: ExerciseExplanation(steps: ["Place cones or markers in the target zones (T, wide, body) of each service box.", "Keep the same ritual and the same toss whatever the target so you don't telegraph it.", "For slice, brush the side of the ball; for kick, brush low to high and left to right.", "Count serves landing in the zone and note your percentage per set to track progress."], equipment: ["racket", "balls", "cones or markers"], commonMistakes: "Changing the toss depending on the target, which signals the direction to the opponent.")),
        SeedEntry(matchers: ["coup droit", "forehand", "cross forehand", "drill cross forehand", "drill mur coup droit", "cross régulier coup droit"],
            fr: ExerciseExplanation(steps: ["Au signal de la balle, tourne hanches et épaules ensemble (unit turn) en armant la raquette d'un seul bloc.", "Charge sur la jambe extérieure, genoux fléchis, regard sur la balle.", "Frappe la balle devant toi entre genou et hauteur de hanche, contact bien en avant du corps.", "Accompagne vers l'avant puis termine la raquette au-dessus de l'épaule opposée.", "Pour la régularité, vise une zone large vers le centre et compte les frappes consécutives."], equipment: ["raquette", "balles", "court ou mur"], commonMistakes: "Préparer la raquette avec le bras seul et frapper la balle trop tard, à côté du corps."),
            en: ExerciseExplanation(steps: ["As the ball comes, turn hips and shoulders together (unit turn), taking the racket back as one block.", "Load onto the outside leg, knees flexed, eyes on the ball.", "Make contact in front of you between knee and hip height, well ahead of the body.", "Swing forward then finish the racket over the opposite shoulder.", "For consistency, aim a wide zone toward the center and count consecutive contacts."], equipment: ["racket", "balls", "court or wall"], commonMistakes: "Taking the racket back with the arm alone and contacting the ball too late, beside the body.")),
        SeedEntry(matchers: ["échanges fond de court", "echanges fond de court", "échanges réguliers", "echanges reguliers", "rallye contrôle", "rallye controle", "alternés fh · bh", "alterné fh · bh", "patterns 1-2 coups"],
            fr: ExerciseExplanation(steps: ["Place-toi en fond de court, prêt à enchaîner coup droit et revers selon la balle.", "Replace-toi au centre après chaque frappe par de petits pas d'ajustement.", "Vise la profondeur vers le fond de court et garde une marge au-dessus du filet.", "Cherche la régularité : un nombre de frappes consécutives élevé, pas la vitesse.", "Alterne les zones coup droit et revers en gardant une allure contrôlée."], equipment: ["raquette", "balles", "court", "partenaire ou mur"], commonMistakes: "Chercher le coup gagnant trop tôt et casser le rythme de l'échange."),
            en: ExerciseExplanation(steps: ["Set up at the baseline, ready to alternate forehand and backhand depending on the ball.", "Recover to the center after each shot with small adjustment steps.", "Aim for depth toward the back of the court and keep margin over the net.", "Seek consistency: a high count of consecutive contacts, not speed.", "Alternate forehand and backhand zones while keeping a controlled pace."], equipment: ["racket", "balls", "court", "partner or wall"], commonMistakes: "Going for the winner too early and breaking the rhythm of the rally.")),
        SeedEntry(matchers: ["activation core", "activation s&c", "activation core légère"],
            fr: ExerciseExplanation(steps: ["Enchaîne quelques ponts fessiers pour réveiller la chaîne postérieure.", "Ajoute des bird-dogs lents de chaque côté pour activer le gainage profond.", "Termine par une planche courte, corps aligné, sans charge additionnelle.", "Reste sur de l'activation légère : l'objectif est de préparer, pas de fatiguer."], equipment: ["tapis optionnel"], commonMistakes: "Transformer l'activation en séance lourde au lieu de simplement réveiller les muscles."),
            en: ExerciseExplanation(steps: ["Chain a few glute bridges to wake up the posterior chain.", "Add slow bird-dogs on each side to activate the deep core.", "Finish with a short plank, body aligned, no added load.", "Keep it light activation: the goal is to prepare, not to fatigue."], equipment: ["mat optional"], commonMistakes: "Turning activation into a heavy session instead of simply waking up the muscles.")),
        SeedEntry(matchers: ["calf raises", "calf raise", "montées sur la pointe", "montees sur la pointe"],
            fr: ExerciseExplanation(steps: ["Tiens-toi debout, pieds parallèles, en t'aidant d'un appui pour l'équilibre si besoin.", "Monte sur la pointe des pieds en poussant fort sur l'avant du pied.", "Marque une courte pause en haut, mollets contractés.", "Redescends lentement les talons sous contrôle, sans rebondir."], equipment: ["appui optionnel pour l'équilibre"], commonMistakes: "Rebondir en bas au lieu de contrôler la descente et de marquer la contraction en haut."),
            en: ExerciseExplanation(steps: ["Stand tall, feet parallel, using a support for balance if needed.", "Rise onto the balls of the feet by pushing strongly through the forefoot.", "Pause briefly at the top with the calves contracted.", "Lower the heels slowly under control, without bouncing."], equipment: ["support optional for balance"], commonMistakes: "Bouncing at the bottom instead of controlling the descent and pausing the contraction at the top.")),
        SeedEntry(matchers: ["conditioning circuit", "kovacs", "circuit 6 stations", "circuit kovacs"],
            fr: ExerciseExplanation(steps: ["Installe les 6 stations en cercle : sprint, échelle d'agilité, médecine-ball, pompe, fente, gainage.", "Travaille chaque station environ 30 secondes, puis enchaîne avec une courte transition.", "Garde une intensité soutenue mais régulière sur tout le tour.", "Récupère le temps prévu entre les tours avant de repartir.", "Adapte le nombre de répétitions à ta forme du jour si une station devient inconfortable."], equipment: ["médecine-ball", "échelle d'agilité optionnelle", "espace dégagé"], commonMistakes: "Partir trop vite sur les premières stations et s'écrouler avant la fin du tour."),
            en: ExerciseExplanation(steps: ["Set up the 6 stations in a circle: sprint, agility ladder, medicine ball, push-up, lunge, plank.", "Work each station about 30 seconds, then move on with a short transition.", "Keep a sustained but steady intensity through the whole round.", "Recover for the set time between rounds before starting again.", "Adjust the number of reps to your form of the day if a station becomes uncomfortable."], equipment: ["medicine ball", "agility ladder optional", "open space"], commonMistakes: "Going out too fast on the first stations and fading before the round ends.")),
        SeedEntry(matchers: ["retour", "retour neutre", "retour neutralisant", "neutralisation", "pattern retour"],
            fr: ExerciseExplanation(steps: ["Adopte une posture d'attente basse et active, raquette devant, juste avant le service adverse.", "Fais un split-step au moment où l'adversaire frappe pour réagir dans toutes les directions.", "Sur balle rapide, raccourcis l'armé et bloque le retour, contact devant le corps.", "Vise un retour profond en cross pour neutraliser et te remettre dans l'échange.", "Replace-toi vers le centre dès le retour joué."], equipment: ["raquette", "balles", "court", "partenaire ou panier"], commonMistakes: "Garder un grand armé sur retour rapide, ce qui décale le timing du contact."),
            en: ExerciseExplanation(steps: ["Adopt a low, active ready stance, racket in front, just before the opponent's serve.", "Make a split-step as the opponent strikes so you can react in any direction.", "On a fast ball, shorten the backswing and block the return, contact in front of the body.", "Aim a deep cross-court return to neutralize and get back into the rally.", "Recover toward the center as soon as the return is played."], equipment: ["racket", "balls", "court", "partner or basket"], commonMistakes: "Keeping a full backswing on a fast serve, which throws off the contact timing.")),
        SeedEntry(matchers: ["split-step", "split step", "déplacement latéral", "deplacement lateral", "recovery step", "side shuffle", "pas chassé", "pas chasse", "cross-over step"],
            fr: ExerciseExplanation(steps: ["Sur la ligne de fond, fais un petit saut d'attente où les deux pieds atterrissent ensemble (split-step).", "Atterris au moment où l'adversaire frappe, genoux fléchis, prêt à partir dans les deux sens.", "Pousse sur la jambe extérieure et déplace-toi en pas chassés latéraux, sans croiser sur les courtes distances.", "Ajoute le cross-over step pour couvrir les balles larges, puis enchaîne un recovery step pour revenir au centre."], equipment: [], commonMistakes: "Rester immobile au lieu de réamorcer un split-step à chaque frappe adverse."),
            en: ExerciseExplanation(steps: ["On the baseline, make a small ready hop where both feet land together (split-step).", "Land as the opponent strikes, knees flexed, ready to push off either way.", "Push off the outside leg and move with lateral shuffle steps, no crossover on short distances.", "Add a crossover step to cover wide balls, then chain a recovery step back to the center."], equipment: [], commonMistakes: "Standing still instead of re-triggering a split-step on every opponent contact.")),
        SeedEntry(matchers: ["cardio intermittent", "sprint 15 m", "sprint 20 m", "sprint maximal", "30 · 30 footing", "sprints courts"],
            fr: ExerciseExplanation(steps: ["Repère une distance courte (15 à 20 m) en ligne droite, sol stable.", "Pars en accélération franche, buste légèrement penché en avant sur les premiers appuis.", "Cours à l'allure prévue (modérée à maximale selon le bloc) sur toute la distance.", "Récupère en marchant le temps indiqué avant de relancer le sprint suivant.", "Conserve une bonne posture sur les derniers sprints même quand la fatigue monte."], equipment: ["espace de course ou court"], commonMistakes: "Démarrer trop fort sur les premiers sprints et s'effondrer en posture sur les derniers."),
            en: ExerciseExplanation(steps: ["Mark a short straight distance (15 to 20 m) on stable ground.", "Launch with a sharp acceleration, torso slightly forward on the first steps.", "Run at the planned pace (moderate to maximal depending on the block) over the full distance.", "Recover by walking for the set time before starting the next sprint.", "Keep good posture on the final sprints even as fatigue rises."], equipment: ["running space or court"], commonMistakes: "Going out too hard on the first sprints and losing posture on the last ones.")),
        SeedEntry(matchers: ["mobilité", "mobilite", "cool-down", "cool down", "foam roll", "foam rolling", "récup active", "recup active", "récupération active", "recuperation active", "90 · 90", "pigeon", "cat-cow", "étirements", "etirements"],
            fr: ExerciseExplanation(steps: ["Commence par quelques minutes de marche ou de mouvements lents pour faire redescendre le rythme.", "Enchaîne les mobilités hanches et thoracique : cercles de hanches, posture 90-90, pigeon, cat-cow, rotation thoracique.", "Tiens chaque position environ 30 secondes en respirant calmement, sans forcer l'amplitude.", "Passe le foam roller sur mollets, quadriceps et fessiers une minute par zone si tu en as un.", "Termine par le sleeper stretch et le cross-body pour relâcher l'épaule de frappe."], equipment: ["tapis optionnel", "foam roller optionnel"], commonMistakes: "Étirer à froid ou chercher l'amplitude maximale au lieu d'un relâchement progressif."),
            en: ExerciseExplanation(steps: ["Start with a few minutes of walking or slow movements to bring the heart rate down.", "Move through hip and thoracic mobility: hip circles, the 90-90 position, pigeon, cat-cow, thoracic rotation.", "Hold each position about 30 seconds breathing calmly, without forcing the range.", "Roll the foam roller over calves, quads and glutes one minute per area if you have one.", "Finish with the sleeper stretch and cross-body to release the hitting shoulder."], equipment: ["mat optional", "foam roller optional"], commonMistakes: "Stretching cold or chasing maximal range instead of a gradual release.")),
        SeedEntry(matchers: ["mini-tennis", "mini tennis", "echauffement cross", "échauffement cross", "drill cross facile", "court drill", "réveil moteur", "mise en route", "feeling balle", "feeling rebond"],
            fr: ExerciseExplanation(steps: ["Place-toi en milieu de court, balles courtes et molles, raquette détendue dans la main.", "Échange en cross sur un tiers du court, vise le centre du tamis (sweet spot) à chaque frappe.", "Garde une allure conversationnelle où tu pourrais parler : c'est un réveil, pas un effort.", "Compte les frappes consécutives sans rater pour calibrer ton feeling de balle.", "Monte progressivement le rythme et la longueur des échanges sur les dernières minutes."], equipment: ["raquette", "balles", "court ou mur"], commonMistakes: "Frapper fort dès la première balle au lieu de chercher le relâchement et le contact propre."),
            en: ExerciseExplanation(steps: ["Set up in the mid-court with soft, slow balls and a relaxed grip on the racket.", "Rally cross-court on a third of the court, aiming for the center of the strings (sweet spot) each time.", "Keep a conversational pace where talking stays easy: this is a wake-up, not an effort.", "Count consecutive clean contacts to calibrate your ball feel.", "Gradually raise the pace and rally length over the final minutes."], equipment: ["racket", "balls", "court or wall"], commonMistakes: "Hitting hard on the first ball instead of seeking relaxation and clean contact.")),
        SeedEntry(matchers: ["grip eastern", "rappel grip", "eastern coup droit", "eastern backhand"],
            fr: ExerciseExplanation(steps: ["Pour l'eastern coup droit, pose la main à plat sur les cordes puis glisse-la vers le manche.", "Cale le talon de la main sur le biseau inférieur du manche, doigts légèrement écartés.", "Pour le revers à 2 mains, place la main dominante en continental et la main non-dominante en eastern coup droit au-dessus.", "Vérifie que la prise reste souple : serre seulement au moment du contact."], equipment: ["raquette"], commonMistakes: "Serrer le manche en permanence, ce qui bloque le poignet et raidit le geste."),
            en: ExerciseExplanation(steps: ["For the eastern forehand, lay your palm flat on the strings then slide it down to the handle.", "Rest the heel of your hand on the bottom bevel of the handle, fingers slightly spread.", "For the two-handed backhand, set the dominant hand in continental and the non-dominant hand in eastern forehand above it.", "Keep the grip loose: tighten only at the moment of contact."], equipment: ["racket"], commonMistakes: "Squeezing the handle constantly, which locks the wrist and stiffens the swing.")),
        SeedEntry(matchers: ["service", "service progressif", "élan complet", "elan complet", "service light", "service récup", "service recup", "service en place", "service maintien"],
            fr: ExerciseExplanation(steps: ["Lance la balle haut et devant, monte en position trophée coude haut.", "Enchaîne la séquence du bas vers le haut : pousse des jambes, déroulé des hanches puis du buste.", "Frappe la balle au point le plus haut, bras tendu, en laissant l'avant-bras tourner (pronation) après le contact.", "Pense « monte et brosse » plutôt que « pousse avec le bras ».", "Accompagne le geste et laisse le corps retomber en équilibre vers l'intérieur du court."], equipment: ["raquette", "balles"], commonMistakes: "Frapper avec le bras seul sans utiliser les jambes ni le buste, ce qui prive le service de vitesse."),
            en: ExerciseExplanation(steps: ["Toss the ball high and in front, rise into the trophy position with a high elbow.", "Run the sequence from bottom up: leg drive, hip then torso unwinding.", "Strike the ball at the highest point, arm extended, letting the forearm rotate (pronation) after contact.", "Think 'jump and brush' rather than 'arm and push'.", "Follow through and let the body land balanced toward the inside of the court."], equipment: ["racket", "balls"], commonMistakes: "Hitting with the arm alone without using legs or torso, which robs the serve of speed.")),
        SeedEntry(matchers: ["service-volée", "service-volee", "service volée", "montée filet", "montee filet", "transition montée", "transition montee", "service + montée", "service + montee"],
            fr: ExerciseExplanation(steps: ["Sers puis avance immédiatement vers le filet en accélérant par petits pas.", "Fais un split-step juste avant le retour adverse pour être stable et prêt à réagir.", "Charge la jambe extérieure et joue la première volée bas devant le corps.", "Continue d'avancer vers la cible pour finir près du filet en position dominante."], equipment: ["raquette", "balles", "court", "partenaire ou panier"], commonMistakes: "Monter au filet sans split-step et se faire surprendre, raquette pas prête."),
            en: ExerciseExplanation(steps: ["Serve then move forward toward the net immediately, accelerating with small steps.", "Make a split-step just before the opponent's return to stay stable and ready to react.", "Load the outside leg and play the first volley low in front of the body.", "Keep moving toward the target to finish near the net in a dominant position."], equipment: ["racket", "balls", "court", "partner or basket"], commonMistakes: "Approaching the net without a split-step and getting caught with the racket not ready.")),
        SeedEntry(matchers: ["agility ladder", "échelle d'agilité", "echelle d'agilite", "in-out", "lateral icky", "icky shuffle", "carioca", "back-pedal", "hopscotch"],
            fr: ExerciseExplanation(steps: ["Pose l'échelle au sol, ou trace des repères à la craie ou avec des cônes si tu n'en as pas.", "Démarre par le pattern in-out : deux pieds dedans, deux pieds dehors, en avançant case par case.", "Garde les appuis bas et rapides, pointes de pieds, regard devant plutôt que sur tes pieds.", "Enchaîne lateral icky shuffle, cross-over puis carioca pour varier les coordinations.", "Privilégie la précision et la légèreté des appuis avant la vitesse pure."], equipment: ["échelle d'agilité ou repères au sol"], commonMistakes: "Regarder ses pieds et taper lourdement les appuis au lieu de rester léger et de fixer l'horizon."),
            en: ExerciseExplanation(steps: ["Lay the ladder on the ground, or mark out rungs with chalk or cones if you don't have one.", "Start with the in-out pattern: two feet in, two feet out, advancing rung by rung.", "Keep the steps low and fast, on the balls of the feet, eyes forward rather than on your feet.", "Chain lateral icky shuffle, crossover then carioca to vary the coordination.", "Favor precision and light footwork before pure speed."], equipment: ["agility ladder or floor markers"], commonMistakes: "Looking at your feet and stamping heavily instead of staying light and fixing the horizon.")),
        SeedEntry(matchers: ["side-to-side", "side to side", "5-balle puissance", "5 balle puissance", "sprint filet", "sprint matchplay"],
            fr: ExerciseExplanation(steps: ["Place-toi en fond de court, prêt à couvrir l'espace par déplacements latéraux.", "Sur balle envoyée à droite puis à gauche, pars en explosivité et joue la frappe en charge.", "Replace-toi par pas chassés rapides après chaque coup, centre de gravité bas.", "Enchaîne les frappes à intensité élevée sur la durée du sprint, puis récupère en marchant.", "Garde la qualité technique malgré l'intensité : appuis et contact propres restent prioritaires."], equipment: ["raquette", "balles", "court", "partenaire ou panier"], commonMistakes: "Négliger le replacement entre deux frappes et arriver en retard sur la balle suivante."),
            en: ExerciseExplanation(steps: ["Set up at the baseline, ready to cover the court with lateral movement.", "On balls sent right then left, push off explosively and hit the shot under load.", "Recover with fast shuffle steps after each shot, center of gravity low.", "Chain high-intensity strikes over the sprint duration, then recover by walking.", "Keep technical quality despite the intensity: clean footwork and contact stay the priority."], equipment: ["racket", "balls", "court", "partner or basket"], commonMistakes: "Skipping the recovery between shots and arriving late on the next ball.")),
        SeedEntry(matchers: ["external rotation", "rotation externe", "er à la bande", "er bande"],
            fr: ExerciseExplanation(steps: ["Fixe une bande élastique à hauteur de coude, place-toi de profil.", "Colle le coude au flanc, fléchi à 90°, avant-bras devant le ventre.", "Tire la bande vers l'extérieur en gardant le coude collé, environ 2 secondes à l'aller.", "Reviens lentement, 2 secondes au retour, sans laisser le coude décoller du flanc.", "Reste sur une charge légère : l'objectif est le contrôle de la coiffe des rotateurs, pas la force brute."], equipment: ["bande élastique"], commonMistakes: "Décoller le coude du flanc et compenser avec l'épaule au lieu d'isoler la rotation."),
            en: ExerciseExplanation(steps: ["Anchor an elastic band at elbow height and stand side-on.", "Tuck the elbow against your side, bent at 90 degrees, forearm across the belly.", "Pull the band outward keeping the elbow tucked, about 2 seconds out.", "Return slowly, 2 seconds back, without letting the elbow drift off the side.", "Stay on a light load: the goal is rotator cuff control, not raw strength."], equipment: ["elastic band"], commonMistakes: "Letting the elbow drift off the side and compensating with the shoulder instead of isolating the rotation.")),
        SeedEntry(matchers: ["revers", "backhand", "cross backhand", "drill mur revers", "long de ligne"],
            fr: ExerciseExplanation(steps: ["Tourne les épaules tôt et arme la raquette des deux mains pour le revers 2 mains.", "Plie les genoux et transfère le poids sur la jambe avant à l'amorce.", "Frappe devant le corps, balle entre genou et hanche, en gardant les bras unis.", "Déroule le buste vers l'avant et finis la raquette haut, vers l'épaule opposée.", "En long de ligne, oriente les épaules vers la cible plus tôt et accompagne droit."], equipment: ["raquette", "balles", "court ou mur"], commonMistakes: "Reculer en frappant la balle dans le dos au lieu d'avancer le contact devant soi."),
            en: ExerciseExplanation(steps: ["Turn the shoulders early and take the racket back with both hands for the two-handed backhand.", "Bend the knees and shift weight onto the front leg as you start the swing.", "Contact in front of the body, ball between knee and hip, keeping the arms united.", "Unwind the torso forward and finish the racket high, toward the opposite shoulder.", "Down the line, orient the shoulders to the target earlier and swing straight through."], equipment: ["racket", "balls", "court or wall"], commonMistakes: "Backing up and hitting the ball behind you instead of taking contact in front.")),
        SeedEntry(matchers: ["lancer + trophée", "lancer + trophee", "trophée statique", "trophee statique", "lancer de balle"],
            fr: ExerciseExplanation(steps: ["Tiens la balle sur le bout des doigts ouverts, bras de lancer tendu.", "Lâche la balle haut et légèrement devant ton épaule de frappe, sans à-coup du poignet.", "Dans le même temps, monte la raquette en position trophée : coude haut, poignet armé.", "Vois la position trophée comme un point de passage fluide, pas une pose figée à tenir."], equipment: ["raquette", "balles"], commonMistakes: "Lancer la balle trop bas ou trop loin derrière, ce qui décale tout le timing du service."),
            en: ExerciseExplanation(steps: ["Hold the ball on open fingertips, tossing arm extended.", "Release the ball high and slightly in front of your hitting shoulder, with no wrist flick.", "At the same time, raise the racket into the trophy position: elbow high, wrist cocked.", "Treat the trophy position as a smooth pass-through point, not a frozen pose to hold."], equipment: ["racket", "balls"], commonMistakes: "Tossing the ball too low or too far back, which throws off the whole serve timing.")),
        SeedEntry(matchers: ["1er coup", "premier coup", "pattern 3 coups", "pattern service", "3-coups", "3 coups", "cross-cross-long", "service + 1er", "service-retour", "service + retour"],
            fr: ExerciseExplanation(steps: ["Sers vers une zone choisie (T ou extérieur) pour ouvrir le court.", "Anticipe le retour probable et enchaîne le 1er coup décisif, souvent en coup droit, vers l'espace libre.", "Replace-toi au centre entre chaque coup par un split-step à chaque frappe adverse.", "Travaille la séquence comme un automatisme : même schéma répété jusqu'à ce qu'il devienne naturel.", "Compte les séquences réussies sur le total pour mesurer ta régularité tactique."], equipment: ["raquette", "balles", "court", "partenaire ou panier"], commonMistakes: "Rester planté après le service au lieu de se replacer et enchaîner le coup suivant."),
            en: ExerciseExplanation(steps: ["Serve to a chosen zone (T or wide) to open up the court.", "Anticipate the likely return and chain the decisive first shot, often a forehand, into the open space.", "Recover to the center between shots with a split-step on each opponent contact.", "Train the sequence as an automatism: the same pattern repeated until it feels natural.", "Count successful sequences out of the total to measure tactical consistency."], equipment: ["racket", "balls", "court", "partner or basket"], commonMistakes: "Standing still after the serve instead of recovering and chaining the next shot.")),
        SeedEntry(matchers: ["planche ventrale", "planche", "plank", "side plank", "plank latéral", "plank lateral"],
            fr: ExerciseExplanation(steps: ["Pour la planche ventrale, place les coudes sous les épaules, avant-bras au sol.", "Aligne tête, dos et bassin, engage les fessiers et le ventre.", "Tiens la position le temps prévu, respiration régulière, sans creuser le bas du dos.", "Pour la planche latérale, appuie sur un avant-bras, corps aligné sur le côté, hanche haute.", "Pour la version avec rotation, passe le bras libre sous le corps puis reviens, contrôlé."], equipment: ["tapis optionnel"], commonMistakes: "Laisser le bassin s'affaisser ou les fesses monter au lieu de garder le corps aligné."),
            en: ExerciseExplanation(steps: ["For the front plank, place the elbows under the shoulders, forearms on the floor.", "Align head, back and pelvis, engage the glutes and abs.", "Hold the position for the set time, breathing steadily, without sagging the lower back.", "For the side plank, prop on one forearm, body aligned on its side, hip high.", "For the rotation version, pass the free arm under the body then return, controlled."], equipment: ["mat optional"], commonMistakes: "Letting the hips sag or the butt pike up instead of keeping the body aligned.")),
        SeedEntry(matchers: ["fente statique", "fente dynamique", "split squat", "single-leg squat", "bulgare"],
            fr: ExerciseExplanation(steps: ["Place un pied en avant à plat, l'autre en arrière (sur un banc pour la version bulgare).", "Descends en pliant le genou avant, sans qu'il dépasse la pointe du pied, environ 2 à 3 secondes.", "Garde le buste droit et le poids vertical au-dessus du pied avant.", "Remonte en poussant dans le talon avant, puis alterne ou enchaîne les répétitions.", "Ajoute des haltères en mains pour la version lestée si tu es à l'aise."], equipment: ["banc optionnel", "haltères optionnels"], commonMistakes: "Pencher le buste en avant et laisser le genou avant partir vers l'intérieur."),
            en: ExerciseExplanation(steps: ["Place one foot forward flat, the other behind (on a bench for the Bulgarian version).", "Lower by bending the front knee, without it passing the toes, about 2 to 3 seconds.", "Keep the torso upright and the weight vertical over the front foot.", "Drive back up through the front heel, then alternate or chain reps.", "Add dumbbells in hand for the loaded version if you are comfortable."], equipment: ["bench optional", "dumbbells optional"], commonMistakes: "Leaning the torso forward and letting the front knee drift inward.")),
        SeedEntry(matchers: ["hip thrust", "pont fessier", "deadlift roumain"],
            fr: ExerciseExplanation(steps: ["Pour le hip thrust, cale le haut du dos sur un banc, pieds à plat au sol.", "Pousse le bassin vers le plafond en serrant les fessiers, sans cambrer le bas du dos.", "Tiens environ 2 secondes en haut puis redescends sous contrôle.", "Pour le pont fessier au sol, même principe allongé sur le dos, genoux fléchis.", "Pour le deadlift roumain unilatéral, descends le buste en gardant le dos plat et une légère flexion de genou."], equipment: ["banc optionnel", "charge optionnelle"], commonMistakes: "Cambrer le bas du dos en fin de poussée au lieu de garder le bassin gainé."),
            en: ExerciseExplanation(steps: ["For the hip thrust, set the upper back on a bench, feet flat on the floor.", "Drive the hips toward the ceiling by squeezing the glutes, without arching the lower back.", "Hold about 2 seconds at the top then lower under control.", "For the floor glute bridge, same idea lying on your back, knees bent.", "For the single-leg Romanian deadlift, hinge the torso down keeping the back flat and a slight knee bend."], equipment: ["bench optional", "load optional"], commonMistakes: "Arching the lower back at the top instead of keeping the pelvis braced.")),
        SeedEntry(matchers: ["med ball", "rotational throw", "overhead slam"],
            fr: ExerciseExplanation(steps: ["Pour le lancer rotatif, place-toi de profil par rapport au mur, médecine-ball à deux mains.", "Charge en tournant le buste vers l'arrière, puis déroule hanches puis épaules de façon explosive.", "Lâche la balle contre le mur au moment où le buste fait face, comme un coup de fond de court.", "Pour l'overhead slam, monte la balle au-dessus de la tête puis projette-la au sol en triple extension descendante.", "Cherche l'explosivité du geste plus que le poids de la balle."], equipment: ["médecine-ball", "mur"], commonMistakes: "Lancer avec les bras seuls au lieu d'enchaîner hanches puis épaules en rotation."),
            en: ExerciseExplanation(steps: ["For the rotational throw, stand side-on to the wall, medicine ball in both hands.", "Load by turning the torso back, then unwind hips then shoulders explosively.", "Release the ball into the wall as the torso faces forward, like a groundstroke.", "For the overhead slam, raise the ball overhead then drive it to the floor with a downward triple extension.", "Seek explosiveness of the motion more than the weight of the ball."], equipment: ["medicine ball", "wall"], commonMistakes: "Throwing with the arms alone instead of sequencing hips then shoulders in rotation.")),
        SeedEntry(matchers: ["sleeper stretch", "cross-body", "mobilité épaule", "mobilite epaule"],
            fr: ExerciseExplanation(steps: ["Pour le sleeper stretch, allonge-toi sur le côté travaillé, bras à 90° devant toi.", "Avec l'autre main, descends doucement l'avant-bras vers le sol jusqu'à sentir un étirement léger derrière l'épaule.", "Tiens environ 30 secondes de chaque côté, respiration calme.", "Pour le cross-body, ramène le bras tendu en travers de la poitrine et maintiens-le avec l'autre bras."], equipment: ["tapis optionnel"], commonMistakes: "Forcer l'amplitude jusqu'à l'inconfort : reste sur un étirement léger et progressif."),
            en: ExerciseExplanation(steps: ["For the sleeper stretch, lie on the working side, arm at 90 degrees in front of you.", "With the other hand, gently lower the forearm toward the floor until you feel a light stretch behind the shoulder.", "Hold about 30 seconds each side, breathing calmly.", "For the cross-body, bring the straight arm across the chest and hold it with the other arm."], equipment: ["mat optional"], commonMistakes: "Forcing the range to discomfort: stay on a light, gradual stretch.")),
        SeedEntry(matchers: ["ghost-stroking", "ghost stroking", "jonglage", "lancer-frappe", "lancé-frappe"],
            fr: ExerciseExplanation(steps: ["Sans balle, prends ta prise puis enchaîne le geste complet au ralenti : préparation, accompagnement, finition épaule.", "Décompose la préparation latérale en tournant les épaules avant de lancer le bras.", "Termine la finition au-dessus de l'épaule opposée, buste qui se déroule.", "Répète à différents rythmes pour ancrer le schéma moteur, focus pur sur la fluidité."], equipment: ["raquette"], commonMistakes: "Bouger seulement le bras sans tourner les épaules, ce qui casse l'enchaînement du geste."),
            en: ExerciseExplanation(steps: ["Without a ball, take your grip then run through the full motion slowly: preparation, swing path, shoulder finish.", "Break down the sideways preparation by turning the shoulders before launching the arm.", "Finish above the opposite shoulder, with the torso unwinding through.", "Repeat at varied tempos to ingrain the motor pattern, focusing purely on fluidity."], equipment: ["racket"], commonMistakes: "Moving only the arm without turning the shoulders, which breaks the flow of the motion.")),
        SeedEntry(matchers: ["prone scaption", "scaption", "prone row"],
            fr: ExerciseExplanation(steps: ["Allonge-toi à plat ventre, bras tendus à environ 30° en avant des épaules, en forme de V.", "Pouces vers le plafond, lève les bras vers le plafond en contrôlant la montée.", "Redescends lentement sans relâcher d'un coup, en gardant les omoplates engagées.", "Pour le prone row, tire les coudes vers le ciel en serrant les omoplates l'une vers l'autre."], equipment: ["petite charge légère optionnelle"], commonMistakes: "Lever les bras trop écartés ou trop haut, ce qui sollicite l'épaule plutôt que les stabilisateurs."),
            en: ExerciseExplanation(steps: ["Lie face down, arms reaching about 30 degrees in front of the shoulders, in a V shape.", "Thumbs up, raise the arms toward the ceiling with a controlled lift.", "Lower slowly without dropping, keeping the shoulder blades engaged.", "For the prone row, pull the elbows toward the ceiling, squeezing the shoulder blades together."], equipment: ["small light load optional"], commonMistakes: "Raising the arms too wide or too high, which loads the shoulder rather than the stabilizers.")),
        SeedEntry(matchers: ["pallof press", "pallof", "anti-rotation"],
            fr: ExerciseExplanation(steps: ["Fixe une bande élastique à hauteur de poitrine sur le côté, place-toi de profil, jambes fléchies.", "Tiens la poignée à deux mains contre le sternum, gainage engagé.", "Pousse les bras droit devant la poitrine environ 2 secondes, sans laisser le buste tourner.", "Reviens 2 secondes au sternum en résistant à la traction latérale de la bande.", "Garde les hanches et les épaules face à l'avant pendant tout le mouvement."], equipment: ["bande élastique"], commonMistakes: "Laisser le buste pivoter vers l'ancrage au lieu de résister à la rotation."),
            en: ExerciseExplanation(steps: ["Anchor an elastic band at chest height to the side, stand side-on, knees flexed.", "Hold the handle with both hands against the sternum, core engaged.", "Press the arms straight out from the chest about 2 seconds, without letting the torso turn.", "Return 2 seconds to the sternum while resisting the band's sideways pull.", "Keep hips and shoulders facing forward throughout the movement."], equipment: ["elastic band"], commonMistakes: "Letting the torso rotate toward the anchor instead of resisting the rotation.")),
        SeedEntry(matchers: ["squat", "goblet squat", "squat barbell"],
            fr: ExerciseExplanation(steps: ["Place les pieds à largeur d'épaules, pointes légèrement vers l'extérieur.", "Descends en poussant les hanches vers l'arrière, poids réparti sur les talons.", "Garde les genoux dans l'axe des orteils et le buste droit, regard devant.", "Descends jusqu'à environ 70 à 80° puis remonte en poussant dans le sol.", "Avec charge (goblet ou barbell), garde le dos gainé et le geste contrôlé."], equipment: ["charge optionnelle (haltère ou barre)"], commonMistakes: "Laisser les genoux rentrer vers l'intérieur ou décoller les talons en descendant."),
            en: ExerciseExplanation(steps: ["Place the feet shoulder-width apart, toes slightly turned out.", "Lower by pushing the hips back, weight balanced over the heels.", "Keep the knees tracking over the toes and the torso upright, eyes forward.", "Descend to about 70 to 80 degrees then drive back up through the floor.", "With load (goblet or barbell), keep the back braced and the movement controlled."], equipment: ["optional load (dumbbell or barbell)"], commonMistakes: "Letting the knees cave inward or the heels lift while lowering.")),
        SeedEntry(matchers: ["box jump", "lateral bound", "plyo"],
            fr: ExerciseExplanation(steps: ["Pour le box jump, place-toi face à la box, genoux fléchis, bras prêts à donner l'impulsion.", "Saute en triple extension chevilles, genoux, hanches et atterris souplement, genoux alignés.", "Redescends en marchant plutôt qu'en sautant pour préserver les appuis.", "Pour le lateral bound, pousse latéralement sur une jambe et réceptionne en douceur sur l'autre, équilibre tenu.", "Privilégie la qualité d'atterrissage et l'explosivité courte plutôt que le volume."], equipment: ["box ou banc"], commonMistakes: "Atterrir genoux raides ou rentrés vers l'intérieur au lieu d'une réception souple et alignée."),
            en: ExerciseExplanation(steps: ["For the box jump, face the box, knees flexed, arms ready to drive the takeoff.", "Jump with triple extension of ankles, knees, hips and land softly, knees aligned.", "Step down rather than jumping down to protect the joints.", "For the lateral bound, push off sideways on one leg and land softly on the other, balance held.", "Favor landing quality and short explosiveness over volume."], equipment: ["box or bench"], commonMistakes: "Landing with stiff or inward-collapsing knees instead of a soft, aligned reception.")),
        SeedEntry(matchers: ["volée", "volee", "ghost-volée", "ghost-volee", "ghost volée"],
            fr: ExerciseExplanation(steps: ["Prends la prise continentale, valable pour la volée coup droit comme revers.", "Garde la raquette devant toi, coude souple, regard sur la balle.", "Avance vers la balle et bloque le contact devant le corps, geste court sans grand armé.", "Accompagne légèrement vers la cible avec de petits pas, centre de gravité bas et réactif."], equipment: ["raquette", "balles", "court"], commonMistakes: "Armer la raquette comme un coup de fond de court au lieu d'un geste court et bloqué devant soi."),
            en: ExerciseExplanation(steps: ["Take the continental grip, valid for both forehand and backhand volleys.", "Keep the racket in front of you, elbow soft, eyes on the ball.", "Move toward the ball and block contact in front of the body, a short stroke with little backswing.", "Punch slightly toward the target with small steps, center of gravity low and reactive."], equipment: ["racket", "balls", "court"], commonMistakes: "Taking a full groundstroke backswing instead of a short blocked stroke in front of you.")),
        SeedEntry(matchers: ["y-t-w", "ytw", "shoulder"],
            fr: ExerciseExplanation(steps: ["Allonge-toi à plat ventre ou penche-toi en avant, bras tendus vers le sol, pouces vers le plafond.", "Pour le Y, lève les bras à 45° au-dessus de la tête en serrant les omoplates.", "Pour le T, écarte les bras à l'horizontale en gardant les épaules basses.", "Pour le W, plie les coudes et tire-les vers le bas en serrant fort les omoplates.", "Reste très léger en charge, mouvement lent et contrôlé, focus sur les stabilisateurs scapulaires."], equipment: ["petite charge légère optionnelle"], commonMistakes: "Remonter les épaules vers les oreilles au lieu de garder les omoplates basses et serrées."),
            en: ExerciseExplanation(steps: ["Lie face down or hinge forward, arms reaching toward the floor, thumbs up.", "For the Y, raise the arms to 45 degrees overhead while squeezing the shoulder blades.", "For the T, spread the arms to horizontal while keeping the shoulders down.", "For the W, bend the elbows and pull them down, squeezing the shoulder blades firmly.", "Stay very light, slow and controlled, focusing on the scapular stabilizers."], equipment: ["small light load optional"], commonMistakes: "Shrugging the shoulders toward the ears instead of keeping the shoulder blades down and squeezed.")),
        SeedEntry(matchers: ["bird-dog", "bird dog"],
            fr: ExerciseExplanation(steps: ["Place-toi à quatre pattes, mains sous les épaules, genoux sous les hanches, dos neutre.", "Tends en même temps le bras et la jambe opposés jusqu'à l'horizontale.", "Tiens environ 2 secondes en gardant le bassin stable, sans tourner les hanches.", "Reviens lentement et alterne les côtés, gainage engagé tout du long."], equipment: ["tapis optionnel"], commonMistakes: "Laisser le bassin basculer sur le côté au lieu de garder le tronc bien stable."),
            en: ExerciseExplanation(steps: ["Set up on all fours, hands under shoulders, knees under hips, neutral back.", "Extend the opposite arm and leg at the same time to horizontal.", "Hold about 2 seconds keeping the pelvis stable, without rotating the hips.", "Return slowly and alternate sides, core engaged throughout."], equipment: ["mat optional"], commonMistakes: "Letting the pelvis tilt to the side instead of keeping the trunk steady.")),
        SeedEntry(matchers: ["smash"],
            fr: ExerciseExplanation(steps: ["Tourne de côté dès que le lob part, pointe la main libre vers la balle pour la suivre.", "Arme la raquette derrière l'épaule, position proche du service.", "Ajuste tes appuis par petits pas pour que la balle reste devant toi en l'air.", "Frappe bras tendu au point le plus haut, avec pronation de l'avant-bras après contact."], equipment: ["raquette", "balles", "court"], commonMistakes: "Laisser la balle passer derrière la tête au lieu de reculer pour la garder devant soi."),
            en: ExerciseExplanation(steps: ["Turn sideways as soon as the lob goes up, point the free hand at the ball to track it.", "Take the racket back behind the shoulder, close to the serve position.", "Adjust your feet with small steps so the ball stays in front of you in the air.", "Strike with arm extended at the highest point, with forearm pronation after contact."], equipment: ["racket", "balls", "court"], commonMistakes: "Letting the ball drift behind the head instead of backing up to keep it in front.")),

        // MARK: football (36)
        SeedEntry(matchers: ["single leg stance", "single leg stance + perturbation", "proprioception cheville", "equilibre sur 1 jambe", "équilibre sur 1 jambe", "single-leg stance"],
            fr: ExerciseExplanation(steps: ["Tiens-toi en équilibre sur une jambe, l'autre légèrement décollée, regard à l'horizon.", "Garde le genou d'appui souple et aligné au-dessus du pied.", "Engage la cheville et le pied pour stabiliser les petites oscillations.", "Progresse en fermant les yeux ou en recevant un ballon léger d'un partenaire.", "Travaille les deux jambes pour équilibrer la proprioception."], equipment: ["ballon léger (optionnel)"], commonMistakes: "Bloquer le genou et se raidir : laisse l'appui légèrement souple pour gérer les déséquilibres."),
            en: ExerciseExplanation(steps: ["Balance on one leg, the other slightly off the floor, gaze on the horizon.", "Keep the supporting knee soft and aligned over the foot.", "Engage the ankle and foot to stabilise small wobbles.", "Progress by closing your eyes or catching a light ball from a partner.", "Work both legs to balance proprioception."], equipment: ["light ball (optional)"], commonMistakes: "Locking the knee and stiffening up: keep the support slightly soft to manage wobbles.")),
        SeedEntry(matchers: ["frappe puissance", "frappe complète", "frappe complete", "frappe alternee", "frappe alternée", "frappe puissance + placement"],
            fr: ExerciseExplanation(steps: ["Prends 2 à 3 appuis d'élan, pied d'appui posé à côté du ballon.", "Frappe avec le cou-de-pied (laces), cheville verrouillée et orteils pointés vers le bas.", "Garde le buste au-dessus du ballon pour cadrer la frappe vers le but.", "Accompagne fort vers l'avant et retombe sur le pied frappeur.", "Reste autour de 70 à 75 pour cent de ton maximum pour garder le contrôle et alterne les deux pieds."], equipment: ["ballon", "but ou mini-but"], commonMistakes: "Chercher la puissance maximale au détriment du cadrage : un ballon cadré à 75 pour cent vaut mieux qu'une frappe forte non maîtrisée."),
            en: ExerciseExplanation(steps: ["Take a 2 to 3 step run-up, standing foot placed beside the ball.", "Strike with the laces (instep), ankle locked and toes pointed down.", "Keep the torso over the ball to keep the shot on target toward goal.", "Follow through strongly forward and land on the kicking foot.", "Stay around 70 to 75 percent of your max to keep control and alternate both feet."], equipment: ["ball", "goal or mini-goal"], commonMistakes: "Chasing maximum power at the expense of accuracy: an on-target shot at 75 percent beats an uncontrolled hard strike.")),
        SeedEntry(matchers: ["intermittent 30s", "intermittent 15s", "intermittents 30s", "intermittent footing", "intermittent footing-marche", "30s · 30s", "15s · 15s", "cardio intermittent", "course intermittente", "strides"],
            fr: ExerciseExplanation(steps: ["Repère deux marques au sol pour faire des allers-retours sur terrain plat.", "Cours à l'allure cible pendant la phase d'effort (par exemple 30 secondes soutenues).", "Récupère en marche active pendant la phase de récup, sans t'arrêter net.", "Garde une foulée régulière et un buste relâché sur la partie rapide.", "Respecte les temps de récupération entre les séries pour tenir la qualité."], equipment: ["cônes ou marques au sol"], commonMistakes: "Partir trop vite sur les premiers cycles : cale une allure que tu peux tenir jusqu'au dernier."),
            en: ExerciseExplanation(steps: ["Mark two spots on the ground for shuttle runs on flat terrain.", "Run at the target pace during the work phase (for example 30 seconds sustained).", "Recover with active walking during the rest phase, without stopping abruptly.", "Keep a steady stride and a relaxed torso on the fast part.", "Respect the recovery times between sets to maintain quality."], equipment: ["cones or floor markers"], commonMistakes: "Going out too fast on the first cycles: settle on a pace you can hold to the last one.")),
        SeedEntry(matchers: ["dribble", "conduite + dribble", "conduite + passe + frappe", "enchainement collectif", "enchaînement collectif", "enchainement complet", "enchaînement complet"],
            fr: ExerciseExplanation(steps: ["Conduis le ballon vers le repère (cône ou mannequin) en gardant le contrôle.", "Exécute un geste simple au contact : crochet intérieur ou extérieur pour changer d'axe.", "Replace immédiatement le ballon sous contrôle après le dribble.", "Enchaîne avec la passe ou la frappe prévue sans casser le rythme.", "Alterne pied dominant et non-dominant d'une répétition à l'autre."], equipment: ["ballon", "cônes ou mannequin", "mini-but (optionnel)"], commonMistakes: "Vouloir un geste trop spectaculaire : un crochet net et maîtrisé est plus efficace qu'un dribble raté."),
            en: ExerciseExplanation(steps: ["Dribble the ball toward the marker (cone or mannequin) while keeping control.", "Perform a simple move at contact: inside or outside cut to change your line.", "Bring the ball back under control immediately after the move.", "Link straight into the planned pass or shot without breaking the rhythm.", "Alternate dominant and non-dominant foot from one rep to the next."], equipment: ["ball", "cones or mannequin", "mini-goal (optional)"], commonMistakes: "Going for a move that is too flashy: a clean, controlled cut is more effective than a failed dribble.")),
        SeedEntry(matchers: ["footing z2", "footing + jongles", "footing intermittent", "footing progressif", "mise en route", "course intermittente z2", "cardio doux", "corde a sauter", "corde à sauter"],
            fr: ExerciseExplanation(steps: ["Démarre par un footing facile en allure conversationnelle autour du terrain.", "Augmente progressivement le rythme pour réveiller le système cardio en douceur.", "Ajoute du ballon dans les pieds (conduite ou jongles légers) pour préparer le geste.", "Garde une foulée souple et un buste relâché tout du long.", "Termine cette mise en route prêt à enchaîner sur le cœur de séance."], equipment: ["ballon (optionnel)", "corde à sauter (optionnel)"], commonMistakes: "Sauter l'échauffement progressif : montée en température graduelle pour entrer dans la séance dans de bonnes conditions."),
            en: ExerciseExplanation(steps: ["Start with an easy jog at conversational pace around the pitch.", "Gradually raise the tempo to wake up the cardio system gently.", "Add the ball at your feet (dribbling or light juggling) to prime the movement.", "Keep a smooth stride and a relaxed torso throughout.", "Finish this warm-up ready to move into the main part of the session."], equipment: ["ball (optional)", "jump rope (optional)"], commonMistakes: "Skipping the progressive warm-up: ramp up the temperature gradually to enter the session in good conditions.")),
        SeedEntry(matchers: ["cool-down", "cool down", "retour calme", "etirements + mobilite", "marche + etirement", "marche + étirement", "mobilite + foam", "mobilité + foam"],
            fr: ExerciseExplanation(steps: ["Commence par 3 à 5 minutes de marche ou footing très lent autour du terrain pour faire redescendre le rythme cardiaque en douceur.", "Étire les groupes clés du foot 30 secondes par côté : ischio-jambiers, quadriceps, adducteurs, mollets et hanches, sans à-coups.", "Garde une tension confortable sur chaque étirement, expire lentement et reste loin de l'inconfort.", "Si tu as un foam roller, passe 1 minute par zone sur ischios, mollets et bandelette ilio-tibiale.", "Termine par quelques respirations amples pour clore la séance au calme."], equipment: ["foam roller (optionnel)"], commonMistakes: "Étirer à froid en force ou rebondir : préfère un maintien stable et progressif après quelques minutes de marche."),
            en: ExerciseExplanation(steps: ["Start with 3 to 5 minutes of walking or very slow jogging around the pitch to bring the heart rate down gently.", "Stretch the key football muscle groups for 30 seconds per side: hamstrings, quadriceps, adductors, calves and hips, with no jerking.", "Hold each stretch at a comfortable tension, breathe out slowly and stay short of discomfort.", "If you have a foam roller, spend 1 minute per area on hamstrings, calves and the iliotibial band.", "Finish with a few full breaths to close the session calmly."], equipment: ["foam roller (optional)"], commonMistakes: "Stretching cold and hard or bouncing: prefer a steady, progressive hold after a few minutes of walking.")),
        SeedEntry(matchers: ["coups de pied arretes", "coups de pied arrêtés", "corner", "coup franc", "coups francs", "coup-franc"],
            fr: ExerciseExplanation(steps: ["Pose le ballon et choisis ta cible (premier poteau, deuxième poteau ou zone de retrait).", "Cale ton élan et ton pied d'appui orienté vers la trajectoire voulue.", "Pour un centre, frappe avec l'intérieur ou le cou-de-pied selon l'effet recherché.", "Travaille le timing des courses des partenaires sur quelques répétitions à vide.", "Alterne côté droit et côté gauche pour varier les angles."], equipment: ["ballon", "but ou mini-but", "cônes (optionnel)"], commonMistakes: "Frapper toujours au même endroit : varie les zones et les trajectoires pour rester imprévisible."),
            en: ExerciseExplanation(steps: ["Set the ball and pick your target (near post, far post or pull-back zone).", "Settle your run-up and point the standing foot toward the intended trajectory.", "For a cross, strike with the inside or the laces depending on the effect you want.", "Work on the timing of teammates' runs over a few unopposed reps.", "Alternate right and left side to vary the angles."], equipment: ["ball", "goal or mini-goal", "cones (optional)"], commonMistakes: "Always delivering to the same spot: vary the zones and trajectories to stay unpredictable.")),
        SeedEntry(matchers: ["recuperation active", "récupération active", "md+1", "recup mi-temps", "récup mi-temps", "footing recup", "footing récup", "footing z1", "mobilite + activation", "mobilité + activation"],
            fr: ExerciseExplanation(steps: ["Commence par un footing très lent en zone facile pour relancer la circulation.", "Enchaîne avec quelques mouvements de mobilité des hanches, chevilles et dos.", "Passe le foam roller 1 minute par zone sur mollets, quadriceps et fessiers si tu en as un.", "Hydrate-toi et garde un effort très léger, conversationnel tout du long.", "Si la fatigue est marquée, raccourcis et privilégie une marche tranquille."], equipment: ["foam roller (optionnel)"], commonMistakes: "Rester totalement inactif après l'effort : un mouvement léger relance mieux la récupération qu'un arrêt complet."),
            en: ExerciseExplanation(steps: ["Start with a very slow jog in an easy zone to get the circulation going.", "Follow with a few mobility moves for the hips, ankles and back.", "Roll 1 minute per area on calves, quads and glutes with a foam roller if you have one.", "Hydrate and keep a very light, conversational effort throughout.", "If fatigue is marked, shorten it and favour an easy walk."], equipment: ["foam roller (optional)"], commonMistakes: "Staying completely inactive after the effort: light movement aids recovery better than a full stop.")),
        SeedEntry(matchers: ["copenhagen adduction", "cae", "copenhagen"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le côté, en appui sur l'avant-bras, coude sous l'épaule.", "Pose la jambe du dessus sur un banc ou un partenaire, au niveau de la cheville.", "Monte le bassin en gardant le corps aligné, jambe basse engagée.", "Descends le bassin de façon contrôlée puis remonte sans à-coups.", "Change de côté pour équilibrer le travail des adducteurs."], equipment: ["banc ou partenaire", "tapis (optionnel)"], commonMistakes: "Laisser le bassin tomber ou cambrer : garde le corps gainé et le mouvement lent et maîtrisé."),
            en: ExerciseExplanation(steps: ["Lie on your side, supported on the forearm, elbow under the shoulder.", "Rest the top leg on a bench or a partner, at ankle level.", "Raise the pelvis keeping the body aligned, lower leg engaged.", "Lower the pelvis in a controlled way, then lift again smoothly.", "Switch sides to balance adductor work."], equipment: ["bench or partner", "mat (optional)"], commonMistakes: "Letting the pelvis drop or arching the back: keep the body braced and the movement slow and controlled.")),
        SeedEntry(matchers: ["rsa", "repeated sprint", "sprint depart arrete", "sprint départ arrêté", "30 m sprint", "rsa reduit"],
            fr: ExerciseExplanation(steps: ["Mesure une distance d'environ 30 m et place-toi en départ arrêté.", "Sprinte à intensité maximale en gardant une foulée puissante et un buste gainé.", "Récupère en marchant pendant l'intervalle prévu entre chaque sprint.", "Vise une faible perte de vitesse entre le premier et le dernier sprint.", "Prends une récupération complète entre les séries pour préserver l'explosivité."], equipment: ["cônes", "chronomètre (optionnel)"], commonMistakes: "Réduire trop la récupération entre sprints : sans récup, la vitesse chute et l'effet recherché disparaît."),
            en: ExerciseExplanation(steps: ["Mark out about 30 m and set up in a standing start.", "Sprint at maximum intensity with a powerful stride and a braced torso.", "Recover by walking during the planned interval between each sprint.", "Aim for a small drop in speed between the first and the last sprint.", "Take full recovery between sets to preserve explosiveness."], equipment: ["cones", "stopwatch (optional)"], commonMistakes: "Cutting recovery between sprints too short: without rest, speed collapses and the intended effect is lost.")),
        SeedEntry(matchers: ["drill tactique", "schemas attaque", "schémas attaque", "sortie de balle", "transition offensive", "transition off", "pattern 1-2", "pattern de passe", "1-2 passes"],
            fr: ExerciseExplanation(steps: ["Mets en place le schéma de jeu (sortie de balle, combinaison ou transition) avec les repères au sol.", "Commence sans opposition pour fixer les courses et les enchaînements de passes.", "Soigne l'orientation du contrôle et la qualité de la première passe.", "Ajoute progressivement des mannequins puis une opposition légère.", "Alterne les côtés gauche et droit pour automatiser le geste des deux pieds."], equipment: ["ballon", "cônes ou mannequins", "chasubles (optionnel)"], commonMistakes: "Précipiter la première passe : un contrôle orienté propre rend tout l'enchaînement plus fluide."),
            en: ExerciseExplanation(steps: ["Set up the pattern (build-up, combination or transition) with floor markers.", "Start unopposed to lock in the runs and the passing sequences.", "Focus on the angle of the first touch and the quality of the first pass.", "Gradually add mannequins then light opposition.", "Alternate left and right side to groove the move with both feet."], equipment: ["ball", "cones or mannequins", "bibs (optional)"], commonMistakes: "Rushing the first pass: a clean angled first touch makes the whole sequence flow better.")),
        SeedEntry(matchers: ["split squat", "split squat bulgare", "split squat avant", "single leg squat", "fente"],
            fr: ExerciseExplanation(steps: ["Place le pied arrière surélevé sur un banc ou une marche, pied avant bien à plat.", "Descends en fléchissant la jambe avant en 3 secondes, buste droit.", "Garde le genou avant aligné au-dessus de la cheville, sans rentrer vers l'intérieur.", "Remonte en poussant dans le talon avant en 1 seconde.", "Travaille les deux jambes pour un équilibre droite-gauche."], equipment: ["banc ou marche", "haltères (optionnel)"], commonMistakes: "Laisser le genou avant tomber vers l'intérieur : garde-le aligné avec le pied pendant toute la descente."),
            en: ExerciseExplanation(steps: ["Place the rear foot elevated on a bench or step, front foot flat.", "Lower by bending the front leg over 3 seconds, chest tall.", "Keep the front knee aligned over the ankle, without caving inward.", "Drive back up through the front heel over 1 second.", "Work both legs for a right-left balance."], equipment: ["bench or step", "dumbbells (optional)"], commonMistakes: "Letting the front knee collapse inward: keep it aligned with the foot throughout the descent.")),
        SeedEntry(matchers: ["possession", "conservation", "toro", "rondo", "jeu de conservation"],
            fr: ExerciseExplanation(steps: ["Délimite une zone avec attaquants en conservation et un ou deux défenseurs.", "Joue en 2 ou 3 touches max pour garder un rythme de circulation élevé.", "Propose un soutien et un angle de passe avant même de recevoir le ballon.", "Oriente ton contrôle pour enchaîner la passe suivante sans temps mort.", "Vise un objectif de passes consécutives pour mesurer la conservation."], equipment: ["ballon", "cônes", "chasubles (optionnel)"], commonMistakes: "Rester statique en attendant le ballon : bouge pour offrir un angle de passe et garder la circulation fluide."),
            en: ExerciseExplanation(steps: ["Mark out a zone with attackers keeping possession and one or two defenders.", "Play with 2 or 3 touch max to keep a high circulation tempo.", "Offer support and a passing angle before you even receive the ball.", "Angle your first touch to link the next pass with no dead time.", "Aim for a target of consecutive passes to measure retention."], equipment: ["ball", "cones", "bibs (optional)"], commonMistakes: "Standing still waiting for the ball: move to offer a passing angle and keep the circulation flowing.")),
        SeedEntry(matchers: ["fifa 11+ complet", "fifa 11+ raccourci", "fifa 11+ — parties", "fifa 11+ parties", "11+ complet", "11+ raccourci"],
            fr: ExerciseExplanation(steps: ["Partie 1 : enchaîne les courses lentes en ligne droite avec ouverture et fermeture des hanches sur 6 à 8 allers.", "Partie 2 : réalise les exercices de gainage, d'équilibre et de plyométrie en soignant l'alignement genou au-dessus du pied.", "Partie 3 : termine par des courses plus rapides avec changements de direction et appuis d'appel.", "Garde une posture droite et des réceptions souples sur chaque exercice.", "Respecte l'ordre des trois parties pour préparer le corps progressivement."], equipment: ["cônes", "ballon (optionnel)", "tapis (optionnel)"], commonMistakes: "Bâcler la qualité d'exécution pour aller vite : c'est la technique propre qui rend cet échauffement utile."),
            en: ExerciseExplanation(steps: ["Part 1: run slowly in a straight line with hip opening and closing over 6 to 8 lengths.", "Part 2: perform the core, balance and plyometric exercises with knee-over-toe alignment.", "Part 3: finish with faster running including changes of direction and planting steps.", "Keep an upright posture and soft landings on every exercise.", "Follow the order of the three parts to prepare the body progressively."], equipment: ["cones", "ball (optional)", "mat (optional)"], commonMistakes: "Rushing through with sloppy execution: it is the clean technique that makes this warm-up worthwhile.")),
        SeedEntry(matchers: ["pallof press", "core anti-rotation", "anti-rotation core", "anti-rotation"],
            fr: ExerciseExplanation(steps: ["Fixe une bande élastique à hauteur de poitrine et place-toi perpendiculairement, mains jointes.", "Tiens-toi debout, pieds largeur bassin, tronc gainé et bassin neutre.", "Étends lentement les bras devant toi en 3 secondes en résistant à la rotation.", "Garde le buste parfaitement face à l'avant, sans laisser la bande te tordre.", "Reviens lentement et travaille les deux côtés."], equipment: ["bande élastique", "point d'ancrage"], commonMistakes: "Laisser le tronc tourner vers la bande : c'est la résistance à la rotation qui compte, pas l'amplitude des bras."),
            en: ExerciseExplanation(steps: ["Anchor an elastic band at chest height and stand perpendicular to it, hands clasped.", "Stand tall, feet hip-width apart, trunk braced and pelvis neutral.", "Slowly extend the arms in front of you over 3 seconds while resisting rotation.", "Keep the torso squarely facing forward, not letting the band twist you.", "Return slowly and work both sides."], equipment: ["elastic band", "anchor point"], commonMistakes: "Letting the trunk rotate toward the band: it is resisting rotation that matters, not how far the arms reach.")),
        SeedEntry(matchers: ["passes courtes", "passe interieur", "passe intérieur", "intérieur du pied", "interieur du pied", "passe + controle", "passe + contrôle", "passe-controle", "passe-contrôle", "combinaison passe", "mini-tennis", "passe + control"],
            fr: ExerciseExplanation(steps: ["Place le pied d'appui à côté du ballon, pointé vers la cible : c'est lui qui oriente la passe.", "Verrouille la cheville et ouvre le pied frappeur à 90 degrés pour présenter une large surface intérieure.", "Frappe le ballon en plein milieu, jambe d'appui légèrement fléchie pour l'équilibre.", "Accompagne le geste vers la cible pour doser le poids de la passe.", "Alterne pied droit et pied gauche pour travailler les deux pieds dès le début."], equipment: ["ballon", "partenaire ou mur"], commonMistakes: "Frapper avec la pointe ou le pied d'appui mal orienté : la passe part de travers et perd en précision."),
            en: ExerciseExplanation(steps: ["Place the standing foot beside the ball, pointed at the target: it sets the direction of the pass.", "Lock the ankle and open the kicking foot to 90 degrees to present a wide inside surface.", "Strike the ball through its mid-line, standing leg slightly bent for balance.", "Follow through toward the target to control the weight of the pass.", "Alternate right and left foot to train both feet from the start."], equipment: ["ball", "partner or wall"], commonMistakes: "Striking with the toe or with a misaligned standing foot: the pass veers off and loses accuracy.")),
        SeedEntry(matchers: ["squat goblet", "back squat", "squat barre", "squat bodyweight", "squats bodyweight", "squat saute", "squat sauté", "fifa 11+ — squats", "fifa 11+ squats"],
            fr: ExerciseExplanation(steps: ["Place les pieds largeur d'épaules, orteils légèrement ouverts.", "Descends en poussant les hanches vers l'arrière, buste droit et talons au sol.", "Garde les genoux dans l'axe des orteils, sans rentrer vers l'intérieur.", "Descends de façon contrôlée puis remonte en poussant dans les talons.", "Pour la version chargée, garde une charge confortable et soigne la technique d'abord."], equipment: ["kettlebell ou haltère (optionnel)", "barre (optionnel)"], commonMistakes: "Laisser les genoux rentrer vers l'intérieur ou décoller les talons : garde l'axe genou-pied stable."),
            en: ExerciseExplanation(steps: ["Set the feet shoulder-width apart, toes slightly turned out.", "Lower by pushing the hips back, chest tall and heels on the floor.", "Keep the knees in line with the toes, without caving inward.", "Lower in a controlled way then drive back up through the heels.", "For the loaded version, keep a comfortable load and prioritise technique first."], equipment: ["kettlebell or dumbbell (optional)", "barbell (optional)"], commonMistakes: "Letting the knees cave in or the heels lift: keep the knee-foot line stable.")),
        SeedEntry(matchers: ["romanian deadlift", "rdl", "trap bar deadlift", "hex bar"],
            fr: ExerciseExplanation(steps: ["Tiens un haltère ou une charge, pieds largeur bassin, genoux légèrement fléchis.", "Pousse les hanches vers l'arrière en gardant le dos plat et neutre.", "Descends la charge le long des jambes en 3 secondes jusqu'à sentir l'étirement des ischio-jambiers.", "Remonte en poussant les hanches vers l'avant, sans arrondir le dos.", "Pour la version unilatérale, garde le bassin horizontal et le tronc gainé."], equipment: ["haltère ou barre", "trap bar (optionnel)"], commonMistakes: "Arrondir le dos pour descendre plus bas : garde le dos plat et laisse les hanches reculer."),
            en: ExerciseExplanation(steps: ["Hold a dumbbell or load, feet hip-width apart, knees slightly bent.", "Push the hips back while keeping the back flat and neutral.", "Lower the load along the legs over 3 seconds until you feel the hamstring stretch.", "Drive back up by pushing the hips forward, without rounding the back.", "For the single-leg version, keep the pelvis level and the trunk braced."], equipment: ["dumbbell or barbell", "trap bar (optional)"], commonMistakes: "Rounding the back to go lower: keep the back flat and let the hips travel backward.")),
        SeedEntry(matchers: ["agility ladder", "echelle d'agilite", "échelle d'agilité", "footwork", "ickey shuffle", "in-out"],
            fr: ExerciseExplanation(steps: ["Place l'échelle au sol et démarre sur la pointe des pieds, genoux souples.", "Exécute le motif choisi (in-out, lateral shuffle, ickey shuffle) en posant un pied par case.", "Garde le buste droit et les bras actifs pour le rythme.", "Privilégie la précision des appuis avant d'augmenter la vitesse.", "Réalise un aller-retour par motif puis enchaîne avec un autre."], equipment: ["échelle d'agilité ou marqueurs au sol"], commonMistakes: "Aller trop vite et taper l'échelle : commence lent et propre, la vitesse vient avec la précision."),
            en: ExerciseExplanation(steps: ["Lay the ladder on the floor and start on the balls of the feet, knees soft.", "Perform the chosen pattern (in-out, lateral shuffle, ickey shuffle) placing one foot per box.", "Keep the torso upright and arms active to set the rhythm.", "Favour precise foot placement before increasing speed.", "Do one round trip per pattern then move on to another."], equipment: ["agility ladder or floor markers"], commonMistakes: "Going too fast and clipping the ladder: start slow and clean, speed comes with precision.")),
        SeedEntry(matchers: ["match amical", "match championnat", "match coupe", "match-simulation", "match simulation", "foot a 5", "foot à 5", "foot a 7", "foot à 7", "foot a 9", "foot à 9", "11v11"],
            fr: ExerciseExplanation(steps: ["Échauffe-toi avant le coup d'envoi (activation et courses progressives) pour entrer prêt.", "Joue à une intensité d'engagement adaptée à ton niveau et au contexte du match.", "Garde une montée en puissance progressive plutôt que des gestes brusques en début de match.", "Hydrate-toi à la mi-temps et reste en mouvement léger pendant la pause.", "Termine par un retour au calme actif et quelques étirements après le match."], equipment: ["ballon", "tenue de match"], commonMistakes: "Démarrer à fond sans montée en puissance : entre progressivement dans le match pour t'engager plus sereinement."),
            en: ExerciseExplanation(steps: ["Warm up before kickoff (activation and progressive runs) to start ready.", "Play at a level of engagement suited to your level and the match context.", "Build up intensity progressively rather than making abrupt moves early on.", "Hydrate at half-time and keep moving lightly during the break.", "Finish with an active cool-down and a few stretches after the match."], equipment: ["ball", "match kit"], commonMistakes: "Going all-out without ramping up: ease into the match to engage more comfortably.")),
        SeedEntry(matchers: ["frappe placee", "frappe placée", "frappe sur cible", "finition", "frappe interieur", "frappe intérieur"],
            fr: ExerciseExplanation(steps: ["Approche le ballon avec un dernier appui calé, pied d'appui pointé vers la cible.", "Pour une frappe placée, ouvre le pied et frappe en intérieur pour viser le coin.", "Garde le buste au-dessus du ballon et l'œil sur la zone visée avant l'impact.", "Transfère le poids du corps vers l'avant en accompagnant le geste.", "Alterne pied droit et gauche et privilégie la précision avant la puissance."], equipment: ["ballon", "cible ou but"], commonMistakes: "Se pencher en arrière à l'impact : le ballon part trop haut au lieu de rester cadré."),
            en: ExerciseExplanation(steps: ["Approach the ball with a settled final step, standing foot pointed at the target.", "For a placed shot, open the foot and strike with the inside to aim for the corner.", "Keep the torso over the ball and your eye on the target zone before impact.", "Transfer body weight forward while following through.", "Alternate right and left foot and favour accuracy over power."], equipment: ["ball", "target or goal"], commonMistakes: "Leaning back at impact: the ball flies too high instead of staying on target.")),
        SeedEntry(matchers: ["controle oriente", "contrôle orienté", "controle amorti", "contrôle amorti", "pied bloqueur", "feeling balle", "grip pied"],
            fr: ExerciseExplanation(steps: ["Va au-devant du ballon et présente une surface souple (intérieur du pied ou semelle).", "Au contact, recule légèrement le pied pour amortir et absorber la vitesse du ballon.", "Oriente le premier contact vers l'espace libre pour enchaîner sans temps mort.", "Garde la tête haute entre les contacts pour lire le jeu autour de toi.", "Travaille les deux pieds en réception pour ne pas être prévisible."], equipment: ["ballon", "partenaire ou mur"], commonMistakes: "Bloquer le ballon raide sous le pied : il rebondit loin et tu perds le contrôle du premier contact."),
            en: ExerciseExplanation(steps: ["Move to meet the ball and present a soft surface (inside of the foot or sole).", "On contact, draw the foot back slightly to cushion and absorb the ball's speed.", "Direct the first touch into open space to keep play flowing.", "Keep your head up between touches to read the play around you.", "Work both feet when receiving so you stay unpredictable."], equipment: ["ball", "partner or wall"], commonMistakes: "Trapping the ball stiff under the foot: it bounces away and you lose control of the first touch.")),
        SeedEntry(matchers: ["fifa 11+ — bench", "fifa 11+ bench", "the bench", "— bench", "plank", "gainage"],
            fr: ExerciseExplanation(steps: ["Place les coudes sous les épaules et les avant-bras au sol, corps aligné de la tête aux talons.", "Engage les fessiers et le ventre pour garder une ligne droite, sans creuser le bas du dos.", "Tiens la position en respirant calmement pendant la durée prévue.", "En version dynamique, lève une jambe à la fois en gardant le bassin stable.", "Reste loin de l'effondrement des hanches : la qualité prime sur la durée."], equipment: ["tapis (optionnel)"], commonMistakes: "Laisser les hanches s'affaisser ou monter trop haut : vise une ligne droite tête-bassin-talons."),
            en: ExerciseExplanation(steps: ["Place the elbows under the shoulders and forearms on the floor, body aligned from head to heels.", "Engage the glutes and abs to keep a straight line, without sagging the lower back.", "Hold the position breathing calmly for the planned duration.", "In the dynamic version, lift one leg at a time while keeping the pelvis stable.", "Stay clear of dropping hips: quality matters more than duration."], equipment: ["mat (optional)"], commonMistakes: "Letting the hips sag or pike up: aim for a straight head-pelvis-heels line.")),
        SeedEntry(matchers: ["sideways bench", "side plank", "planche laterale", "planche latérale"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le côté, coude sous l'épaule, corps aligné des pieds à la tête.", "Soulève les hanches pour garder le bassin haut et le tronc gainé.", "Engage les obliques et le moyen fessier pour stabiliser le côté.", "En version dynamique, monte et descends légèrement le bassin sans le poser.", "Change de côté pour équilibrer le travail gauche et droit."], equipment: ["tapis (optionnel)"], commonMistakes: "Laisser le bassin redescendre vers le sol : garde la hanche haute et le corps bien aligné."),
            en: ExerciseExplanation(steps: ["Lie on your side, elbow under the shoulder, body aligned from feet to head.", "Lift the hips to keep the pelvis high and the trunk braced.", "Engage the obliques and gluteus medius to stabilise the side.", "In the dynamic version, raise and lower the pelvis slightly without resting it.", "Switch sides to balance left and right work."], equipment: ["mat (optional)"], commonMistakes: "Letting the pelvis drop toward the floor: keep the hip high and the body well aligned.")),
        SeedEntry(matchers: ["nordic hamstring", "nhe", "nordic"],
            fr: ExerciseExplanation(steps: ["Mets-toi à genoux sur un tapis, chevilles bloquées par un partenaire ou une barre fixe.", "Garde le tronc, les hanches et les cuisses alignés, fessiers engagés.", "Descends vers l'avant très lentement en 3 à 5 secondes en retenant avec les ischio-jambiers.", "Quand tu ne peux plus retenir, amortis avec les mains au sol.", "Pousse avec les mains pour revenir au départ et limiter l'effort de remontée."], equipment: ["tapis", "partenaire ou barre fixe"], commonMistakes: "Casser la hanche vers l'arrière pour tricher : garde la ligne tronc-cuisse et descends lentement."),
            en: ExerciseExplanation(steps: ["Kneel on a mat with ankles held by a partner or a fixed bar.", "Keep the trunk, hips and thighs aligned, glutes engaged.", "Lower forward very slowly over 3 to 5 seconds, resisting with the hamstrings.", "When you can no longer hold, catch yourself with your hands on the floor.", "Push with the hands to return to the start and limit the upward effort."], equipment: ["mat", "partner or fixed bar"], commonMistakes: "Hinging the hips back to cheat: keep the trunk-thigh line and lower slowly.")),
        SeedEntry(matchers: ["conduite slalom", "conduite ballon", "conduite +", "conduite entre", "slalom"],
            fr: ExerciseExplanation(steps: ["Pousse le ballon avec de petits contacts à chaque pas, intérieur et extérieur du pied.", "Garde le ballon proche, à moins de 50 cm du pied, surtout entre les cônes serrés.", "Relève la tête entre les touches pour anticiper le prochain cône.", "Fléchis légèrement les genoux pour changer de direction sans déséquilibre.", "Alterne pied dominant et non-dominant pour conduire des deux pieds."], equipment: ["ballon", "cônes"], commonMistakes: "Pousser le ballon trop loin devant : tu cours après au lieu de garder le contrôle dans les changements de direction."),
            en: ExerciseExplanation(steps: ["Push the ball with small touches on every step, inside and outside of the foot.", "Keep the ball close, within 50 cm of the foot, especially through tight cones.", "Lift your head between touches to anticipate the next cone.", "Bend the knees slightly to change direction without losing balance.", "Alternate dominant and non-dominant foot to dribble with both feet."], equipment: ["ball", "cones"], commonMistakes: "Pushing the ball too far ahead: you end up chasing it instead of keeping control through changes of direction.")),
        SeedEntry(matchers: ["passes longues", "passe longue", "laces", "cou-de-pied", "cou de pied"],
            fr: ExerciseExplanation(steps: ["Pose le pied d'appui à côté et un peu derrière le ballon, orienté vers la cible lointaine.", "Frappe sous le ballon avec le cou-de-pied (laces) pour lui donner de la trajectoire.", "Penche légèrement le buste en arrière au moment de l'impact pour lever le ballon.", "Accompagne le geste vers le haut et l'avant pour porter la distance.", "Vise une zone de réception large autour du partenaire et alterne les pieds."], equipment: ["ballon", "partenaire ou cible"], commonMistakes: "Vouloir trop forcer dès le départ : commence par doser la trajectoire avant de chercher la puissance."),
            en: ExerciseExplanation(steps: ["Set the standing foot beside and slightly behind the ball, aimed at the distant target.", "Strike under the ball with the laces (instep) to give it a trajectory.", "Lean the torso back slightly at impact to lift the ball.", "Follow through up and forward to carry the distance.", "Aim for a wide landing zone around your partner and alternate feet."], equipment: ["ball", "partner or target"], commonMistakes: "Forcing for power right away: start by controlling the trajectory before chasing distance.")),
        SeedEntry(matchers: ["box jump", "plyometrie", "plyométrie", "vertical jump", "vertical jumps", "broad jump", "bondissement", "hex bar jump"],
            fr: ExerciseExplanation(steps: ["Place-toi face à la box, pieds largeur bassin, après un échauffement complet.", "Fléchis les genoux et balance les bras pour armer le saut.", "Saute de façon explosive et atterris souplement, genoux fléchis et dans l'axe.", "Vise une réception silencieuse pour absorber l'impact.", "Redescends en marchant plutôt qu'en sautant, et reste sur des hauteurs maîtrisées."], equipment: ["box ou step"], commonMistakes: "Atterrir jambes raides ou genoux qui rentrent : cherche une réception souple et alignée à chaque saut."),
            en: ExerciseExplanation(steps: ["Stand facing the box, feet hip-width apart, after a full warm-up.", "Bend the knees and swing the arms to load the jump.", "Jump explosively and land softly, knees bent and aligned.", "Aim for a quiet landing to absorb the impact.", "Step back down rather than jumping down, and stay on heights you can control."], equipment: ["box or step"], commonMistakes: "Landing with stiff legs or knees caving in: aim for a soft, aligned landing on every jump.")),
        SeedEntry(matchers: ["jeu de tete", "jeu de tête", "tete frontale", "tête frontale", "tete simple", "tête simple"],
            fr: ExerciseExplanation(steps: ["Place-toi sous la trajectoire du ballon, genoux fléchis et regard sur le ballon.", "Contracte le cou et le tronc pour garder la tête ferme à l'impact.", "Touche le ballon avec le front (jamais le sommet ni la nuque), yeux ouverts.", "Avance le buste vers le ballon pour donner la direction plutôt que d'attendre passivement.", "Commence avec un ballon léger ou semi-gonflé et augmente l'engagement progressivement."], equipment: ["ballon léger", "partenaire"], commonMistakes: "Fermer les yeux et subir le ballon : garde le front et le regard actifs pour contrôler le contact."),
            en: ExerciseExplanation(steps: ["Position yourself under the ball's flight, knees bent and eyes on the ball.", "Brace the neck and trunk to keep the head firm at impact.", "Contact the ball with the forehead (never the top or back of the head), eyes open.", "Move the torso into the ball to give it direction rather than waiting passively.", "Start with a light or partly inflated ball and build engagement gradually."], equipment: ["light ball", "partner"], commonMistakes: "Closing the eyes and letting the ball arrive: keep the forehead and gaze active to control the contact.")),
        SeedEntry(matchers: ["lateral bound", "lateral hops", "saut lateral", "saut latéral"],
            fr: ExerciseExplanation(steps: ["Pars en appui sur une jambe, genou légèrement fléchi.", "Saute latéralement vers l'autre jambe en poussant fort sur l'extérieur du pied.", "Atterris sur la jambe d'arrivée et stabilise-toi 1 à 2 secondes avant de repartir.", "Garde le genou d'appui aligné au-dessus du pied, sans le laisser rentrer.", "Ajuste la distance selon ton niveau et soigne la stabilité de réception."], equipment: [], commonMistakes: "Enchaîner trop vite sans stabiliser : marque l'arrêt à la réception pour travailler le contrôle latéral."),
            en: ExerciseExplanation(steps: ["Start balanced on one leg, knee slightly bent.", "Bound sideways onto the other leg by pushing hard off the outside of the foot.", "Land on the landing leg and stabilise for 1 to 2 seconds before bounding back.", "Keep the support knee aligned over the foot, not letting it cave in.", "Adjust the distance to your level and focus on a stable landing."], equipment: [], commonMistakes: "Chaining bounds too fast without stabilising: mark the stop on landing to train lateral control.")),
        SeedEntry(matchers: ["hip thrust", "pont fessier", "glute bridge"],
            fr: ExerciseExplanation(steps: ["Pose les épaules sur un banc (hip thrust) ou allonge-toi au sol (pont fessier), pieds à plat largeur bassin.", "Monte les hanches en poussant dans les talons jusqu'à l'extension complète.", "Contracte les fessiers 1 à 2 secondes en haut, sans cambrer le bas du dos.", "Redescends de façon contrôlée sans relâcher complètement.", "Pour la version unilatérale, garde le bassin bien horizontal sur une seule jambe."], equipment: ["banc ou marche (optionnel)", "haltère ou barre (optionnel)"], commonMistakes: "Cambrer le bas du dos en haut au lieu d'engager les fessiers : pousse les hanches sans creuser les lombaires."),
            en: ExerciseExplanation(steps: ["Rest the shoulders on a bench (hip thrust) or lie on the floor (glute bridge), feet flat at hip width.", "Lift the hips by driving through the heels to full extension.", "Squeeze the glutes for 1 to 2 seconds at the top, without arching the lower back.", "Lower in a controlled way without fully releasing.", "For the single-leg version, keep the pelvis level on one leg."], equipment: ["bench or step (optional)", "dumbbell or barbell (optional)"], commonMistakes: "Arching the lower back at the top instead of engaging the glutes: drive the hips without overextending the lumbar.")),
        SeedEntry(matchers: ["bench press"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le banc, pieds bien ancrés au sol, omoplates serrées.", "Tiens la barre ou les haltères largeur épaules, poignets droits.", "Descends la charge de façon contrôlée vers la poitrine.", "Pousse vers le haut en gardant les coudes à un angle modéré du tronc.", "Garde un appui stable et une charge confortable, avec un pareur ou des butées si besoin."], equipment: ["banc", "haltères ou barre"], commonMistakes: "Décoller les fessiers ou rebondir la barre sur la poitrine : garde un appui stable et un mouvement contrôlé."),
            en: ExerciseExplanation(steps: ["Lie on the bench, feet anchored to the floor, shoulder blades retracted.", "Hold the bar or dumbbells shoulder-width apart, wrists straight.", "Lower the load in a controlled way toward the chest.", "Press up keeping the elbows at a moderate angle from the trunk.", "Keep a stable base and a comfortable load, with a spotter or safety bars if needed."], equipment: ["bench", "dumbbells or barbell"], commonMistakes: "Lifting the glutes or bouncing the bar off the chest: keep a stable base and a controlled movement.")),
        SeedEntry(matchers: ["calf raises", "calf raise", "mollet"],
            fr: ExerciseExplanation(steps: ["Tiens-toi debout, pieds largeur bassin, regard devant.", "Monte sur la pointe des pieds en poussant fort dans les orteils.", "Tiens 2 secondes en haut, contraction des mollets.", "Redescends lentement les talons pour travailler l'amplitude complète.", "Pour progresser, ajoute des maintiens isométriques ou passe en unilatéral."], equipment: ["marche (optionnel)"], commonMistakes: "Rebondir en bas sans contrôler : descends lentement pour profiter de toute l'amplitude."),
            en: ExerciseExplanation(steps: ["Stand tall, feet hip-width apart, eyes forward.", "Rise onto the balls of the feet by driving hard through the toes.", "Hold 2 seconds at the top, calves contracted.", "Lower the heels slowly to work the full range of motion.", "To progress, add isometric holds or switch to single-leg."], equipment: ["step (optional)"], commonMistakes: "Bouncing at the bottom without control: lower slowly to use the full range of motion.")),
        SeedEntry(matchers: ["jeu reduit", "jeu réduit", "5v5", "4v4", "3v3", "6v6", "jeu 5v5", "jeu 4v4", "jeu 3v3"],
            fr: ExerciseExplanation(steps: ["Délimite un terrain réduit avec des mini-buts et forme les équipes.", "Fixe une contrainte (2 ou 3 touches max) pour accélérer le jeu et la prise de décision.", "Enchaîne les phases de jeu intense puis récupère en marche entre les séries.", "Cherche la transition rapide attaque-défense dès la perte ou la récupération du ballon.", "Hydrate-toi entre les séries et garde l'intensité cible sur chaque bloc."], equipment: ["ballon", "mini-buts ou cônes", "chasubles (optionnel)"], commonMistakes: "Rester statique en perdant le ballon : la transition immédiate est le cœur du travail en jeu réduit."),
            en: ExerciseExplanation(steps: ["Mark out a small pitch with mini-goals and form the teams.", "Set a constraint (2 or 3 touch max) to speed up play and decision-making.", "Alternate intense playing phases then recover by walking between sets.", "Look for the quick attack-defence transition as soon as the ball is lost or won.", "Hydrate between sets and keep the target intensity on each block."], equipment: ["ball", "mini-goals or cones", "bibs (optional)"], commonMistakes: "Standing still when you lose the ball: the immediate transition is the core of small-sided work.")),
        SeedEntry(matchers: ["jongles", "jonglage", "jongle"],
            fr: ExerciseExplanation(steps: ["Lâche le ballon depuis les mains et touche-le doucement, surface stable (cuisse ou intérieur du pied).", "Garde la cheville verrouillée et frappe par en dessous pour renvoyer le ballon à hauteur de hanche.", "Reste sur place, genoux souples, et suis le ballon des yeux à chaque contact.", "Enchaîne quelques contacts puis recommence si le ballon tombe, sans te crisper.", "Augmente progressivement le nombre de contacts d'affilée au fil des séances."], equipment: ["ballon"], commonMistakes: "Frapper trop fort : le ballon part trop haut et devient incontrôlable, vise des touches douces et régulières."),
            en: ExerciseExplanation(steps: ["Drop the ball from your hands and touch it gently with a stable surface (thigh or inside of the foot).", "Keep the ankle locked and tap from underneath to send the ball back to hip height.", "Stay on the spot, knees soft, and track the ball with your eyes on each contact.", "Link a few touches then restart if the ball drops, without tensing up.", "Gradually increase the number of touches in a row over the sessions."], equipment: ["ball"], commonMistakes: "Tapping too hard: the ball flies up and becomes uncontrollable, aim for soft, steady touches.")),
        SeedEntry(matchers: ["bird-dog", "bird dog"],
            fr: ExerciseExplanation(steps: ["Place-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.", "Tends le bras opposé à la jambe opposée jusqu'à l'horizontale.", "Garde le bassin stable et le dos neutre, sans rotation du tronc.", "Tiens 2 secondes puis reviens lentement avant de changer de côté.", "Engage le ventre tout du long pour limiter les balancements."], equipment: ["tapis (optionnel)"], commonMistakes: "Laisser le bassin pivoter quand tu tends le bras et la jambe : garde-le stable et parallèle au sol."),
            en: ExerciseExplanation(steps: ["Get on all fours, hands under the shoulders and knees under the hips.", "Extend the opposite arm to the opposite leg until horizontal.", "Keep the pelvis stable and the back neutral, without trunk rotation.", "Hold 2 seconds then return slowly before switching sides.", "Engage the abs throughout to limit any swaying."], equipment: ["mat (optional)"], commonMistakes: "Letting the pelvis rotate as you extend arm and leg: keep it stable and parallel to the floor.")),

        // MARK: cycling (28)
        SeedEntry(matchers: ["planche ventrale", "planche ventrale + dorsale", "planche ventrale isometrique", "planche ventrale isométrique", "planche ventrale legere", "planche ventrale légère", "front plank"],
            fr: ExerciseExplanation(steps: ["Place les coudes sous les épaules, avant-bras au sol, corps aligné de la tête aux talons.", "Engage les abdos et serre légèrement les fessiers pour éviter que le bas du dos ne creuse.", "Garde le regard vers le sol et la nuque dans le prolongement du dos.", "Tiens la position en respirant calmement pour la durée indiquée."], equipment: ["tapis"], commonMistakes: "Laisser le bassin s'affaisser ou remonter les fesses au lieu de garder une ligne droite."),
            en: ExerciseExplanation(steps: ["Place your elbows under your shoulders, forearms on the floor, body in a line from head to heels.", "Brace your abs and gently squeeze your glutes so the lower back does not sag.", "Keep your gaze toward the floor and your neck in line with your back.", "Hold the position breathing calmly for the prescribed duration."], equipment: ["mat"], commonMistakes: "Letting the hips drop or piking them up instead of holding a straight line.")),
        SeedEntry(matchers: ["sprint", "sprints d'activation", "sprints opener", "opener sprint", "depart z6", "départ z6", "ftp-z6", "ftp-z7", "strides", "activation neuromusculaire", "sprint depart", "sprint départ", "pre-race opener", "opener"],
            fr: ExerciseExplanation(steps: ["Sur un plateau roulant, lance une accélération courte et franche (8 à 30 secondes selon le bloc).", "Monte vite la cadence, autour de 100 à 115 rpm, en cherchant la vivacité plus que la grosse force.", "Reste assis ou en danseuse selon ton aisance, mais garde le vélo stable.", "Récupère complètement en FTP-Z1 entre chaque (2 à 3 minutes) pour repartir frais.", "L'idée est de réveiller les fibres rapides, pas de t'épuiser : qualité plutôt que volume."], equipment: ["vélo"], commonMistakes: "Enchaîner les sprints sans récup complète et perdre la vivacité dès la deuxième répétition."),
            en: ExerciseExplanation(steps: ["On a rolling flat, launch a short, sharp acceleration (8 to 30 seconds depending on the block).", "Spin the cadence up fast, around 100 to 115 rpm, chasing snap rather than raw force.", "Stay seated or stand depending on your comfort, but keep the bike steady.", "Recover fully in FTP-Z1 between each (2 to 3 minutes) to start fresh.", "The point is to wake up the fast fibres, not to drain yourself: quality over volume."], equipment: ["bike"], commonMistakes: "Chaining sprints without full recovery and losing snap from the second rep onward.")),
        SeedEntry(matchers: ["long ride", "longue", "sortie longue", "150 km", "140 km", "130 km", "simulation course", "simulation cyclosportive", "pic montagne", "montagne z2", "ravito", "ravitaillement", "simulation ravitaillement", "80 km ftp-z2", "82 km", "78 km"],
            fr: ExerciseExplanation(steps: ["Garde une base FTP-Z2 conversationnelle (RPE 2 à 3) sur la majorité de la sortie.", "Pars prudemment : sur le premier tiers, reste 5 % sous ton allure cible pour gérer l'adrénaline.", "Sur les inclusions Z3 ou les côtes, monte d'intensité de façon contrôlée puis redescends en Z2.", "Mange et bois régulièrement : vise 60 à 90 g de glucides et un bidon par heure.", "Teste ton matériel et ton plan nutrition comme une répétition du jour J."], equipment: ["vélo", "bidons", "gels ou barres"], commonMistakes: "Partir trop vite et négliger le ravitaillement dans la première heure, puis s'effondrer en fin de sortie."),
            en: ExerciseExplanation(steps: ["Keep a conversational FTP-Z2 base (RPE 2 to 3) for most of the ride.", "Start cautiously: on the first third, stay 5% below target pace to manage the early adrenaline.", "On Z3 inclusions or climbs, lift the intensity in a controlled way, then ease back to Z2.", "Eat and drink steadily: aim for 60 to 90 g of carbs and one bottle per hour.", "Test your gear and nutrition plan as a dress rehearsal for race day."], equipment: ["bike", "water bottles", "gels or bars"], commonMistakes: "Going out too hard and skipping fuelling in the first hour, then fading badly at the end.")),
        SeedEntry(matchers: ["vo2max", "vo2 max", "ftp-z5", "intervalles ftp-z5", "intervalles courts ftp-z5", "intervalles z5", "z5"],
            fr: ExerciseExplanation(steps: ["Vise FTP-Z5 (106 à 120 % FTP, RPE 6 à 7) : parler devient impossible.", "Dose le pacing : commence un peu prudent, c'est dur au milieu, max sur la fin.", "Garde une cadence libre élevée, autour de 95 à 105 rpm, pour mobiliser le cardio.", "Récupère en FTP-Z1 entre les répétitions, mais sans laisser le cardio retomber complètement.", "Cherche des répétitions régulières plutôt qu'un premier intervalle héroïque suivi d'un effondrement."], equipment: ["vélo", "home trainer (optionnel)"], commonMistakes: "Démarrer à 130 % FTP sur la première répétition et ne plus tenir la zone sur la seconde moitié."),
            en: ExerciseExplanation(steps: ["Aim for FTP-Z5 (106 to 120% FTP, RPE 6 to 7): talking becomes impossible.", "Manage the pacing: start a touch conservative, it is hard in the middle, all-out at the end.", "Hold a high free cadence, around 95 to 105 rpm, to drive the cardio system.", "Recover in FTP-Z1 between reps, but without letting the heart rate drop all the way down.", "Aim for consistent reps rather than a heroic first interval followed by a collapse."], equipment: ["bike", "home trainer (optional)"], commonMistakes: "Starting at 130% FTP on the first rep and failing to hold the zone in the second half.")),
        SeedEntry(matchers: ["sfr", "force basse cadence", "basse cadence", "repetitions cote", "répétitions côte", "cotes longues", "côtes longues", "repetitions cote longues", "force specifique"],
            fr: ExerciseExplanation(steps: ["Cherche une côte régulière de 4 à 8 % ou mets de la résistance haute sur le home trainer.", "Pose un gros braquet et tourne lentement, autour de 50 à 65 rpm, en restant assis.", "Vise un effort FTP-Z3 à Z4 (RPE 4 à 5) avec un pédalage appuyé mais rond et fluide.", "Garde le dos plat et les épaules relâchées, sans tirer sur le guidon.", "En descente ou en récup, repasse en cadence élevée et faible résistance pour relâcher."], equipment: ["vélo", "home trainer (optionnel)"], commonMistakes: "Se cambrer et tirer sur le guidon au lieu de garder un pédalage rond et un tronc stable."),
            en: ExerciseExplanation(steps: ["Find a steady 4 to 8% climb or set high resistance on the home trainer.", "Push a big gear and turn slowly, around 50 to 65 rpm, staying seated.", "Aim for an FTP-Z3 to Z4 effort (RPE 4 to 5) with a strong but round, fluid pedal stroke.", "Keep your back flat and shoulders relaxed, without yanking on the bars.", "On the descent or recovery, return to high cadence and low resistance to relax."], equipment: ["bike", "home trainer (optional)"], commonMistakes: "Arching the back and pulling on the bars instead of keeping a round stroke and a stable torso.")),
        SeedEntry(matchers: ["deadlift roumain", "romanian deadlift", "souleve de terre roumain", "soulevé de terre roumain"],
            fr: ExerciseExplanation(steps: ["Debout, charge légère en mains, pieds largeur de hanches et genoux légèrement fléchis.", "Pousse les hanches vers l'arrière en gardant le dos plat tout au long du mouvement.", "Descends la charge le long des jambes jusqu'à mi-tibia, en sentant l'étirement des ischios.", "Reviens en poussant les hanches vers l'avant, sans arrondir le bas du dos."], equipment: ["haltères ou barre légère"], commonMistakes: "Arrondir le dos en descendant au lieu de garder une charnière de hanche dos plat."),
            en: ExerciseExplanation(steps: ["Stand with a light load in your hands, feet hip-width and knees slightly bent.", "Hinge your hips backward while keeping your back flat throughout the movement.", "Lower the load along your legs to mid-shin, feeling the stretch in your hamstrings.", "Return by driving the hips forward, without rounding the lower back."], equipment: ["dumbbells or light barbell"], commonMistakes: "Rounding the back on the way down instead of keeping a flat-back hip hinge.")),
        SeedEntry(matchers: ["activation ftp-z1-z2", "remise en jambes", "activation j-2", "mise en route", "race week", "bloc z2 court", "bloc endurance z2 court", "bloc z2 + sprints", "bloc z2 + 2 sprints", "bloc z2 + 3 sprints"],
            fr: ExerciseExplanation(steps: ["Roule en FTP-Z1 puis FTP-Z2 souple (RPE 2 à 3 maximum), cadence 85 à 90 rpm sur du plat.", "Ce n'est pas un test : l'objectif est d'arriver frais et alerte, pas fatigué.", "Si la séance inclut quelques sprints courts, garde-les vifs et récupère bien entre chacun.", "Profites-en pour vérifier ton matériel et tes sensations avant l'échéance."], equipment: ["vélo"], commonMistakes: "Transformer une mise en jambes en séance intense parce que les jambes répondent bien."),
            en: ExerciseExplanation(steps: ["Ride in FTP-Z1 then easy FTP-Z2 (RPE 2 to 3 max), cadence 85 to 90 rpm on the flat.", "This is not a test: the goal is to arrive fresh and alert, not tired.", "If the session includes a few short sprints, keep them sharp and recover well between each.", "Use it to check your gear and how you feel before the event."], equipment: ["bike"], commonMistakes: "Turning a leg-opener into an intense session because the legs are responding well.")),
        SeedEntry(matchers: ["pont fessier", "pont fessier bipodal", "pont fessier unilateral", "pont fessier unilatéral", "glute bridge"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le dos, pieds à plat largeur de hanches, talons proches des fesses.", "Pousse dans les talons et monte le bassin en serrant fort les fessiers.", "Monte jusqu'à former une ligne droite genoux-hanches-épaules, sans cambrer le bas du dos.", "Tiens 2 secondes en haut, puis redescends en contrôle.", "Sur la version unilatérale, garde le bassin de niveau en tendant une jambe."], equipment: ["tapis"], commonMistakes: "Monter en cambrant le bas du dos au lieu d'aller chercher la poussée dans les fessiers."),
            en: ExerciseExplanation(steps: ["Lie on your back, feet flat hip-width apart, heels close to your glutes.", "Drive through your heels and lift your hips by squeezing the glutes hard.", "Rise until you form a straight line knee-hip-shoulder, without arching the lower back.", "Hold 2 seconds at the top, then lower with control.", "On the single-leg version, keep the pelvis level while extending one leg."], equipment: ["mat"], commonMistakes: "Lifting by arching the lower back instead of driving the movement from the glutes.")),
        SeedEntry(matchers: ["calf raises", "calf raises bipodal", "calf raises sureleves", "calf raises surélevés", "single-leg calf raises", "mollets"],
            fr: ExerciseExplanation(steps: ["Debout, ou en appui sur le bord d'une marche pour gagner en amplitude.", "Monte sur les pointes de pieds en contrôle, en cherchant la hauteur maximale.", "Sur la version surélevée, laisse le talon descendre sous le niveau de la marche.", "Redescends lentement (4 secondes sur la version excentrique) pour bien charger le mollet."], equipment: ["marche (optionnelle)"], commonMistakes: "Rebondir vite en haut sans amplitude complète, ce qui réduit le travail du mollet."),
            en: ExerciseExplanation(steps: ["Stand tall, or balance on the edge of a step for greater range.", "Rise onto the balls of your feet under control, reaching maximum height.", "On the raised version, let the heel drop below the level of the step.", "Lower slowly (4 seconds on the eccentric version) to load the calf fully."], equipment: ["step (optional)"], commonMistakes: "Bouncing quickly at the top without full range, reducing the work on the calf.")),
        SeedEntry(matchers: ["recovery", "recuperation", "récupération", "ftp-z1", "pedalage recuperation", "pédalage récupération", "z1 recuperation", "tres courte ftp-z1", "très courte ftp-z1"],
            fr: ExerciseExplanation(steps: ["Reste en zone très facile (FTP-Z1, RPE 1 à 2) : tu peux chanter sans être essoufflé.", "Garde une cadence libre et fluide autour de 85 à 95 rpm, sur du plat ou home trainer.", "Pédale en souplesse, sans jamais forcer, même si les jambes se sentent bien.", "Le but est de relancer la circulation et de préparer les muscles, pas de chercher un stimulus."], equipment: ["vélo", "home trainer (optionnel)"], commonMistakes: "Accélérer parce que les jambes se sentent fraîches, ce qui transforme la récup en vraie séance."),
            en: ExerciseExplanation(steps: ["Stay in a very easy zone (FTP-Z1, RPE 1 to 2): you could sing without getting out of breath.", "Keep a free, smooth cadence around 85 to 95 rpm, on flat ground or a home trainer.", "Pedal lightly without ever forcing, even if your legs feel good.", "The goal is to boost circulation and prime the muscles, not to chase a training stimulus."], equipment: ["bike", "home trainer (optional)"], commonMistakes: "Speeding up because your legs feel fresh, which turns a recovery ride into a real session.")),
        SeedEntry(matchers: ["cadence 90", "cadence 90-95", "cadence haute ftp-z2", "cadence haute", "cadence elevee", "cadence élevée", "travail cadence haute", "cadence 100-105", "cadence alternee", "cadence alternée", "sprints de cadence"],
            fr: ExerciseExplanation(steps: ["Reste en FTP-Z2 (RPE 2 à 3) tout en imposant une cadence plus haute, autour de 90 à 105 rpm.", "Choisis un braquet facile pour faire tourner les jambes sans monter en intensité cardio.", "Cherche un pédalage rond et silencieux : pas de rebond sur la selle.", "Sur les blocs alternés, reviens à 85 rpm en récup pour relâcher avant la série suivante."], equipment: ["vélo", "home trainer (optionnel)"], commonMistakes: "Crisper le haut du corps et rebondir sur la selle quand la cadence monte."),
            en: ExerciseExplanation(steps: ["Stay in FTP-Z2 (RPE 2 to 3) while holding a higher cadence, around 90 to 105 rpm.", "Pick an easy gear so the legs spin without raising your cardio intensity.", "Aim for a round, quiet pedal stroke with no bouncing on the saddle.", "On alternating blocks, drop back to 85 rpm during recovery to relax before the next set."], equipment: ["bike", "home trainer (optional)"], commonMistakes: "Tensing the upper body and bouncing on the saddle as the cadence climbs.")),
        SeedEntry(matchers: ["sweet-spot", "sweet spot", "blocs sweet spot", "initiation sweet spot", "sweet-spot 88-94"],
            fr: ExerciseExplanation(steps: ["Vise le sweet-spot (88 à 94 % FTP, RPE 3 à 4) : effort soutenu mais tenable longtemps.", "Tu parles par phrases brèves, respiration soutenue mais contrôlée. Cadence 85 à 95 rpm.", "Garde la même intensité du début à la fin du bloc, sans pousser au-delà.", "Récupère en FTP-Z1 souple entre les intervalles pour repartir propre.", "Joue sur la cadence et la résistance pour éviter de te crisper mentalement sur un bloc long."], equipment: ["vélo", "home trainer (optionnel)"], commonMistakes: "Monter au-dessus du sweet-spot et basculer dans le seuil, ce qui coûte trop en fatigue pour le bénéfice."),
            en: ExerciseExplanation(steps: ["Aim for the sweet spot (88 to 94% FTP, RPE 3 to 4): a sustained effort you can hold for a long time.", "You speak in short phrases, breathing strong but controlled. Cadence 85 to 95 rpm.", "Hold the same intensity from start to finish of the block, without pushing beyond it.", "Recover at easy FTP-Z1 between intervals to start each one clean.", "Vary cadence and resistance to avoid tensing up mentally on a long block."], equipment: ["bike", "home trainer (optional)"], commonMistakes: "Drifting above the sweet spot into threshold, which costs too much fatigue for the benefit.")),
        SeedEntry(matchers: ["hip thrust", "hip thrust charge", "hip thrust chargé", "hip thrust maintien", "hip thrust dos au sol"],
            fr: ExerciseExplanation(steps: ["Cale le haut du dos sur un banc ou un canapé bas, pieds à plat largeur de hanches.", "Place une charge sur les hanches (haltère, sac chargé ou élastique) si la version chargée est prévue.", "Pousse dans les talons et monte les hanches en serrant les fessiers, tibias verticaux.", "Tiens 2 secondes en haut, hanches alignées avec le tronc, puis redescends en contrôle."], equipment: ["banc ou canapé bas", "charge (optionnelle)"], commonMistakes: "Cambrer le bas du dos en haut au lieu de finir le mouvement par une contraction fessière."),
            en: ExerciseExplanation(steps: ["Rest your upper back on a bench or low couch, feet flat hip-width apart.", "Place a load on your hips (dumbbell, loaded bag or band) if the loaded version is planned.", "Drive through your heels and lift your hips by squeezing the glutes, shins vertical.", "Hold 2 seconds at the top, hips aligned with the torso, then lower with control."], equipment: ["bench or low couch", "load (optional)"], commonMistakes: "Arching the lower back at the top instead of finishing the move with a glute squeeze.")),
        SeedEntry(matchers: ["etirements epaules", "étirements épaules", "cervicales", "epaules et cervicales", "épaules et cervicales", "trapeze"],
            fr: ExerciseExplanation(steps: ["Pour les pectoraux, place l'avant-bras contre un mur et tourne doucement le buste pour ouvrir l'épaule.", "Fais des cercles cervicaux lents pour relâcher la nuque, sollicitée en position guidon.", "Pour le trapèze, incline la tête sur le côté et accompagne légèrement avec la main.", "Reste sur des sensations douces et une respiration calme, sans tirer brusquement."], equipment: ["mur"], commonMistakes: "Tirer fort sur la tête ou la nuque au lieu d'un étirement progressif et contrôlé."),
            en: ExerciseExplanation(steps: ["For the chest, place your forearm against a wall and gently turn your torso to open the shoulder.", "Do slow neck circles to release the neck, which works hard in the handlebar position.", "For the traps, tilt your head to the side and guide gently with your hand.", "Stay with soft sensations and calm breathing, without pulling sharply."], equipment: ["wall"], commonMistakes: "Pulling hard on the head or neck instead of a gradual, controlled stretch.")),
        SeedEntry(matchers: ["endurance z2", "endurance ftp-z2", "continue ftp-z2", "continu ftp-z2", "sortie endurance", "sortie continue", "z2 endurance", "bloc z2", "bloc endurance z2", "activation ftp-z1-z2", "vallonnee ftp-z2", "vallonnée ftp-z2"],
            fr: ExerciseExplanation(steps: ["Cale-toi en FTP-Z2 (RPE 2 à 3) : tu tiens une conversation complète sans gasper.", "Vise une cadence souple de 85 à 95 rpm sur le plat, fluide et régulière.", "Sur une côte, passe au braquet inférieur avant la pente pour garder la cadence et la zone.", "Pense hydratation et apport glucidique léger si la sortie dépasse 45 minutes.", "Garde de la marge : l'idée est de finir frais, pas vidé."], equipment: ["vélo", "bidon", "home trainer (optionnel)"], commonMistakes: "Dériver vers le rouge dès qu'une côte arrive et casser le caractère aérobie de la séance."),
            en: ExerciseExplanation(steps: ["Settle into FTP-Z2 (RPE 2 to 3): you can hold a full conversation without gasping.", "Aim for a smooth 85 to 95 rpm cadence on the flat, fluid and steady.", "On a climb, shift to an easier gear before the gradient to keep your cadence and zone.", "Plan for hydration and a light carbohydrate intake if the ride runs past 45 minutes.", "Keep a buffer: the idea is to finish fresh, not drained."], equipment: ["bike", "water bottle", "home trainer (optional)"], commonMistakes: "Drifting into the red as soon as a climb appears, breaking the aerobic nature of the ride.")),
        SeedEntry(matchers: ["tempo", "ftp-z3", "z3 tempo", "blocs ftp-z3", "tempo continu", "tempo ftp-z3", "z3 long", "allure cyclosportive"],
            fr: ExerciseExplanation(steps: ["Installe-toi en FTP-Z3 (RPE 3 à 4) : tu parles par phrases courtes uniquement.", "Vise une cadence de 85 à 92 rpm et un effort homogène, sans à-coups.", "C'est un effort soutenu mais maîtrisé, pas un sprint : garde la même puissance du début à la fin.", "Entre les blocs, redescends en FTP-Z2 souple pour relâcher avant de repartir."], equipment: ["vélo", "home trainer (optionnel)"], commonMistakes: "Démarrer le bloc trop fort puis ne plus tenir l'allure sur la fin."),
            en: ExerciseExplanation(steps: ["Settle into FTP-Z3 (RPE 3 to 4): you can only speak in short sentences.", "Aim for an 85 to 92 rpm cadence and a steady, even effort with no surges.", "This is a sustained but controlled effort, not a sprint: hold the same power start to finish.", "Between blocks, ease back to relaxed FTP-Z2 to recover before the next one."], equipment: ["bike", "home trainer (optional)"], commonMistakes: "Starting the block too hard, then being unable to hold the pace toward the end.")),
        SeedEntry(matchers: ["cote 6-8", "côte 6-8", "repetitions cote 6-8", "côtes 6-9", "cote longue", "côte longue", "monter cote", "pente"],
            fr: ExerciseExplanation(steps: ["Choisis une côte de 4 à 9 % et monte à un effort soutenu (FTP-Z3 à Z4, RPE 4 à 8 en fin).", "Reste assis, dos plat, cadence 65 à 80 rpm sur un braquet résistant.", "Vise la régularité : un effort homogène plutôt qu'une attaque suivie d'un essoufflement.", "Redescends en récupération FTP-Z1, cadence libre, avant la répétition suivante."], equipment: ["vélo"], commonMistakes: "Attaquer le bas de la côte trop fort et finir le haut à l'agonie sans tenir la zone."),
            en: ExerciseExplanation(steps: ["Pick a 4 to 9% climb and ride up at a sustained effort (FTP-Z3 to Z4, RPE 4 up to 8 by the end).", "Stay seated, back flat, cadence 65 to 80 rpm in a resistant gear.", "Aim for consistency: an even effort rather than an attack followed by gasping.", "Roll back down in FTP-Z1 recovery, free cadence, before the next rep."], equipment: ["bike"], commonMistakes: "Attacking the bottom of the climb too hard and crawling over the top out of the zone.")),
        SeedEntry(matchers: ["squat", "squat avec charge", "squat maintien", "squat charge", "squat allege", "squat allégé", "single-leg squat", "squat charge reduite", "squat charge réduite"],
            fr: ExerciseExplanation(steps: ["Pieds largeur d'épaules, pointes légèrement ouvertes, dos plat et regard devant.", "Descends en poussant les hanches vers l'arrière, genoux dans l'axe des pieds.", "Vise une descente cuisses parallèles au sol, talons bien ancrés.", "Remonte en poussant dans les talons, sans arrondir le bas du dos.", "Sur la version chargée, garde une forme stricte et adapte la charge à ton ressenti d'effort."], equipment: ["barre ou haltères (optionnel)"], commonMistakes: "Laisser les genoux rentrer vers l'intérieur ou arrondir le dos sous la charge."),
            en: ExerciseExplanation(steps: ["Feet shoulder-width, toes slightly out, back flat and gaze forward.", "Lower by pushing your hips back, knees tracking in line with your feet.", "Aim to descend until your thighs are parallel to the floor, heels firmly planted.", "Drive back up through your heels, without rounding the lower back.", "On the loaded version, keep strict form and match the load to your effort feel."], equipment: ["barbell or dumbbells (optional)"], commonMistakes: "Letting the knees cave inward or rounding the back under the load.")),
        SeedEntry(matchers: ["etirements psoas", "étirements psoas", "etirement ilio-psoas", "étirement ilio-psoas", "etirement quadriceps", "étirement quadriceps", "psoas et quadriceps"],
            fr: ExerciseExplanation(steps: ["Place-toi en fente avant, genou arrière au sol et bassin légèrement avancé.", "Cherche un étirement doux à l'avant de la hanche de la jambe arrière.", "Pour le quadriceps, ramène le talon vers la fesse en gardant la hanche en extension.", "Respire calmement et tiens l'étirement sans à-coups le temps indiqué, sans chercher l'extrême."], equipment: ["tapis"], commonMistakes: "Cambrer le bas du dos pour gagner en amplitude au lieu d'engager le bassin doucement."),
            en: ExerciseExplanation(steps: ["Set up in a lunge, back knee on the floor and pelvis slightly forward.", "Look for a gentle stretch at the front of the back-leg hip.", "For the quad, draw the heel toward the glute while keeping the hip extended.", "Breathe calmly and hold the stretch smoothly for the given time, without forcing the extreme."], equipment: ["mat"], commonMistakes: "Arching the lower back to gain range instead of gently engaging the pelvis.")),
        SeedEntry(matchers: ["threshold", "seuil", "intervalles seuil", "ftp-z4", "intervalles ftp-z4", "z4 seuil", "split negatif", "split négatif", "activation seuil"],
            fr: ExerciseExplanation(steps: ["Installe-toi au seuil (FTP-Z4, 91 à 105 % FTP, RPE 7 à 8) : seuls des mots isolés passent.", "Pars sur un effort homogène, pas de départ en trombe, et tiens la puissance jusqu'au bout.", "Garde une cadence de 85 à 95 rpm et un haut du corps relâché.", "Récupère en FTP-Z1 cadence libre entre les intervalles.", "Si la puissance dérive nettement sur le dernier intervalle, mieux vaut écourter que t'enliser."], equipment: ["vélo", "home trainer (optionnel)"], commonMistakes: "Partir trop vite sur le premier intervalle et voir la puissance s'effondrer sur les suivants."),
            en: ExerciseExplanation(steps: ["Settle at threshold (FTP-Z4, 91 to 105% FTP, RPE 7 to 8): only isolated words come out.", "Open with an even effort, no flying start, and hold the power to the end.", "Keep an 85 to 95 rpm cadence and a relaxed upper body.", "Recover in FTP-Z1 at free cadence between intervals.", "If power clearly fades on the last interval, it is better to cut it short than to grind on."], equipment: ["bike", "home trainer (optional)"], commonMistakes: "Going out too fast on the first interval and watching power collapse on the rest.")),
        SeedEntry(matchers: ["routine mobilite", "routine mobilité", "mobilite post-velo", "mobilité post-vélo", "mobilite", "mobilité"],
            fr: ExerciseExplanation(steps: ["Enchaîne quelques mobilisations douces après le vélo : ouverture de hanche, fessiers, bas du dos.", "Tiens chaque position 30 à 45 secondes par côté en respirant tranquillement.", "Inclus les mollets debout et en flexion plantaire pour relâcher l'arrière de la jambe.", "Reste sur des amplitudes confortables : l'objectif est de relâcher, pas de performer."], equipment: ["tapis"], commonMistakes: "Forcer les amplitudes à froid au lieu de mobiliser progressivement après l'effort."),
            en: ExerciseExplanation(steps: ["Flow through a few gentle mobilisations after the ride: hip opener, glutes, lower back.", "Hold each position 30 to 45 seconds per side, breathing easily.", "Include standing and plantar-flexed calf work to release the back of the leg.", "Stay within comfortable ranges: the goal is to relax, not to perform."], equipment: ["mat"], commonMistakes: "Forcing ranges while cold instead of mobilising gradually after the effort.")),
        SeedEntry(matchers: ["planche dorsale", "extension dorsale", "back extension", "superman"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le ventre, bras tendus devant et jambes allongées.", "Lève en alternance un bras et la jambe opposée, en restant gainé.", "Tiens la contraction 2 secondes en haut, sans forcer la cambrure du bas du dos.", "Redescends en contrôle avant d'alterner avec l'autre côté."], equipment: ["tapis"], commonMistakes: "Lever trop haut en hyperextension brusque au lieu d'un mouvement contrôlé et tenu."),
            en: ExerciseExplanation(steps: ["Lie face down, arms extended in front and legs straight.", "Raise one arm and the opposite leg alternately while keeping your core engaged.", "Hold the contraction 2 seconds at the top, without overarching the lower back.", "Lower with control before switching to the other side."], equipment: ["mat"], commonMistakes: "Jerking up into a sharp overextension instead of a controlled, held movement.")),
        SeedEntry(matchers: ["side plank", "planche laterale", "planche latérale", "gainage lateral", "gainage latéral"],
            fr: ExerciseExplanation(steps: ["Appuie-toi sur l'avant-bras, coude sous l'épaule, corps aligné sur le côté.", "Soulève les hanches pour former une ligne droite des pieds à la tête.", "Garde le bassin haut et les hanches empilées, sans laisser le tronc s'affaisser.", "Pose le genou au sol pour alléger si la position est trop exigeante."], equipment: ["tapis"], commonMistakes: "Laisser les hanches retomber vers le sol et perdre l'alignement latéral."),
            en: ExerciseExplanation(steps: ["Prop yourself on your forearm, elbow under the shoulder, body aligned on its side.", "Lift your hips to form a straight line from feet to head.", "Keep the pelvis high and hips stacked, without letting the torso sag.", "Drop the knee to the floor to make it easier if the position is too demanding."], equipment: ["mat"], commonMistakes: "Letting the hips drop toward the floor and losing the side alignment.")),
        SeedEntry(matchers: ["single-leg squat", "squat une jambe", "pistol"],
            fr: ExerciseExplanation(steps: ["Tiens-toi sur une jambe, l'autre légèrement levée devant ou sur le côté.", "Garde une chaise ou un appui à portée de main pour l'équilibre si besoin.", "Descends en contrôle jusqu'à 60-70° de flexion, genou bien dans l'axe du pied.", "Remonte en poussant dans le talon, tronc gainé et bassin de niveau."], equipment: ["chaise (optionnelle)"], commonMistakes: "Laisser le genou partir vers l'intérieur en perdant le contrôle de l'équilibre."),
            en: ExerciseExplanation(steps: ["Stand on one leg, the other slightly raised in front or to the side.", "Keep a chair or support within reach for balance if needed.", "Lower with control to about 60-70 degrees of knee bend, knee tracking over the foot.", "Drive back up through the heel, core braced and pelvis level."], equipment: ["chair (optional)"], commonMistakes: "Letting the knee drift inward while losing control of your balance.")),
        SeedEntry(matchers: ["test 20 min", "test ftp", "recalibrage", "test 20 min ftp"],
            fr: ExerciseExplanation(steps: ["Échauffe-toi bien, puis lance un effort maximal soutenu sur 20 minutes en terrain plat ou home trainer.", "Pars sur une allure que tu penses tenir 20 min, sans exploser dans les 5 premières minutes.", "Avec capteur : ta puissance moyenne × 0,95 donne ton FTP estimé.", "Sans capteur, repère-toi à l'allure seuil : phrases très courtes, essoufflement net (RPE 7 à 8).", "Termine par un retour au calme en FTP-Z1 pour faire redescendre la fréquence cardiaque."], equipment: ["vélo", "capteur de puissance (optionnel)", "home trainer (optionnel)"], commonMistakes: "Partir trop fort sur les premières minutes et s'effondrer avant la fin du test."),
            en: ExerciseExplanation(steps: ["Warm up well, then ride a sustained maximal effort over 20 minutes on flat ground or a home trainer.", "Open at a pace you believe you can hold for 20 min, without blowing up in the first 5 minutes.", "With a power meter: your average power × 0.95 gives your estimated FTP.", "Without a meter, use threshold feel: very short sentences, clear heavy breathing (RPE 7 to 8).", "Finish with a cool-down in FTP-Z1 to bring your heart rate back down."], equipment: ["bike", "power meter (optional)", "home trainer (optional)"], commonMistakes: "Going out too hard in the first minutes and collapsing before the test is done.")),
        SeedEntry(matchers: ["cyclosportive", "course complete", "course complète", "200 km", "100-150 km"],
            fr: ExerciseExplanation(steps: ["Pars conservateur : sur la première heure, reste sous ton allure cible pour gérer l'emballement du départ.", "Installe-toi ensuite sur ton allure de croisière (FTP-Z2 à Z3) et passe les côtes en Z3 à Z4.", "Garde les efforts très intenses (Z5) pour de rares passages vraiment courts.", "Mange et bois dès la première heure : vise un apport régulier de glucides et de liquide chaque heure.", "Reste lucide sur tes sensations et ajuste l'allure plutôt que de t'accrocher à un objectif chiffré rigide."], equipment: ["vélo", "bidons", "gels ou barres", "ravitaillement solide"], commonMistakes: "Se laisser emporter par le peloton de départ et se mettre dans le rouge avant même la mi-parcours."),
            en: ExerciseExplanation(steps: ["Start conservatively: in the first hour, stay below target pace to manage the rush of the start.", "Then settle into your cruising pace (FTP-Z2 to Z3) and ride climbs in Z3 to Z4.", "Save the very intense efforts (Z5) for rare, genuinely short sections.", "Eat and drink from the first hour: aim for a steady carb and fluid intake every hour.", "Stay tuned to how you feel and adjust pace rather than clinging to a rigid number."], equipment: ["bike", "water bottles", "gels or bars", "solid food"], commonMistakes: "Getting carried away in the start group and going into the red before even halfway.")),
        SeedEntry(matchers: ["repos absolu", "repos complet", "journee entiere", "journée entière"],
            fr: ExerciseExplanation(steps: ["Pose une vraie journée sans vélo ni renforcement : laisse le corps se régénérer.", "Une marche douce de 20 à 30 minutes reste la bienvenue pour bouger un peu.", "Soigne ton hydratation et un repas riche en glucides la veille d'une échéance.", "Considère ce repos comme une partie de l'entraînement, pas comme du temps perdu."], equipment: [], commonMistakes: "Glisser une petite sortie « juste pour bouger » qui entame la fraîcheur du jour de course."),
            en: ExerciseExplanation(steps: ["Take a true day off the bike and off strength work: let the body recover.", "A gentle 20 to 30 minute walk is welcome to move a little.", "Look after your hydration and a carb-rich meal the day before an event.", "Treat this rest as part of training, not as wasted time."], equipment: [], commonMistakes: "Sneaking in a little ride 'just to move' that eats into race-day freshness.")),
        SeedEntry(matchers: ["bird-dog", "bird dog"],
            fr: ExerciseExplanation(steps: ["Place-toi à quatre pattes, mains sous les épaules, genoux sous les hanches, dos plat.", "Tends simultanément un bras et la jambe opposée jusqu'à l'horizontale.", "Garde le tronc stable et le bassin de niveau, sans rotation ni bascule.", "Tiens 2 secondes, reviens en contrôle, puis alterne le nombre de répétitions par côté."], equipment: ["tapis"], commonMistakes: "Laisser le bassin pivoter ou creuser le dos au lieu de garder un tronc gainé et stable."),
            en: ExerciseExplanation(steps: ["Get on all fours, hands under shoulders, knees under hips, back flat.", "Extend one arm and the opposite leg at the same time until they are horizontal.", "Keep the torso stable and the pelvis level, with no rotation or tilt.", "Hold 2 seconds, return with control, then alternate the reps per side."], equipment: ["mat"], commonMistakes: "Letting the pelvis rotate or the back arch instead of keeping a braced, stable torso.")),

        // MARK: running (30)
        SeedEntry(matchers: ["calf raises", "calf raise", "single-leg calf raises excentriques", "calf raises excentriques", "calf raises bipodal", "calf raises surélevés", "calf raises excentriques sur marche", "mollet"],
            fr: ExerciseExplanation(steps: ["Place-toi sur le bord d'une marche, l'avant des pieds en appui et les talons libres dans le vide pour une amplitude complète.", "Monte sur la pointe des pieds en montant les talons aussi haut que possible, puis contracte le mollet en haut.", "Redescends lentement, en 3 à 4 secondes pour la version excentrique, jusqu'à ressentir un étirement contrôlé du mollet.", "Pour la version sur une jambe, monte sur deux pieds et descends sur un seul ; garde la cheville bien dans l'axe."], equipment: ["marche ou step"], commonMistakes: "Précipiter la descente alors que c'est le travail lent et contrôlé qui apporte le bénéfice principal sur le mollet et le tendon."),
            en: ExerciseExplanation(steps: ["Stand on the edge of a step with the balls of your feet supported and your heels free in the air for full range.", "Rise onto the balls of your feet, lifting the heels as high as possible, then squeeze the calf at the top.", "Lower slowly, over 3 to 4 seconds for the eccentric version, until you feel a controlled calf stretch.", "For the single-leg version, rise on two feet and lower on one; keep the ankle tracking in line."], equipment: ["step"], commonMistakes: "Rushing the lowering phase, when the slow, controlled descent delivers the main benefit for the calf and tendon.")),
        SeedEntry(matchers: ["marche récupération", "walking-recovery", "marche récupération post-test", "marche recuperation"],
            fr: ExerciseExplanation(steps: ["Marche à un rythme tranquille et régulier pour laisser le cœur redescendre progressivement après l'effort.", "Respire amplement et relâche les épaules, les bras et la nuque : c'est un retour au calme, pas un exercice.", "Garde un pas fluide sans chercher à aller vite : l'objectif est de faire circuler le sang et de favoriser la récupération.", "Profites-en pour t'hydrater et noter tes sensations de fin de séance."], equipment: [], commonMistakes: "Écourter la marche de récupération et s'arrêter net, ce qui prive le corps d'un retour au calme progressif."),
            en: ExerciseExplanation(steps: ["Walk at a calm, steady rhythm to let your heart rate come down gradually after the effort.", "Breathe fully and relax your shoulders, arms, and neck: this is a cool-down, not an exercise.", "Keep a smooth gait without trying to go fast: the goal is to circulate blood and support recovery.", "Use the time to hydrate and note how the session felt."], equipment: [], commonMistakes: "Cutting the recovery walk short and stopping abruptly, which denies the body a gradual cool-down.")),
        SeedEntry(matchers: ["routine mobilité", "mobilité hanches", "mobilité hanches et chevilles", "routine mobilité complète", "mobilité"],
            fr: ExerciseExplanation(steps: ["Enchaîne des mouvements amples et lents : cercles de hanches, cercles de chevilles, balancés de jambe, rotations thoraciques.", "Tiens les fentes basses 20 à 30 secondes par côté, en respirant calmement, sans chercher l'amplitude maximale d'un coup.", "Reste sans intensité : l'objectif est de préparer les articulations et de relâcher, pas de produire un effort.", "Bouge à un rythme contrôlé et reste à l'écoute de tes sensations ; en cas d'inconfort, réduis l'amplitude."], equipment: ["tapis (optionnel)"], commonMistakes: "Forcer l'amplitude à froid au lieu d'augmenter progressivement et en douceur."),
            en: ExerciseExplanation(steps: ["Flow through wide, slow movements: hip circles, ankle circles, leg swings, thoracic rotations.", "Hold low lunges 20 to 30 seconds per side, breathing calmly, without forcing maximum range all at once.", "Stay free of intensity: the goal is to prepare the joints and relax, not to produce effort.", "Move at a controlled pace and stay tuned to how it feels; if anything feels uneasy, reduce the range."], equipment: ["mat (optional)"], commonMistakes: "Forcing range of motion while cold instead of building it up gradually and gently.")),
        SeedEntry(matchers: ["sortie longue", "long run", "long run aérobie", "bloc easy long run", "portion endurance daniels-e", "sortie longue daniels-e", "long run cutback"],
            fr: ExerciseExplanation(steps: ["Démarre franchement détendu, à allure facile : la sortie longue se gère sur la durée, pas sur les premiers kilomètres.", "Maintiens une respiration conversationnelle du début à la fin. Si tu sens l'allure dériver vers le dur, reviens en zone basse.", "Anticipe le ravitaillement : un apport glucidique toutes les 40 à 50 minutes et de l'eau toutes les 15 à 20 minutes, comme en conditions de course.", "Teste à l'entraînement ce que tu prévois le jour J (boisson, gels, tenue) pour habituer ton système digestif et éviter les surprises.", "Garde une cadence stable et une foulée économique : l'enjeu est l'endurance et l'économie de course, pas la vitesse."], equipment: ["chaussures de running", "gourde ou ceinture d'hydratation", "ravitaillement glucidique"], commonMistakes: "Partir trop vite et tester de nouveaux produits le jour de la course plutôt que pendant les sorties longues d'entraînement."),
            en: ExerciseExplanation(steps: ["Start clearly relaxed at an easy pace: the long run is managed over time, not over the first few kilometers.", "Keep conversational breathing from start to finish. If the pace drifts toward hard, return to the low zone.", "Plan your fueling: a carbohydrate intake every 40 to 50 minutes and water every 15 to 20 minutes, just like race conditions.", "Rehearse in training what you plan for race day (drink, gels, kit) to train your gut and avoid surprises.", "Hold a steady cadence and economical stride: the focus here is endurance and running economy, not speed."], equipment: ["running shoes", "water bottle or hydration belt", "carbohydrate fuel"], commonMistakes: "Going out too fast and trying new products on race day instead of during training long runs.")),
        SeedEntry(matchers: ["clamshell", "clamshells", "clamshell mini-band", "clamshells avec résistance", "clamshell avec mini-band"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le côté, genoux pliés à environ 90 degrés et hanches empilées, talons joints.", "Ouvre le genou du dessus comme un coquillage, sans bouger le bassin ni le faire basculer en arrière.", "Cherche la sensation sur l'extérieur de la hanche (les abducteurs), pas dans le bas du dos.", "Reviens lentement et répète le nombre de répétitions prévu ; ajoute un mini-band autour des genoux pour plus de résistance."], equipment: ["tapis (optionnel)", "mini-band (optionnel)"], commonMistakes: "Faire basculer le bassin vers l'arrière pour ouvrir plus grand, ce qui transfère le travail hors des abducteurs de hanche."),
            en: ExerciseExplanation(steps: ["Lie on your side, knees bent to about 90 degrees with hips stacked and heels together.", "Open the top knee like a clamshell, without moving the pelvis or letting it roll backward.", "Seek the feeling on the outside of the hip (the abductors), not in the lower back.", "Return slowly and repeat the planned reps; add a mini-band around the knees for more resistance."], equipment: ["mat (optional)", "mini-band (optional)"], commonMistakes: "Rolling the pelvis backward to open wider, which shifts the work away from the hip abductors.")),
        SeedEntry(matchers: ["single-leg squat", "single leg squat", "single-leg squat assisté", "squat unijambiste"],
            fr: ExerciseExplanation(steps: ["Tiens-toi debout sur une jambe, l'autre tendue devant toi, bras devant pour l'équilibre.", "Descends de façon contrôlée en poussant les hanches en arrière, comme vers une chaise stable derrière toi.", "Garde le genou d'appui aligné avec la pointe du pied, sans le laisser partir vers l'intérieur.", "Remonte en poussant dans le talon ; pour la version assistée, effleure une chaise ou un support pour doser la profondeur."], equipment: ["chaise ou support (pour la version assistée)"], commonMistakes: "Laisser le genou d'appui rentrer vers l'intérieur au lieu de le garder aligné sur le pied."),
            en: ExerciseExplanation(steps: ["Stand on one leg, the other extended in front of you, arms forward for balance.", "Lower in a controlled way by pushing the hips back, as if toward a stable chair behind you.", "Keep the standing knee aligned with the toes, without letting it collapse inward.", "Stand back up by driving through the heel; for the assisted version, lightly touch a chair or support to gauge depth."], equipment: ["chair or support (for the assisted version)"], commonMistakes: "Letting the standing knee cave inward instead of keeping it tracking over the foot.")),
        SeedEntry(matchers: ["pont fessier", "pont fessier unilatéral", "glute bridge", "activation fessiers"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le dos, genoux pliés, pieds à plat largeur de bassin et bras le long du corps.", "Pousse dans les talons pour décoller le bassin jusqu'à une ligne droite des genoux aux épaules.", "Contracte les fessiers 2 secondes en haut sans cambrer le bas du dos, puis redescends lentement.", "Pour la version unilatérale, tends une jambe et garde le bassin parfaitement horizontal, sans le laisser pencher du côté libre."], equipment: ["tapis (optionnel)"], commonMistakes: "Cambrer le bas du dos pour monter plus haut au lieu d'engager d'abord les fessiers."),
            en: ExerciseExplanation(steps: ["Lie on your back, knees bent, feet flat hip-width apart and arms by your sides.", "Drive through your heels to lift the pelvis up to a straight line from knees to shoulders.", "Squeeze the glutes for 2 seconds at the top without arching the lower back, then lower slowly.", "For the single-leg version, extend one leg and keep the pelvis perfectly level, not dropping on the free side."], equipment: ["mat (optional)"], commonMistakes: "Arching the lower back to lift higher instead of engaging the glutes first.")),
        SeedEntry(matchers: ["run facile", "course endurance", "course continue", "footing", "endurance fondamentale", "portion endurance", "easy run", "jogging d'activation", "footing d'activation", "footing léger", "footing très court", "course continue légère", "daniels-e", "long run cutback", "endurance daniels-e"],
            fr: ExerciseExplanation(steps: ["Cale-toi sur une allure conversationnelle : tu peux dire une phrase complète sans t'essouffler. C'est le repère le plus fiable, plus que la montre.", "Vise une zone aérobie basse (autour de Daniels-E, environ 65 à 78 pour cent de la FC max), respiration ample et régulière par le nez si possible.", "Garde une cadence fluide autour de 165 à 175 pas par minute, foulée courte, pieds qui se posent sous le bassin plutôt que devant.", "Reste relâché : épaules basses, bras qui balancent près du corps, regard à l'horizon. L'objectif est de finir avec la sensation d'avoir pu continuer.", "Si l'allure te demande de retenir ton souffle, ralentis. Ces sorties construisent la base aérobie : la lenteur est volontaire."], equipment: ["chaussures de running"], commonMistakes: "Courir trop vite ses sorties faciles, ce qui transforme l'easy run en effort moyen et fatigue sans bénéfice aérobie supplémentaire."),
            en: ExerciseExplanation(steps: ["Settle into a conversational pace: you can speak a full sentence without gasping. That cue is more reliable than your watch.", "Aim for a low aerobic zone (around Daniels-E, roughly 65 to 78 percent of max HR), with full, steady breathing through the nose when possible.", "Keep a smooth cadence around 165 to 175 steps per minute, short stride, feet landing under your hips rather than ahead.", "Stay relaxed: low shoulders, arms swinging close to the body, eyes on the horizon. The goal is to finish feeling you could have kept going.", "If the pace makes you hold your breath, ease off. These runs build the aerobic base, so going slow is intentional."], equipment: ["running shoes"], commonMistakes: "Running easy days too fast, turning the easy run into a medium effort that adds fatigue without extra aerobic benefit.")),
        SeedEntry(matchers: ["cooldown", "cooldown easy", "cooldown extended", "footing recovery", "easy run récup active", "récup active", "jogging d'activation", "activation"],
            fr: ExerciseExplanation(steps: ["Termine en trot très facile (RPE 4 à 5) pour consolider le volume aérobie et faciliter l'élimination du lactate accumulé.", "Garde une respiration ample et une allure nettement plus lente que la partie principale de la séance.", "Relâche progressivement la foulée et la cadence : tu cherches à circuler, pas à produire un effort.", "Si les jambes sont lourdes après un bloc intense, finir en marche-jogging est tout à fait acceptable."], equipment: ["chaussures de running"], commonMistakes: "Sauter le retour au calme ou le courir trop vite, alors qu'il aide la récupération entre les séances."),
            en: ExerciseExplanation(steps: ["Finish at a very easy jog (RPE 4 to 5) to consolidate aerobic volume and help clear accumulated lactate.", "Keep full breathing and a pace clearly slower than the main part of the session.", "Gradually relax your stride and cadence: you are circulating, not producing effort.", "If your legs feel heavy after an intense block, finishing with a walk-jog is perfectly fine."], equipment: ["running shoes"], commonMistakes: "Skipping the cool-down or running it too fast, when it helps recovery between sessions.")),
        SeedEntry(matchers: ["bulgarian split squat", "split squat"],
            fr: ExerciseExplanation(steps: ["Place le pied arrière surélevé sur un banc ou une chaise stable, le pied avant suffisamment loin devant.", "Descends en pliant le genou avant, le buste légèrement penché, jusqu'à ce que la cuisse avant soit proche de l'horizontale.", "Garde le genou avant aligné avec le pied et le poids réparti sur tout l'appui avant.", "Remonte en poussant dans le talon avant ; ajoute des haltères seulement quand la technique est propre."], equipment: ["banc ou chaise", "haltères (optionnel)"], commonMistakes: "Mettre trop de poids sur la jambe arrière au lieu de charger l'appui avant qui travaille réellement."),
            en: ExerciseExplanation(steps: ["Place the rear foot elevated on a bench or stable chair, the front foot set far enough ahead.", "Lower by bending the front knee, torso leaning slightly forward, until the front thigh is near horizontal.", "Keep the front knee aligned with the foot and the weight spread over the whole front foot.", "Stand up by driving through the front heel; add dumbbells only once the technique is clean."], equipment: ["bench or chair", "dumbbells (optional)"], commonMistakes: "Putting too much weight on the rear leg instead of loading the front foot that actually does the work.")),
        SeedEntry(matchers: ["squat poids du corps", "squats poids du corps", "squat"],
            fr: ExerciseExplanation(steps: ["Tiens-toi debout, pieds écartés largeur d'épaules, pointes légèrement ouvertes.", "Descends en poussant les hanches en arrière et en pliant les genoux, buste droit et talons ancrés au sol.", "Vise des cuisses proches de l'horizontale, en gardant les genoux alignés avec les pieds.", "Remonte en poussant dans les talons et en serrant les fessiers en haut, sans cambrer le bas du dos."], equipment: [], commonMistakes: "Laisser les talons décoller ou les genoux rentrer vers l'intérieur au lieu de garder l'appui stable."),
            en: ExerciseExplanation(steps: ["Stand with feet shoulder-width apart, toes slightly turned out.", "Lower by pushing the hips back and bending the knees, torso tall and heels anchored to the floor.", "Aim for thighs near horizontal, keeping the knees aligned with the feet.", "Stand back up by driving through the heels and squeezing the glutes at the top, without arching the lower back."], equipment: [], commonMistakes: "Letting the heels lift or the knees cave inward instead of keeping a stable base.")),
        SeedEntry(matchers: ["@hmp", "allure semi", "portion allure semi", "segments allure semi", "strides allure semi"],
            fr: ExerciseExplanation(steps: ["Vise ton allure semi cible (@HMP) : un effort soutenu mais maîtrisé, fluide, que tu peux tenir longtemps.", "Ces segments simulent les conditions de course : cherche la sensation de mécanique bien huilée plutôt que la performance brute.", "Sur les portions courtes (strides ou segments), entre dans l'allure progressivement et relâche pendant les récupérations en trot facile.", "Garde une cadence haute et une foulée légère : c'est un rappel neuromusculaire de l'allure cible.", "Si l'allure te paraît dure dès le début, vérifie ton départ : sur le semi, partir conservateur les premiers kilomètres protège la fin de course."], equipment: ["chaussures de running"], commonMistakes: "Aborder ces segments comme un test de vitesse au lieu d'une répétition fluide de l'allure de course cible."),
            en: ExerciseExplanation(steps: ["Aim for your target half-marathon pace (@HMP): a sustained but controlled, smooth effort you can hold for a long time.", "These segments simulate race conditions: seek the well-oiled mechanics feel rather than raw performance.", "On short portions (strides or segments), ease into the pace progressively and relax during the easy-jog recoveries.", "Keep a high cadence and a light stride: this is a neuromuscular reminder of the target pace.", "If the pace feels hard from the start, check your opening: in the half, starting conservatively in the early kilometers protects the finish."], equipment: ["running shoes"], commonMistakes: "Treating these segments as a speed test instead of a smooth rehearsal of the target race pace.")),
        SeedEntry(matchers: ["semi-marathon 21", "marathon 42", "10 km à allure cible", "test 5k", "5k chronométré", "10k à allure", "@5k-pace", "@10k-pace"],
            fr: ExerciseExplanation(steps: ["Pars conservateur sur les premiers kilomètres, légèrement plus lent que ton allure cible : tu protèges la fin de course.", "Progresse ensuite vers ton allure cible et cherche une seconde moitié au moins aussi rapide que la première (negative split).", "Sur un test chronométré, vise un effort régulier d'environ 8 sur 10, du début à la fin, plutôt qu'un sprint mal réparti.", "Suis ton plan de ravitaillement répété à l'entraînement : apport glucidique et eau aux moments prévus, rien de nouveau le jour J.", "Garde une mécanique économique et une respiration rythmée ; sur la fin, donne ce qu'il reste si l'énergie le permet."], equipment: ["chaussures de running testées", "ravitaillement glucidique", "tenue testée à l'entraînement"], commonMistakes: "Partir trop vite sous l'effet de l'adrénaline, ce qui épuise les réserves de glycogène avant la fin de course."),
            en: ExerciseExplanation(steps: ["Start conservatively in the first kilometers, slightly slower than your target pace: you protect the finish.", "Then progress toward your target pace and aim for a second half at least as fast as the first (negative split).", "On a timed test, aim for a steady effort around 8 out of 10, start to finish, rather than a poorly distributed sprint.", "Follow the fueling plan you rehearsed in training: carbohydrate and water at the planned moments, nothing new on race day.", "Keep economical mechanics and rhythmic breathing; near the end, give what is left if energy allows."], equipment: ["tested running shoes", "carbohydrate fuel", "kit tested in training"], commonMistakes: "Starting too fast on adrenaline, which burns through glycogen stores before the finish.")),
        SeedEntry(matchers: ["checklist matérielle", "checklist", "pré-course"],
            fr: ExerciseExplanation(steps: ["Prépare tes chaussures de course déjà rodées (testées à l'entraînement, pas neuves le jour J).", "Sors la tenue que tu as déjà portée à l'entraînement, sans nouveauté, pour éviter toute gêne en course.", "Vérifie ton plan de ravitaillement : gels et boisson prévus, répartis aux kilomètres clés comme tu l'as répété.", "Anticipe la logistique : réveil, échauffement, transport et arrivée au départ avec une marge confortable."], equipment: ["chaussures rodées", "tenue testée", "gels et boisson"], commonMistakes: "Étrenner du matériel neuf le jour de la course au lieu de tout valider à l'entraînement."),
            en: ExerciseExplanation(steps: ["Lay out your broken-in race shoes (tested in training, not brand new on race day).", "Set aside the kit you have already worn in training, with nothing new, to avoid any discomfort during the race.", "Check your fueling plan: planned gels and drink, placed at the key kilometers just as you rehearsed.", "Plan the logistics: wake-up, warm-up, transport, and arriving at the start with a comfortable margin."], equipment: ["broken-in shoes", "tested kit", "gels and drink"], commonMistakes: "Breaking in new gear on race day instead of validating everything in training.")),
        SeedEntry(matchers: ["marathon pace", "daniels-m", "bloc marathon pace"],
            fr: ExerciseExplanation(steps: ["Cale-toi sur ton allure marathon cible (Daniels-M) : la sensation est comfortably hard, pas conversationnelle mais soutenable longtemps.", "Cherche une allure exacte et STABLE plutôt que des variations : c'est l'entraînement le plus spécifique de ton plan.", "Profite du bloc pour répéter ta stratégie de course : ravitaillement à allure réelle, gestion de la cadence et de la respiration.", "Si tu sens l'allure devenir dure trop tôt, reviens légèrement en zone basse : il s'agit d'ancrer la mémoire de l'allure, pas de t'épuiser.", "Reste mécaniquement économique : foulée régulière, buste droit, bras détendus, regard loin devant."], equipment: ["chaussures de running", "ravitaillement glucidique"], commonMistakes: "Courir le bloc plus vite que l'allure marathon réelle, ce qui fausse le ressenti que tu cherches à automatiser pour le jour J."),
            en: ExerciseExplanation(steps: ["Settle into your target marathon pace (Daniels-M): the feel is comfortably hard, not conversational but holdable for a long time.", "Look for an exact, STEADY pace rather than swings: this is the most race-specific session in your plan.", "Use the block to rehearse your race strategy: fueling at real pace, managing cadence and breathing.", "If the pace starts to feel hard too early, ease slightly into the low zone: the aim is to lock in pace memory, not to exhaust yourself.", "Stay mechanically economical: steady stride, tall torso, relaxed arms, eyes far ahead."], equipment: ["running shoes", "carbohydrate fuel"], commonMistakes: "Running the block faster than true marathon pace, which distorts the feel you are trying to automate for race day.")),
        SeedEntry(matchers: ["hip thrust", "hip thrust chargé"],
            fr: ExerciseExplanation(steps: ["Cale le haut du dos contre un banc ou un canapé bas, pieds à plat au sol, charge posée sur le pli des hanches.", "Pousse dans les talons pour monter le bassin jusqu'à une ligne droite des genoux aux épaules.", "Contracte fort les fessiers 2 secondes en haut, en gardant les tibias verticaux et le menton légèrement rentré.", "Redescends lentement et maîtrise toute l'amplitude : la puissance des hanches se travaille sur le contrôle, pas sur l'élan."], equipment: ["banc ou support bas", "charge (haltère, sac chargé ou élastique)"], commonMistakes: "Pousser avec le bas du dos plutôt qu'avec les fessiers et hyperextendre la colonne en haut du mouvement."),
            en: ExerciseExplanation(steps: ["Rest your upper back against a bench or a low couch, feet flat on the floor, load set across your hip crease.", "Drive through your heels to lift the pelvis up to a straight line from knees to shoulders.", "Squeeze the glutes hard for 2 seconds at the top, keeping the shins vertical and the chin slightly tucked.", "Lower slowly and control the full range: hip power is built through control, not momentum."], equipment: ["bench or low support", "load (dumbbell, loaded bag or band)"], commonMistakes: "Pushing with the lower back rather than the glutes and hyperextending the spine at the top.")),
        SeedEntry(matchers: ["fentes dynamiques", "fentes statiques", "fente", "lunge"],
            fr: ExerciseExplanation(steps: ["Pars debout, fais un grand pas vers l'avant et descends en pliant les deux genoux vers 90 degrés.", "Garde le buste droit, le genou avant aligné avec le pied et sans le laisser dépasser largement la pointe.", "Pour la version statique, remonte sur place ; pour la version dynamique, reviens au centre puis alterne les jambes.", "Pousse dans le talon avant pour remonter et garde le bassin stable tout au long du mouvement."], equipment: [], commonMistakes: "Laisser le genou avant dépasser largement la pointe du pied ou pencher le buste vers l'avant."),
            en: ExerciseExplanation(steps: ["Start standing, take a big step forward, and lower by bending both knees toward 90 degrees.", "Keep the torso tall, the front knee aligned with the foot and not traveling far past the toes.", "For the static version, push back up in place; for the dynamic version, return to center then alternate legs.", "Drive through the front heel to rise and keep the pelvis stable throughout the movement."], equipment: [], commonMistakes: "Letting the front knee travel far past the toes or leaning the torso too far forward.")),
        SeedEntry(matchers: ["planche ventrale", "planche", "plank"],
            fr: ExerciseExplanation(steps: ["Place les coudes juste sous les épaules et les avant-bras au sol, pieds écartés largeur de bassin.", "Aligne le corps en une ligne droite des talons à la tête : engage les fessiers et rentre légèrement le bassin pour éviter de creuser le bas du dos.", "Garde la nuque dans le prolongement du dos, regard vers le sol, et respire de façon régulière pendant le maintien.", "Tiens la durée prévue en restant gréé : dès que le bassin s'affaisse, fais une courte pause plutôt que de perdre l'alignement."], equipment: ["tapis (optionnel)"], commonMistakes: "Laisser le bassin s'affaisser ou remonter les fesses, ce qui réduit l'engagement du centre du corps."),
            en: ExerciseExplanation(steps: ["Place your elbows directly under your shoulders, forearms on the floor, feet hip-width apart.", "Align the body in a straight line from heels to head: engage the glutes and slightly tuck the pelvis to avoid sagging the lower back.", "Keep your neck in line with your spine, eyes toward the floor, and breathe steadily throughout the hold.", "Hold for the planned time while staying braced: as soon as the hips drop, take a short break rather than losing alignment."], equipment: ["mat (optional)"], commonMistakes: "Letting the hips sag or piking the hips up, which reduces core engagement.")),
        SeedEntry(matchers: ["side plank", "planche latérale", "gainage latéral"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le côté, coude sous l'épaule, avant-bras au sol et jambes empilées.", "Décolle le bassin pour former une ligne droite de la tête aux pieds, en engageant les obliques et le moyen fessier.", "Garde le bassin stable et face à l'avant, sans rotation : la hanche du dessus reste empilée sur celle du dessous.", "Tiens la durée prévue de chaque côté en respirant calmement, puis repose-toi avant de changer de côté."], equipment: ["tapis (optionnel)"], commonMistakes: "Laisser le bassin descendre vers le sol au lieu de maintenir la ligne corporelle gainée."),
            en: ExerciseExplanation(steps: ["Lie on your side, elbow under your shoulder, forearm on the floor and legs stacked.", "Lift the hips to form a straight line from head to feet, engaging the obliques and glute medius.", "Keep the pelvis stable and facing forward, without rotation: the top hip stays stacked over the bottom one.", "Hold the planned time on each side, breathing calmly, then rest before switching sides."], equipment: ["mat (optional)"], commonMistakes: "Letting the hips drop toward the floor instead of keeping a braced body line.")),
        SeedEntry(matchers: ["nordic curl", "nordic hamstring"],
            fr: ExerciseExplanation(steps: ["Place-toi à genoux sur un tapis, chevilles bien calées (sous un meuble bas ou tenues par un partenaire).", "Garde les hanches en extension et le corps gainé sur une ligne des genoux à la tête, sans casser à la hanche.", "Descends lentement vers l'avant en résistant au maximum avec les ischio-jambiers, en 3 à 4 secondes.", "Aide-toi des mains pour amortir la fin et remonter : c'est la phase de descente freinée qui apporte le bénéfice."], equipment: ["tapis", "point de calage des chevilles"], commonMistakes: "Casser à la hanche pour faciliter la descente au lieu de garder le corps gainé et de freiner avec les ischio-jambiers."),
            en: ExerciseExplanation(steps: ["Kneel on a mat with your ankles firmly anchored (under a low piece of furniture or held by a partner).", "Keep the hips extended and the body braced in a line from knees to head, without bending at the hip.", "Lower slowly forward, resisting as much as possible with the hamstrings, over 3 to 4 seconds.", "Use your hands to cushion the end and push back up: the controlled lowering phase delivers the benefit."], equipment: ["mat", "ankle anchor point"], commonMistakes: "Bending at the hip to make the descent easier instead of keeping the body braced and resisting with the hamstrings.")),
        SeedEntry(matchers: ["wall sit", "wall sit partiel", "chaise"],
            fr: ExerciseExplanation(steps: ["Adosse-toi à un mur, fais glisser le dos vers le bas jusqu'à former un angle d'environ 60 à 70 degrés au genou.", "Garde les pieds écartés largeur de bassin, les genoux au-dessus des chevilles et le dos plat contre le mur.", "Engage les quadriceps et respire calmement pendant tout le maintien.", "Tiens la durée prévue ; remonte légèrement si l'effort devient trop intense plutôt que de perdre la position."], equipment: ["mur"], commonMistakes: "Laisser les genoux dépasser largement la pointe des pieds au lieu de garder les tibias proches de la verticale."),
            en: ExerciseExplanation(steps: ["Lean against a wall and slide your back down until you reach about a 60 to 70 degree angle at the knees.", "Keep the feet hip-width apart, knees over the ankles, and the back flat against the wall.", "Engage the quadriceps and breathe calmly throughout the hold.", "Hold the planned time; rise slightly if the effort gets too intense rather than losing the position."], equipment: ["wall"], commonMistakes: "Letting the knees travel far past the toes instead of keeping the shins close to vertical.")),
        SeedEntry(matchers: ["deadlift", "deadlift léger", "soulevé de terre"],
            fr: ExerciseExplanation(steps: ["Place-toi debout, pieds largeur de hanches, la charge proche des tibias et les scapulas légèrement serrées.", "Pousse les hanches en arrière en gardant le dos plat pour descendre la charge le long des jambes.", "Descends jusqu'à sentir l'étirement de la chaîne postérieure (ischio-jambiers), sans arrondir le bas du dos.", "Remonte en poussant dans les talons et en avançant les hanches ; la technique prime sur la charge, surtout au début."], equipment: ["haltères ou barre légère"], commonMistakes: "Arrondir le bas du dos en descendant au lieu de garder le dos plat et de charnière sur les hanches."),
            en: ExerciseExplanation(steps: ["Stand with feet hip-width apart, the load close to your shins and your shoulder blades slightly set.", "Push the hips back while keeping a flat back to lower the load along your legs.", "Lower until you feel the posterior chain stretch (hamstrings), without rounding the lower back.", "Stand up by driving through the heels and bringing the hips forward; technique comes before load, especially at first."], equipment: ["dumbbells or light bar"], commonMistakes: "Rounding the lower back on the way down instead of keeping a flat back and hinging at the hips.")),
        SeedEntry(matchers: ["tempo continu", "tempo daniels-t", "bloc tempo", "blocs seuil", "segment tempo", "daniels-t", "tempo"],
            fr: ExerciseExplanation(steps: ["Vise l'allure seuil (Daniels-T), une sensation comfortably hard : soutenu mais tenable sur une heure de course environ.", "Repère de la parole : tu peux placer quelques mots courts, pas une conversation. La respiration devient rythmée mais contrôlée.", "Sur les 5 premières minutes, cale ton allure sans te précipiter. L'objectif est une vitesse STABLE, pas une accélération finale.", "En continu, garde le même effort du début à la fin ; en blocs (cruise intervals), enchaîne avec une récup courte en trot facile.", "Tiens-toi à l'allure prévue : un écart inférieur à 5 secondes au kilomètre entre le premier et le dernier bloc est le signe d'un seuil bien géré."], equipment: ["chaussures de running"], commonMistakes: "Démarrer trop vite et finir en sprint, ce qui fait dériver l'allure et rate l'objectif de stimulation du seuil lactique."),
            en: ExerciseExplanation(steps: ["Aim for threshold pace (Daniels-T), a comfortably hard feel: sustained but holdable for about an hour of racing.", "Talk test: you can place a few short words, not a conversation. Breathing becomes rhythmic but controlled.", "Over the first 5 minutes, settle your pace without rushing. The goal is a STEADY speed, not a final surge.", "Continuous tempo: hold the same effort start to finish; in cruise intervals, link reps with a short easy-jog recovery.", "Stick to the planned pace: less than 5 seconds per kilometer drift between the first and last block signals a well-managed threshold."], equipment: ["running shoes"], commonMistakes: "Starting too fast and finishing in a sprint, which makes the pace drift and misses the lactate-threshold stimulus.")),
        SeedEntry(matchers: ["strides", "stride", "daniels-r", "strides 6", "stride final", "strides courts"],
            fr: ExerciseExplanation(steps: ["Après ta sortie facile, lance de courtes accélérations progressives : monte la vitesse sur 20 à 100 mètres, sans jamais sprinter à fond.", "Décompose chaque stride : démarrage doux, montée en vitesse au milieu, puis relâchement fluide en fin de segment.", "Vise une mécanique propre : cadence haute, pieds qui se posent sous le bassin, buste droit, bras relâchés.", "Récupère complètement entre chaque (marche ou trot lent) : l'objectif est la qualité du geste, pas l'essoufflement.", "Plafonne l'effort vers 90 pour cent de ta vitesse : les strides réveillent les fibres rapides sans créer de fatigue."], equipment: ["chaussures de running", "terrain plat"], commonMistakes: "Transformer les strides en sprints maximaux, ce qui crée de la tension inutile au lieu d'un simple rappel neuromusculaire."),
            en: ExerciseExplanation(steps: ["After your easy run, launch short progressive accelerations: build speed over 20 to 100 meters, never sprinting all out.", "Break each stride into phases: gentle start, speed build in the middle, then a smooth release at the end of the segment.", "Aim for clean mechanics: high cadence, feet landing under the hips, tall torso, relaxed arms.", "Recover fully between reps (walk or slow jog): the goal is movement quality, not breathlessness.", "Cap the effort around 90 percent of your speed: strides wake up the fast fibers without creating fatigue."], equipment: ["running shoes", "flat ground"], commonMistakes: "Turning strides into all-out sprints, which creates needless tension instead of a simple neuromuscular reminder.")),
        SeedEntry(matchers: ["intervalles", "daniels-i", "interval 400", "interval 600", "interval 800", "interval 1000", "interval 1200", "1000m", "1200m", "800m", "600m", "400m", "vo2"],
            fr: ExerciseExplanation(steps: ["Cours les répétitions à allure I (Daniels-I), proche de ton allure 3K à 5K : exigeant mais régulier, jamais en sprint maximal.", "Chaque répétition doit ressembler à la précédente : vise une allure homogène plutôt que d'exploser la première et subir les dernières.", "Respecte la récupération en trot lent (pas d'arrêt complet) : elle permet de répéter la qualité d'effort sur tout le bloc.", "Concentre-toi sur une mécanique propre : cadence haute, pieds sous le bassin, buste droit, bras actifs.", "Si l'allure dérive nettement sur les dernières répétitions, mieux vaut arrêter une rép plus tôt que sacrifier la qualité."], equipment: ["chaussures de running", "piste ou parcours plat mesuré"], commonMistakes: "Partir trop fort dès la première répétition, ce qui dégrade les suivantes et réduit le temps réellement passé à intensité VO2max."),
            en: ExerciseExplanation(steps: ["Run the reps at I pace (Daniels-I), close to your 3K to 5K pace: demanding but even, never an all-out sprint.", "Each rep should look like the one before: aim for a consistent pace rather than blowing up the first and crawling the last.", "Respect the slow-jog recovery (no full stop): it lets you repeat the quality effort across the whole set.", "Focus on clean mechanics: high cadence, feet under the hips, tall torso, active arms.", "If pace clearly drifts on the last reps, it is better to stop one rep early than to sacrifice quality."], equipment: ["running shoes", "track or measured flat route"], commonMistakes: "Going out too hard on the first rep, which degrades the rest and cuts the time actually spent at VO2max intensity.")),
        SeedEntry(matchers: ["run · walk", "run walk", "bloc run · walk", "bloc laddered", "blocs courts", "bloc long", "bloc course", "bloc course 4", "bloc course 5"],
            fr: ExerciseExplanation(steps: ["Alterne course très lente et marche rapide selon la structure prévue : la course doit rester en allure conversationnelle complète.", "Pendant la portion course, vérifie le test de la parole : si le souffle coupe au bout de 30 secondes, ralentis encore.", "Sur la marche, reste active et dynamique plutôt que traînante : tu entretiens la fréquence cardiaque et le rythme.", "Reviens au jogging dès que tu te sens prêt sur les blocs plus longs ; couper pour marcher un instant est normal et ne casse pas la séance.", "Progresse semaine après semaine en allongeant les blocs de course : la régularité prime sur la vitesse à ce stade."], equipment: ["chaussures de running"], commonMistakes: "Courir la portion 'course' trop vite, ce qui rend la transition vers la marche brutale et empêche de tenir le volume prévu."),
            en: ExerciseExplanation(steps: ["Alternate very slow running and brisk walking per the planned structure: the running portion stays at a full conversational pace.", "During the run portion, check the talk test: if your breath cuts out after 30 seconds, slow down further.", "On the walk, stay active and brisk rather than dawdling: you keep heart rate and rhythm up.", "Return to jogging as soon as you feel ready on longer blocks; pausing to walk a moment is normal and does not break the session.", "Progress week by week by lengthening the run blocks: consistency matters more than speed at this stage."], equipment: ["running shoes"], commonMistakes: "Running the 'run' portion too fast, which makes the switch to walking abrupt and prevents holding the planned volume.")),
        SeedEntry(matchers: ["box jumps", "box jump", "pliométrie", "saut"],
            fr: ExerciseExplanation(steps: ["Choisis une boîte ou une marche stable et basse (30 à 40 cm), bien fixée pour ne pas glisser.", "Fléchis légèrement les genoux et les hanches, balance les bras, puis saute en atterrissant en douceur sur la boîte.", "Réceptionne genoux fléchis et dos droit, comme un amorti silencieux, pour absorber l'impact.", "Redescends en marchant plutôt qu'en sautant vers le bas : c'est de la pliométrie modérée pour l'économie de course, pas une recherche de hauteur."], equipment: ["boîte ou marche stable basse"], commonMistakes: "Sauter sur une boîte trop haute ou redescendre en sautant, ce qui augmente inutilement l'impact à la réception."),
            en: ExerciseExplanation(steps: ["Choose a stable, low box or step (30 to 40 cm), firmly placed so it cannot slip.", "Slightly bend the knees and hips, swing the arms, then jump up landing softly on the box.", "Land with bent knees and a straight back, like a silent cushion, to absorb the impact.", "Step down rather than jumping down: this is moderate plyometrics for running economy, not a quest for height."], equipment: ["stable low box or step"], commonMistakes: "Jumping onto a box that is too high or jumping back down, which needlessly increases landing impact.")),
        SeedEntry(matchers: ["bird-dog", "bird dog", "birddog"],
            fr: ExerciseExplanation(steps: ["Place-toi à quatre pattes, mains sous les épaules et genoux sous les hanches, dos neutre.", "Tends en même temps le bras et la jambe opposés jusqu'à l'horizontale, en gardant le bassin stable face au sol.", "Cherche l'anti-rotation : le bassin ne bascule pas, le tronc reste gainé et la nuque dans l'axe du dos.", "Tiens 2 secondes en haut, reviens lentement, puis alterne les côtés sur le nombre de répétitions prévu."], equipment: ["tapis (optionnel)"], commonMistakes: "Laisser le bassin pivoter ou cambrer le bas du dos au lieu de garder le tronc stable et gainé."),
            en: ExerciseExplanation(steps: ["Set up on all fours, hands under the shoulders and knees under the hips, neutral back.", "Extend the opposite arm and leg together to horizontal, keeping the pelvis stable and facing the floor.", "Seek anti-rotation: the pelvis does not tilt, the trunk stays braced, and the neck stays in line with the spine.", "Hold 2 seconds at the top, return slowly, then alternate sides for the planned number of reps."], equipment: ["mat (optional)"], commonMistakes: "Letting the pelvis rotate or arching the lower back instead of keeping the trunk stable and braced.")),
        SeedEntry(matchers: ["step-ups", "step ups", "step up"],
            fr: ExerciseExplanation(steps: ["Place un pied à plat sur une marche ou une chaise stable, le genou aligné avec le pied.", "Monte en poussant fort dans la jambe d'appui sur la marche, sans t'aider d'un élan de la jambe arrière.", "Redresse-toi complètement en haut, puis redescends de façon contrôlée plutôt qu'en te laissant tomber.", "Alterne ou enchaîne selon le plan, en gardant le buste droit et le bassin stable."], equipment: ["marche ou chaise stable"], commonMistakes: "S'aider d'un élan de la jambe au sol pour monter au lieu de faire travailler la jambe posée sur la marche."),
            en: ExerciseExplanation(steps: ["Place one foot flat on a step or stable chair, knee aligned with the foot.", "Step up by driving hard through the supporting leg on the step, without pushing off with the trailing leg.", "Stand fully tall at the top, then lower in a controlled way rather than dropping down.", "Alternate or repeat per the plan, keeping the torso tall and the pelvis stable."], equipment: ["step or stable chair"], commonMistakes: "Using a push-off from the ground leg to step up instead of working the leg placed on the step.")),
        SeedEntry(matchers: ["fartlek"],
            fr: ExerciseExplanation(steps: ["Alterne des blocs 'on' à allure 5K (RPE 8, soutenu) et des blocs 'off' en footing facile, selon la structure prévue.", "Sur les blocs 'on', cherche un effort régulier et maîtrisé plutôt qu'un démarrage explosif : l'idée est de pouvoir répéter chaque bloc.", "Profite des blocs 'off' pour relâcher complètement la respiration et baisser la cadence : c'est une vraie récupération active.", "Le fartlek se pilote au ressenti : si les derniers blocs 'on' se dégradent nettement, raccourcis-les plutôt que de t'épuiser.", "Garde une foulée fluide même sur les portions rapides : cadence haute, appuis dynamiques sous le bassin."], equipment: ["chaussures de running"], commonMistakes: "Transformer les blocs 'on' en sprints maximaux, ce qui rend les répétitions impossibles à tenir et casse la régularité de la séance."),
            en: ExerciseExplanation(steps: ["Alternate 'on' blocks at 5K pace (RPE 8, sustained) and 'off' blocks at easy jog, following the planned structure.", "On the 'on' blocks, look for a steady, controlled effort rather than an explosive start: you should be able to repeat each block.", "Use the 'off' blocks to fully release your breathing and drop your cadence: this is genuine active recovery.", "Fartlek is driven by feel: if the last 'on' blocks clearly degrade, shorten them rather than exhausting yourself.", "Keep a smooth stride even on the fast portions: high cadence, dynamic footstrike under the hips."], equipment: ["running shoes"], commonMistakes: "Turning the 'on' blocks into all-out sprints, which makes the reps impossible to hold and breaks the session's consistency.")),

        // MARK: swimming (30)
        SeedEntry(matchers: ["external rotation", "rotation externe", "manchette rotateurs", "external rotation band", "external rotation avec band", "external rotation avec resistance"],
            fr: ExerciseExplanation(steps: ["Fixe un élastique léger à hauteur de coude (poignée de porte ou rampe).", "Garde le coude collé au flanc, fléchi à 90 degrés, l'avant-bras à l'horizontale.", "Tourne lentement la main vers l'extérieur (rotation externe), puis reviens tout aussi lentement.", "Tempo lent (environ 3 secondes aller, 3 secondes retour), charge légère, qualité avant volume.", "Tu renforces les muscles arrière de l'épaule qui équilibrent les pectoraux dominants du nageur."], equipment: ["élastique"], commonMistakes: "Décoller le coude du corps et utiliser l'élan, ce qui sort la cible du mouvement."),
            en: ExerciseExplanation(steps: ["Anchor a light band at elbow height (a door handle or rail).", "Keep the elbow tucked against your side, bent to 90 degrees, forearm horizontal.", "Slowly rotate the hand outward (external rotation), then return just as slowly.", "Slow tempo (about 3 seconds out, 3 seconds back), light load, quality over volume.", "You strengthen the rear shoulder muscles that balance the swimmer's dominant chest muscles."], equipment: ["resistance band"], commonMistakes: "Letting the elbow drift away from the body and using momentum, which takes the target off the move.")),
        SeedEntry(matchers: ["time trial", "test 400", "test css", "recalibrage css", "chronométré", "chronometre", "400 m crawl chronométré", "200 m crawl chronométré", "test sp1", "test sp2", "1000 m continu crawl chronométré"],
            fr: ExerciseExplanation(steps: ["Échauffe-toi bien avant : un test maximal demande un corps déjà chaud et délié.", "Pars sur une allure soutenue et régulière, surtout pas de départ trop rapide qui ruine la fin.", "Note ton temps exact : c'est lui qui calcule ton CSS et calibre toutes les allures du plan.", "Entre le 400 m et le 200 m, prends 5 minutes de récup active (nage très lente plus flotter).", "La formule CSS = (400 - 200) divisé par (temps 400 m moins temps 200 m), exprimée en allure au 100 m."], equipment: [], commonMistakes: "Partir trop vite sur le test et s'effondrer en fin de distance, ce qui fausse le CSS."),
            en: ExerciseExplanation(steps: ["Warm up well beforehand: a maximal test needs a body that is already warm and loose.", "Go out at a sustained, steady pace, never a too-fast start that wrecks the finish.", "Note your exact time: it computes your CSS and calibrates every pace in the plan.", "Between the 400 m and the 200 m, take 5 minutes of active recovery (very slow swim plus float).", "The CSS formula = (400 - 200) divided by (400 m time minus 200 m time), expressed as pace per 100 m."], equipment: [], commonMistakes: "Going out too fast on the test and collapsing late, which skews the CSS.")),
        SeedEntry(matchers: ["en1", "récupération", "recuperation", "récup active", "recup active", "retour au calme", "décharge", "decharge", "consolidation crawl", "nage récup", "nage recup", "bloc en1", "récupération + bilatérale"],
            fr: ExerciseExplanation(steps: ["Allure conversationnelle facile (EN1, RPE 3-4) : tu peux parler en nageant, le souffle reste ample.", "Vise CSS + 8 à 12 secondes au 100 m. Si tu n'as pas de repère CSS, pars plus lent que tu ne le penses.", "Respiration bilatérale tous les 3 cycles pour équilibrer le corps gauche-droite et travailler l'aisance.", "Compte tes coups de bras tous les 200 m : si ça dérive de plus de 2 coups au 50 m, relâche l'allure.", "Cherche la glisse longue entre chaque cycle, corps haut et détendu plutôt que la vitesse."], equipment: [], commonMistakes: "Partir trop vite : sur l'endurance, l'allure régulière prime sur le chrono."),
            en: ExerciseExplanation(steps: ["Easy conversational pace (EN1, RPE 3-4): you can talk while swimming and your breathing stays relaxed.", "Aim for CSS + 8 to 12 seconds per 100 m. With no CSS reference, start slower than you think.", "Breathe bilaterally every 3 strokes to balance left and right and build ease in the water.", "Count your strokes every 200 m: if it drifts more than 2 strokes per 50 m, ease the pace.", "Look for a long glide between cycles, body high and relaxed rather than fast."], equipment: [], commonMistakes: "Starting too fast: on endurance work, steady pace matters more than the clock.")),
        SeedEntry(matchers: ["en2", "progressifs", "bloc en2", "comfortably hard", "crawl avec evf appliqué", "crawl avec evf applique", "dos crawlé continu", "dos crawle continu"],
            fr: ExerciseExplanation(steps: ["Allure « comfortably hard » (EN2, RPE 5-6) : tu peux dire 4-5 mots mais pas une phrase entière.", "Vise CSS plus ou moins 0 à 3 secondes au 100 m. Chronomètre chaque répétition.", "Cherche la constance : garde un écart inférieur à 3-4 secondes entre tes répétitions.", "Garde un coude haut sous l'eau et une entrée de main dans l'axe de l'épaule.", "Si la dernière répétition dégrade fortement (plus de 5 secondes), c'est le signe d'arrêter là."], equipment: [], commonMistakes: "Démarrer trop fort sur les premières reps et ne plus tenir l'allure sur les dernières."),
            en: ExerciseExplanation(steps: ["Comfortably hard pace (EN2, RPE 5-6): you can say 4-5 words but not a full sentence.", "Aim for CSS plus or minus 0 to 3 seconds per 100 m. Time each repetition.", "Look for consistency: keep the gap under 3-4 seconds between repetitions.", "Keep a high elbow underwater and a hand entry in line with the shoulder.", "If the last rep drops off sharply (more than 5 seconds), that is the cue to stop there."], equipment: [], commonMistakes: "Going out too hard on the first reps and fading on the last ones.")),
        SeedEntry(matchers: ["fingertip drag", "fingertip", "drag du bout des doigts", "doigts à la surface", "doigts a la surface"],
            fr: ExerciseExplanation(steps: ["Pendant le retour aérien du bras, fais glisser le bout des doigts à la surface de l'eau.", "Va de la hanche jusqu'à l'entrée de la main, comme si tu grattais doucement la surface.", "Ce geste force naturellement un coude haut en récupération et un retour relâché.", "Garde l'épaule détendue : c'est la rotation du tronc qui amène le bras, pas la force du bras.", "Enchaîne ensuite quelques longueurs de crawl normal pour ancrer la sensation de coude haut."], equipment: [], commonMistakes: "Lever le bras tendu très haut au lieu de garder le coude haut et l'avant-bras relâché."),
            en: ExerciseExplanation(steps: ["During the arm's recovery over the water, drag your fingertips along the surface.", "Go from the hip to the hand entry, as if lightly scratching the surface.", "This naturally forces a high elbow in recovery and a relaxed return.", "Keep the shoulder relaxed: trunk rotation brings the arm forward, not arm strength.", "Then swim a few normal crawl lengths to lock in the high-elbow feel."], equipment: [], commonMistakes: "Lifting a straight arm very high instead of keeping a high elbow and relaxed forearm.")),
        SeedEntry(matchers: ["scapula retraction", "scapula", "rétraction omoplates", "retraction omoplates", "scapula retraction band"],
            fr: ExerciseExplanation(steps: ["Fixe un élastique horizontal à hauteur de poitrine (porte ou rampe) et saisis-le des deux mains.", "Coudes près du corps, tire en ramenant les omoplates l'une vers l'autre, comme pour serrer un crayon entre elles.", "Garde les épaules basses, sans les hausser vers les oreilles.", "Tempo lent (environ 2 secondes de contraction, 2 secondes de retour).", "Tu renforces les rhomboïdes, antagonistes des pectoraux souvent dominants chez le nageur."], equipment: ["élastique"], commonMistakes: "Hausser les épaules vers les oreilles au lieu de serrer les omoplates vers le centre du dos."),
            en: ExerciseExplanation(steps: ["Anchor a horizontal band at chest height (door or rail) and grab it with both hands.", "Elbows close to the body, pull by drawing the shoulder blades together, as if squeezing a pencil between them.", "Keep the shoulders low, without shrugging toward the ears.", "Slow tempo (about 2 seconds of contraction, 2 seconds back).", "You strengthen the rhomboids, antagonists to the chest muscles often dominant in swimmers."], equipment: ["resistance band"], commonMistakes: "Shrugging the shoulders toward the ears instead of squeezing the shoulder blades toward the mid-back.")),
        SeedEntry(matchers: ["catch high-elbow", "high-elbow", "high elbow", "evf", "early vertical forearm", "drills catch", "catch +", "sculling evf"],
            fr: ExerciseExplanation(steps: ["Juste après l'entrée de la main, fléchis le coude pour amener l'avant-bras à la verticale tôt.", "Garde le coude plus haut que la main : tu « attrapes » l'eau et la pousses vers l'arrière, pas vers le bas.", "Enchaîne souvent sculling avant-bras vertical et fist swim pour bien sentir l'appui.", "Pense à un grand seau d'eau que tu pousses derrière toi avec tout l'avant-bras.", "Reste détendu : c'est un geste de précision et de timing, pas de force brute."], equipment: [], commonMistakes: "Laisser tomber le coude et tirer avec le bras tendu, ce qui perd l'appui sur l'avant-bras."),
            en: ExerciseExplanation(steps: ["Just after the hand entry, bend the elbow to bring the forearm vertical early.", "Keep the elbow higher than the hand: you grab the water and push it backward, not downward.", "Often alternate vertical-forearm sculling and fist swim to feel the catch.", "Picture a big bucket of water you push behind you with the whole forearm.", "Stay relaxed: this is precision and timing, not brute force."], equipment: [], commonMistakes: "Dropping the elbow and pulling with a straight arm, which loses the forearm catch.")),
        SeedEntry(matchers: ["paddles", "paddle", "drills catch + paddles", "drills + paddles", "drills paddles"],
            fr: ExerciseExplanation(steps: ["Commence avec des paddles de petite taille (small ou medium) pour ne pas surcharger l'épaule.", "Concentre-toi sur la sensation de prise d'eau amplifiée et un catch précoce et propre.", "Garde un coude haut sous l'eau : les paddles amplifient le bon comme le mauvais geste.", "Alterne longueurs avec et sans paddles pour comparer les sensations de propulsion.", "En cas de gêne à l'épaule, retire les paddles sans hésiter et continue à mains nues."], equipment: ["paddles"], commonMistakes: "Choisir des paddles trop grandes trop tôt, ce qui dégrade le geste sous la charge."),
            en: ExerciseExplanation(steps: ["Start with small paddles (small or medium) to avoid overloading the shoulder.", "Focus on the amplified feel of the water and an early, clean catch.", "Keep a high elbow underwater: paddles amplify good and bad technique alike.", "Alternate lengths with and without paddles to compare the feel of propulsion.", "If the shoulder feels uncomfortable, take the paddles off without hesitation and continue bare-handed."], equipment: ["paddles"], commonMistakes: "Choosing paddles that are too big too soon, which degrades technique under load.")),
        SeedEntry(matchers: ["expiration sous l'eau", "expiration active", "respiration latérale", "respiration laterale", "breath control", "breath", "side kick with breath", "respiration statique", "expiration", "bilatérale", "bilaterale", "compteur de cycles", "compteur cycles", "crawl bilatérale"],
            fr: ExerciseExplanation(steps: ["Visage dans l'eau, expire longuement et progressivement par le nez et la bouche, sans bloquer le souffle.", "Tourne la tête juste assez pour qu'une oreille reste dans l'eau et l'autre à l'air, sans la lever.", "Inspire vite et reviens le visage dans l'eau : l'expiration doit être continue entre deux inspirations.", "En bilatéral, inspire tous les 3 cycles pour alterner les côtés et équilibrer le corps.", "Si la bilatérale essouffle, reviens côté favori sur quelques longueurs puis réessaie, sans frustration."], equipment: [], commonMistakes: "Retenir son air sous l'eau puis devoir tout expirer et inspirer dans le même temps : expire en continu."),
            en: ExerciseExplanation(steps: ["Face in the water, exhale long and steadily through nose and mouth, without holding your breath.", "Turn your head just enough so one ear stays in the water and the other in the air, without lifting it.", "Inhale quickly and return your face to the water: the exhale should be continuous between breaths.", "When breathing bilaterally, inhale every 3 strokes to alternate sides and balance the body.", "If bilateral breathing leaves you short of breath, go back to your favourite side for a few lengths, then try again, no frustration."], equipment: [], commonMistakes: "Holding air underwater then having to exhale and inhale at once: exhale continuously instead.")),
        SeedEntry(matchers: ["serratus", "serratus push-up", "push-up plus", "serratus push-up plus"],
            fr: ExerciseExplanation(steps: ["Place-toi en planche haute, mains sous les épaules, corps gainé et aligné.", "Sans plier les coudes, pousse le sol pour « arrondir » légèrement le haut du dos (les omoplates s'écartent).", "Reviens lentement en laissant les omoplates se rapprocher, toujours sans bouger les coudes.", "Le mouvement est petit et précis : tu cibles le serratus antérieur, clé de la phase de catch.", "Garde le bassin stable et le ventre engagé tout au long."], equipment: ["tapis"], commonMistakes: "Plier les coudes comme pour une pompe au lieu d'isoler le mouvement des omoplates."),
            en: ExerciseExplanation(steps: ["Set up in a high plank, hands under the shoulders, body braced and aligned.", "Without bending the elbows, push the floor to slightly round the upper back (shoulder blades spread).", "Return slowly, letting the shoulder blades come together, still without moving the elbows.", "The movement is small and precise: you target the serratus anterior, key to the catch phase.", "Keep the pelvis stable and the abs engaged throughout."], equipment: ["mat"], commonMistakes: "Bending the elbows like a push-up instead of isolating the shoulder-blade movement.")),
        SeedEntry(matchers: ["rec", "nage récupération", "nage recuperation", "récupération active", "recuperation active", "dos lent", "récup active drills", "recup active drills", "crawl simplifié", "crawl simplifie", "crawl libre", "plaisir et autonomie", "100 m crawl easy", "crawl easy"],
            fr: ExerciseExplanation(steps: ["Allure très facile, sans aucune intensité : l'objectif est de relâcher, pas de progresser.", "Choisis le dos crawlé lent ou un crawl souple, respiration ample et libre.", "Laisse le corps flotter et la fréquence cardiaque redescendre tranquillement.", "Si c'est libre, nage simplement pour le plaisir : aucun chrono, aucune contrainte de longueur.", "Termine en relâchant épaules et nuque, sans chercher la performance."], equipment: [], commonMistakes: "Transformer la récup en vraie nage : si tu pousses, ce n'est plus de la récupération."),
            en: ExerciseExplanation(steps: ["Very easy pace with zero intensity: the goal is to release, not to progress.", "Choose slow backstroke or a relaxed crawl, with open and free breathing.", "Let your body float and your heart rate come down quietly.", "If it is free swim, just swim for enjoyment: no clock, no length target.", "Finish by relaxing shoulders and neck, without chasing performance."], equipment: [], commonMistakes: "Turning recovery into a real swim: if you push, it is no longer recovery.")),
        SeedEntry(matchers: ["dos crawlé", "dos crawle", "dos crawlé technique", "dos crawle technique"],
            fr: ExerciseExplanation(steps: ["Garde le bassin haut, ne t'assieds pas dans l'eau : le corps reste long et horizontal.", "Oreilles immergées, regard vers le plafond, tête fixe et alignée.", "Initie la rotation par la hanche, l'épaule suit : tu roules d'un côté à l'autre à chaque bras.", "Garde un battement de jambes régulier et souple pour soutenir le bassin.", "Allure EN1-EN2 souple : c'est aussi un travail d'équilibre musculaire après beaucoup de crawl."], equipment: [], commonMistakes: "S'asseoir dans l'eau avec le bassin bas, ce qui casse l'alignement et freine."),
            en: ExerciseExplanation(steps: ["Keep hips high, do not sit in the water: the body stays long and horizontal.", "Ears submerged, eyes to the ceiling, head still and aligned.", "Initiate rotation from the hip, the shoulder follows: you roll side to side with each arm.", "Keep a steady, loose leg kick to support the hips.", "Easy EN1-EN2 pace: it is also muscular balance work after lots of freestyle."], equipment: [], commonMistakes: "Sitting in the water with low hips, which breaks alignment and creates drag.")),
        SeedEntry(matchers: ["long swim", "long swim continu", "long swim crawl", "nage continue", "1000 m continu", "long swim pic", "pic absolu", "long swim taper", "long swim raccourci", "long swim 400", "long swim 500", "long swim 600", "long swim 700", "long swim 800", "long swim 1000", "long swim 1300"],
            fr: ExerciseExplanation(steps: ["Pars TRÈS lent, 10-15 secondes au 100 m plus lent que ton allure de test 400 m : la régularité fait le long swim.", "Si tu sens le souffle s'accélérer avant la mi-distance, c'est que tu es parti trop vite : relâche.", "Respiration bilatérale tous les 3 cycles en EN1, passe côté favori sur les portions EN2 plus rapides.", "Compte tes coups de bras toutes les 200-500 m et vise une stabilité (plus ou moins 1 coup).", "Sur les très longues distances, bois quelques gorgées au bord toutes les 800 m si besoin."], equipment: [], commonMistakes: "Attaquer trop fort les 200 premiers mètres, le grand classique qui fait exploser le long swim."),
            en: ExerciseExplanation(steps: ["Start VERY slow, 10-15 seconds per 100 m slower than your 400 m test pace: consistency makes the long swim.", "If your breathing speeds up before halfway, you went out too fast: ease off.", "Breathe bilaterally every 3 strokes in EN1, switch to your favourite side on faster EN2 portions.", "Count your strokes every 200-500 m and aim for stability (plus or minus 1 stroke).", "On very long distances, take a few sips at the wall every 800 m if needed."], equipment: [], commonMistakes: "Attacking the first 200 m too hard, the classic mistake that blows up the long swim.")),
        SeedEntry(matchers: ["6-3-6", "636", "side kick", "battements latéraux", "battements lateraux", "body roll", "rotation tronc", "rotation hanche"],
            fr: ExerciseExplanation(steps: ["Mets-toi sur le côté, bras inférieur tendu devant en flèche, bras supérieur le long du corps.", "Fais 6 battements de jambes en position latérale, oreille basse dans l'eau, hanches hautes.", "Enchaîne 3 coups de bras de crawl pour basculer sur l'autre côté, puis 6 battements à nouveau.", "Initie la rotation par les hanches : l'épaule suit le mouvement du bassin, pas l'inverse.", "Alterne côté favori et côté faible : le côté faible révèle les compensations à corriger."], equipment: [], commonMistakes: "Tourner depuis les épaules en gardant le bassin à plat, alors que la rotation part des hanches."),
            en: ExerciseExplanation(steps: ["Lie on your side, lower arm extended forward streamlined, upper arm along the body.", "Take 6 kicks on your side, lower ear in the water, hips high.", "Add 3 crawl strokes to switch to the other side, then 6 kicks again.", "Initiate rotation from the hips: the shoulder follows the pelvis, not the other way around.", "Alternate favourite and weaker side: the weaker side reveals the compensations to fix."], equipment: [], commonMistakes: "Rotating from the shoulders with a flat pelvis, when rotation comes from the hips.")),
        SeedEntry(matchers: ["pull-buoy", "pull buoy", "pullbuoy", "bras seuls", "isolation traction", "pull-buoy isolation"],
            fr: ExerciseExplanation(steps: ["Cale le pull-buoy entre les cuisses pour faire flotter les jambes et les garder immobiles.", "Concentre-toi à 100 % sur la traction des bras : entrée, catch coude haut, poussée longue jusqu'à la cuisse.", "Sens la prise d'eau sur l'avant-bras dès le début du mouvement sous l'eau.", "Garde le corps gainé et aligné pour éviter de cambrer le bas du dos.", "Allure souple : le but est la qualité de traction, pas un volume rapide."], equipment: ["pull-buoy"], commonMistakes: "Cambrer le dos quand les jambes flottent, au lieu de garder le tronc gainé et horizontal."),
            en: ExerciseExplanation(steps: ["Place the pull-buoy between your thighs to float the legs and keep them still.", "Focus 100% on the arm pull: entry, high-elbow catch, long push to the thigh.", "Feel the catch on the forearm from the very start of the underwater phase.", "Keep the body braced and aligned to avoid arching the lower back.", "Easy pace: the goal is pull quality, not fast volume."], equipment: ["pull-buoy"], commonMistakes: "Arching the back when the legs float, instead of keeping the trunk braced and horizontal.")),
        SeedEntry(matchers: ["streamline", "push-off", "superman glide", "superman", "poussée mur", "poussee mur", "glisse 5 m", "glisse 8 m", "flottaison ventrale"],
            fr: ExerciseExplanation(steps: ["Mains jointes au-dessus de la tête, bras collés aux oreilles, corps tendu comme une flèche.", "Pousse du mur et tiens la position le plus longtemps possible avant le premier mouvement.", "Souffle lentement par le nez sous l'eau pendant la glisse pour rester relâché.", "Garde les hanches hautes et la tête neutre dans l'alignement du corps.", "Cherche à allonger la distance de glisse au fil des semaines : c'est un repère d'efficacité."], equipment: [], commonMistakes: "Lever la tête pendant la glisse, ce qui fait plonger les hanches et freine le corps."),
            en: ExerciseExplanation(steps: ["Hands joined above the head, arms squeezing the ears, body tight like an arrow.", "Push off the wall and hold the position as long as possible before the first movement.", "Exhale slowly through the nose underwater during the glide to stay relaxed.", "Keep hips high and head neutral, in line with the body.", "Aim to lengthen the glide distance over the weeks: it is an efficiency marker."], equipment: [], commonMistakes: "Lifting the head during the glide, which drops the hips and slows the body.")),
        SeedEntry(matchers: ["battement de jambes", "jambes seules", "kickboard", "planche", "battement de pieds", "drill jambes", "25 m jambes"],
            fr: ExerciseExplanation(steps: ["Initie le battement depuis la hanche, pas depuis le genou : le mouvement part du haut de la jambe.", "Garde une amplitude modérée, genoux à peine fléchis et chevilles souples comme des palmes.", "Avec planche : bras tendus devant, visage dans l'eau, souffle régulier entre deux inspirations.", "Garde les hanches hautes et le corps horizontal pour réduire la traînée.", "Les pieds restent relâchés : des chevilles rigides freinent au lieu de propulser."], equipment: ["planche"], commonMistakes: "Plier fortement les genoux et pédaler, au lieu d'un battement souple parti des hanches."),
            en: ExerciseExplanation(steps: ["Start the kick from the hip, not the knee: the movement comes from the upper leg.", "Keep a moderate amplitude, knees barely bent and ankles loose like fins.", "With a board: arms extended forward, face in the water, steady exhale between breaths.", "Keep hips high and body horizontal to reduce drag.", "Feet stay relaxed: stiff ankles slow you down instead of propelling."], equipment: ["kickboard"], commonMistakes: "Bending the knees hard and cycling, instead of a loose kick driven from the hips.")),
        SeedEntry(matchers: ["brasse", "bloc brasse", "drill brasse", "brasse coordination", "brasse continu"],
            fr: ExerciseExplanation(steps: ["Suis l'ordre du timing : tirer avec les bras, puis respirer, puis ramener les jambes, puis glisser.", "Les bras agissent avant les jambes, jamais l'inverse : c'est la clé de la coordination.", "Garde une longue glisse en flèche après chaque coup de pied, au moins 1 à 1,5 seconde.", "Écarte les genoux modérément, à largeur de hanches, chevilles tournées vers l'extérieur.", "En cas d'inconfort au genou interne, réduis l'amplitude du fouet de jambes et reste souple."], equipment: [], commonMistakes: "Ramener les jambes en même temps que la traction des bras au lieu de les enchaîner après."),
            en: ExerciseExplanation(steps: ["Follow the timing order: pull with the arms, then breathe, then recover the legs, then glide.", "Arms act before the legs, never the reverse: that is the key to coordination.", "Hold a long streamlined glide after each kick, at least 1 to 1.5 seconds.", "Spread the knees moderately, hip width, ankles turned outward.", "If the inner knee feels uncomfortable, reduce the kick amplitude and stay relaxed."], equipment: [], commonMistakes: "Recovering the legs at the same time as the arm pull instead of sequencing them after.")),
        SeedEntry(matchers: ["y-t-w", "ytw", "y t w", "shoulder activation"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le ventre sur un tapis, front posé sur les mains, bras détendus.", "Lève les bras tendus en Y (dans l'axe avant, pouces vers le haut), puis repose lentement.", "Enchaîne la position T (bras en croix, pouces vers le haut), puis la position W (coudes fléchis bas).", "À chaque position, serre légèrement les omoplates vers le bas et l'arrière, sans hausser les épaules.", "Mouvement lent et contrôlé : tu actives les stabilisateurs du haut du dos et de l'épaule."], equipment: ["tapis"], commonMistakes: "Hausser les épaules vers les oreilles au lieu d'engager le bas des omoplates."),
            en: ExerciseExplanation(steps: ["Lie face down on a mat, forehead resting on your hands, arms relaxed.", "Lift straight arms into a Y (forward axis, thumbs up), then lower slowly.", "Move to the T position (arms in a cross, thumbs up), then the W position (elbows bent low).", "In each position, gently draw the shoulder blades down and back, without shrugging.", "Slow, controlled movement: you activate the stabilisers of the upper back and shoulder."], equipment: ["mat"], commonMistakes: "Shrugging the shoulders toward the ears instead of engaging the lower shoulder blades.")),
        SeedEntry(matchers: ["face pull", "face pull élastique", "face pull elastique"],
            fr: ExerciseExplanation(steps: ["Fixe un élastique à hauteur du visage et saisis-le des deux mains.", "Tire vers le visage en écartant les coudes, qui montent au-dessus de la ligne des épaules.", "Finis en serrant les omoplates ensemble, mains qui s'éloignent de part et d'autre de la tête.", "Reviens lentement en contrôlant la tension de l'élastique jusqu'au bout.", "C'est l'antidote à la rotation interne chronique des épaules du nageur."], equipment: ["élastique"], commonMistakes: "Tirer avec les bras en gardant les coudes bas au lieu d'ouvrir et de monter les coudes."),
            en: ExerciseExplanation(steps: ["Anchor a band at face height and grab it with both hands.", "Pull toward your face while spreading the elbows, which rise above shoulder level.", "Finish by squeezing the shoulder blades together, hands moving apart on each side of the head.", "Return slowly, controlling the band tension all the way back.", "This is the antidote to the swimmer's chronic internal shoulder rotation."], equipment: ["resistance band"], commonMistakes: "Pulling with the arms while keeping the elbows low instead of opening and raising the elbows.")),
        SeedEntry(matchers: ["cat-cow", "cat cow", "chat-vache", "chat vache", "mobilité thoracique", "mobilite thoracique"],
            fr: ExerciseExplanation(steps: ["Place-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.", "Inspire en creusant doucement le dos, regard qui monte légèrement (la vache).", "Expire en arrondissant le dos vers le plafond, regard vers le nombril (le chat).", "Mouvement lent et fluide, en suivant le rythme de ta respiration.", "Tu mobilises toute la colonne, utile à la rotation du tronc en nage."], equipment: ["tapis"], commonMistakes: "Forcer en bout d'amplitude au lieu de rester sur un mouvement souple et progressif."),
            en: ExerciseExplanation(steps: ["Get on all fours, hands under the shoulders and knees under the hips.", "Inhale while gently arching the back, eyes rising slightly (the cow).", "Exhale while rounding the back toward the ceiling, eyes to the navel (the cat).", "Slow, flowing movement, following the rhythm of your breath.", "You mobilise the whole spine, useful for trunk rotation while swimming."], equipment: ["mat"], commonMistakes: "Forcing the end range instead of staying on a soft, gradual movement.")),
        SeedEntry(matchers: ["threshold", "css pace", "@css", "css+", "main set threshold", "css —", "css broken", "broken", "css introduction", "css récup", "css recup"],
            fr: ExerciseExplanation(steps: ["Nage exactement à ton allure CSS (seuil critique), calculée depuis ton test 400 m et 200 m.", "Respecte la récup serrée indiquée (10 à 20 secondes) : c'est elle qui crée le stimulus seuil.", "Le critère de réussite est la régularité : un écart inférieur à 3 secondes entre la première et la dernière répétition.", "Découpe mentalement le set : concentre-toi sur la répétition en cours, pas sur celles qui restent.", "Sur les formats longs (200-500 m), reste juste sous le seuil, un peu plus soutenable que le CSS pur."], equipment: [], commonMistakes: "Allonger soi-même la récup quand ça fatigue, ce qui dénature le travail au seuil."),
            en: ExerciseExplanation(steps: ["Swim exactly at your CSS (critical swim speed), calculated from your 400 m and 200 m tests.", "Keep the tight recovery as prescribed (10 to 20 seconds): it is what creates the threshold stimulus.", "The success marker is consistency: a gap under 3 seconds between the first and last rep.", "Break the set up mentally: focus on the current rep, not the ones still to come.", "On longer formats (200-500 m), stay just below threshold, slightly more sustainable than pure CSS."], equipment: [], commonMistakes: "Stretching the recovery yourself when it gets hard, which changes the threshold effect.")),
        SeedEntry(matchers: ["sp1", "sp2", "sp3", "race-pace", "race pace", "bloc lactique", "lactique", "sprint sp3", "vitesse max", "vitesse libre", "activation 4", "strides", "activation strides", "bloc activation"],
            fr: ExerciseExplanation(steps: ["Nage à l'allure de course visée (SP1 = 200 m, SP2 = 100 m, SP3 = vitesse max sur 25 m).", "Sors contrôlé sur les premières longueurs, puis monte régulièrement : pas de départ tout-droit explosif.", "Prends toute la récup indiquée (60 secondes à 3 minutes) : elle restaure l'énergie pour rester rapide.", "Vise un écart minimal entre répétitions (moins d'1 seconde) : c'est le marqueur de tenue.", "Si tu craques nettement sur les dernières, valide d'arrêter une ou deux reps plus tôt."], equipment: [], commonMistakes: "Tout donner dès le premier sprint et ne plus pouvoir tenir l'allure sur les suivants."),
            en: ExerciseExplanation(steps: ["Swim at your target race pace (SP1 = 200 m, SP2 = 100 m, SP3 = top speed over 25 m).", "Start controlled on the first lengths, then build steadily: no explosive flat-out start.", "Take the full recovery shown (60 seconds to 3 minutes): it restores energy to stay fast.", "Aim for a minimal gap between reps (under 1 second): that is the marker of holding pace.", "If you fade clearly on the last ones, it is fine to stop one or two reps early."], equipment: [], commonMistakes: "Going all-out on the first sprint and being unable to hold pace on the next ones.")),
        SeedEntry(matchers: ["sculling", "scull", "figures-8", "figure-8", "essuie-glace", "mains en cuillère", "mains en cuillere"],
            fr: ExerciseExplanation(steps: ["Bras tendus devant, mains à plat, fais des petits mouvements en huit, comme un essuie-glace doux.", "Oriente la paume pour pousser l'eau vers l'arrière et sentir la pression sous l'avant-bras.", "Avance lentement uniquement grâce à la prise d'eau des mains, sans grand mouvement de bras.", "Un pull-buoy entre les cuisses isole le haut du corps et te laisse te concentrer sur la sensation.", "Le but est de développer la sensibilité de l'eau et un catch précoce, pas de la vitesse."], equipment: ["pull-buoy"], commonMistakes: "Faire de grands moulinets de bras au lieu de petits mouvements précis depuis les avant-bras."),
            en: ExerciseExplanation(steps: ["Arms extended forward, hands flat, make small figure-8 movements like a gentle wiper.", "Angle the palm to push water backward and feel the pressure under the forearm.", "Move forward slowly using only the hands' grip on the water, with no large arm motion.", "A pull-buoy between the thighs isolates the upper body so you can focus on the feel.", "The goal is to build feel for the water and an early catch, not speed."], equipment: ["pull-buoy"], commonMistakes: "Making big arm sweeps instead of small precise movements from the forearms.")),
        SeedEntry(matchers: ["single arm", "bras non-dominant", "bras dominant", "un seul bras", "single arm bras"],
            fr: ExerciseExplanation(steps: ["Nage avec un seul bras actif, l'autre tendu devant en flèche tout le long.", "Travaille d'abord le bras non dominant : il révèle les défauts cachés du côté faible.", "Respire du côté du bras inactif pour garder l'équilibre et le corps haut.", "Reproduis sur le bras faible le même catch haut et la même poussée que sur le bras fort.", "Compare les deux côtés : l'objectif est de symétriser le geste gauche-droite."], equipment: [], commonMistakes: "Négliger le bras faible : c'est lui qui a le plus à gagner, ne le saute pas."),
            en: ExerciseExplanation(steps: ["Swim with a single active arm, the other extended forward streamlined the whole time.", "Work the non-dominant arm first: it reveals the hidden flaws of the weak side.", "Breathe on the side of the inactive arm to keep balance and a high body.", "Reproduce the same high catch and push on the weak arm as on the strong one.", "Compare both sides: the goal is to make the left-right stroke symmetrical."], equipment: [], commonMistakes: "Neglecting the weak arm: it has the most to gain, so do not skip it.")),
        SeedEntry(matchers: ["planche ventrale", "planche", "gainage", "plank"],
            fr: ExerciseExplanation(steps: ["Place-toi en appui sur les avant-bras et la pointe des pieds, coudes sous les épaules.", "Garde le corps en ligne droite, des talons à la tête, sans creuser ni arrondir le bas du dos.", "Engage les fessiers et le ventre pour verrouiller le bassin et rester rigide.", "Respire calmement et tiens la durée indiquée sans laisser les hanches s'affaisser.", "Un tronc stable au sol se traduit par une position horizontale stable dans l'eau."], equipment: ["tapis"], commonMistakes: "Laisser les hanches s'affaisser ou se relever en pointe au lieu de garder le corps aligné."),
            en: ExerciseExplanation(steps: ["Set up on your forearms and toes, elbows under the shoulders.", "Keep the body in a straight line from heels to head, without sagging or rounding the lower back.", "Engage glutes and abs to lock the pelvis and stay rigid.", "Breathe calmly and hold the prescribed time without letting the hips drop.", "A stable trunk on land translates to a stable horizontal position in the water."], equipment: ["mat"], commonMistakes: "Letting the hips sag or pike up instead of keeping the body aligned.")),
        SeedEntry(matchers: ["deadlift", "deadlift léger", "deadlift leger", "soulevé de terre", "souleve de terre", "kettlebell"],
            fr: ExerciseExplanation(steps: ["Charge légère (barre ou kettlebell de 12 à 16 kg), pieds largeur de hanches.", "Garde le dos neutre et la poitrine ouverte, regard légèrement devant le sol.", "Pousse les hanches vers l'arrière pour descendre, puis reviens en poussant le sol avec les pieds.", "Engage la chaîne postérieure : fessiers, ischio-jambiers et muscles du dos travaillent ensemble.", "Mouvement contrôlé, la charge légère équilibre le pattern bras-épaules dominant du nageur."], equipment: ["barre ou kettlebell légère"], commonMistakes: "Arrondir le bas du dos en descendant au lieu de garder le dos neutre et de pousser les hanches en arrière."),
            en: ExerciseExplanation(steps: ["Light load (a bar or a 12 to 16 kg kettlebell), feet hip-width apart.", "Keep a neutral back and an open chest, eyes slightly ahead on the floor.", "Push the hips backward to lower, then return by pushing the floor away with your feet.", "Engage the posterior chain: glutes, hamstrings and back muscles work together.", "Controlled movement; the light load balances the swimmer's dominant arm-shoulder pattern."], equipment: ["light bar or kettlebell"], commonMistakes: "Rounding the lower back on the way down instead of keeping it neutral and pushing the hips back.")),
        SeedEntry(matchers: ["fist swim", "poings fermés", "poings fermes", "poing fermé", "poing ferme"],
            fr: ExerciseExplanation(steps: ["Nage le crawl normalement mais avec les poings fermés tout le long.", "Sans la surface de la main, tu apprends à chercher l'appui avec tout l'avant-bras.", "Garde un coude haut sous l'eau : l'avant-bras devient ta vraie surface propulsive (early vertical forearm).", "Quand tu rouvres les mains au 25 m suivant, savoure la prise d'eau soudain beaucoup plus pleine.", "Alterne longueurs poings fermés et mains ouvertes pour bien sentir le contraste."], equipment: [], commonMistakes: "Tirer avec un coude bas qui glisse dans l'eau au lieu d'engager l'avant-bras vertical."),
            en: ExerciseExplanation(steps: ["Swim normal crawl but with your fists closed the whole time.", "Without the hand's surface, you learn to find purchase with the whole forearm.", "Keep a high elbow underwater: the forearm becomes your real propulsive surface (early vertical forearm).", "When you reopen your hands on the next 25 m, enjoy the suddenly much fuller catch.", "Alternate closed-fist and open-hand lengths to really feel the contrast."], equipment: [], commonMistakes: "Pulling with a low elbow that slips through the water instead of engaging a vertical forearm.")),
        SeedEntry(matchers: ["en3", "vo2max", "vo2 max", "bloc en3", "reps longues", "court — 4", "court — 3"],
            fr: ExerciseExplanation(steps: ["Allure soutenue (EN3, RPE 7-8) : tu peux dire 2-3 mots isolés à la fin de chaque répétition, pas plus.", "Vise CSS - 5 à -10 secondes au 100 m. C'est plus rapide que ton allure de test 400 m.", "Respecte la récup courte indiquée (30 à 50 secondes) pour garder le stimulus VO2max.", "Vise un écart inférieur à 2-4 secondes entre la première et la dernière répétition.", "Si tu dérives nettement sur l'avant-dernière, valide d'arrêter une répétition plus tôt : c'est de la régulation, pas un échec."], equipment: [], commonMistakes: "Confondre EN3 avec un sprint : c'est rapide mais régulier, pas maximal."),
            en: ExerciseExplanation(steps: ["Sustained pace (EN3, RPE 7-8): you can say 2-3 isolated words at the end of each rep, no more.", "Aim for CSS - 5 to -10 seconds per 100 m. This is faster than your 400 m test pace.", "Keep the short recovery as prescribed (30 to 50 seconds) to preserve the VO2max stimulus.", "Target a gap under 2-4 seconds between the first and last repetition.", "If you drift clearly on the second-to-last rep, it is fine to stop one rep early: that is regulation, not failure."], equipment: [], commonMistakes: "Treating EN3 as a sprint: it is fast but steady, not maximal.")),
        SeedEntry(matchers: ["catch-up", "catch up", "catchup"],
            fr: ExerciseExplanation(steps: ["Garde un bras tendu devant et n'initie la traction de l'autre que lorsqu'il vient toucher la main avant.", "Cherche la glisse maximale entre chaque cycle : le but est de rallonger le temps passé en flèche.", "Synchronise l'entrée de la main avec la rotation des hanches pour un mouvement fluide.", "Garde un rythme lent et contrôlé : ce drill travaille le timing, pas la vitesse.", "Reste détendu, le drill corrige la nage « moulin à vent » où les deux bras tirent en même temps."], equipment: [], commonMistakes: "Aller trop vite et perdre la phase de glisse, ce qui annule l'intérêt du drill."),
            en: ExerciseExplanation(steps: ["Keep one arm extended forward and only start the other pull when it touches the front hand.", "Look for maximum glide between each cycle: the goal is to lengthen time spent streamlined.", "Sync the hand entry with hip rotation for a smooth, flowing movement.", "Keep a slow, controlled rhythm: this drill trains timing, not speed.", "Stay relaxed; the drill fixes the windmill stroke where both arms pull at once."], equipment: [], commonMistakes: "Going too fast and losing the glide phase, which defeats the drill's purpose.")),

        // MARK: triathlon (36)
        SeedEntry(matchers: ["long run", "course continue daniels-e long", "long run daniels", "finition daniels-m"],
            fr: ExerciseExplanation(steps: ["Pars sur une allure facile et tenable, puis maintiens-la sur toute la durée prévue.", "Privilégie une surface souple quand c'est possible pour un appui plus confortable.", "Bois régulièrement et apporte un peu de glucides sur les sorties longues pour habituer le ventre.", "Si une finition à allure course (Daniels-M) est prévue, relance les dernières minutes sans casser la cadence.", "Garde une cadence autour de 175-185 pas par minute et un effort régulier jusqu'au bout."], equipment: ["chaussures de running", "flasque ou ceinture d'hydratation", "ravitaillement glucidique"], commonMistakes: "Négliger l'hydratation et le ravitaillement sur les longues durées."),
            en: ExerciseExplanation(steps: ["Start at an easy, sustainable pace, then hold it across the whole planned duration.", "Favor a softer surface when possible for a more comfortable footing.", "Drink regularly and take in some carbohydrate on long runs to train your gut.", "If a race-pace finish (Daniels-M) is planned, lift the last minutes without breaking cadence.", "Keep cadence around 175-185 steps per minute and an even effort to the end."], equipment: ["running shoes", "handheld or hydration belt", "carbohydrate fuel"], commonMistakes: "Neglecting hydration and fueling on long-duration efforts.")),
        SeedEntry(matchers: ["ftp-z1", "recovery ftp-z1", "spinning z1", "pédalage très lent post-test"],
            fr: ExerciseExplanation(steps: ["Pédale très souple, RPE 2-3, pour évacuer en douceur après un effort intense.", "Laisse la cadence libre et concentre-toi sur une respiration calme.", "Reste léger sur la pédale, aucune intention de pousser.", "Bois pour réamorcer la récupération."], equipment: ["vélo", "bidon"], commonMistakes: "Transformer la récupération en séance : reste vraiment très léger."),
            en: ExerciseExplanation(steps: ["Spin very lightly, RPE 2-3, to flush out gently after an intense effort.", "Let the cadence stay free and focus on calm breathing.", "Stay light on the pedals with no intent to push.", "Drink to kickstart recovery."], equipment: ["bike", "bottle"], commonMistakes: "Turning recovery into a workout: keep it genuinely very light.")),
        SeedEntry(matchers: ["position tt", "tt-bike", "cruise ftp-z2 tt", "validation confort lombaire", "tt cruise"],
            fr: ExerciseExplanation(steps: ["Installe-toi sur les prolongateurs en gardant le dos plat et la nuque relâchée.", "Vérifie sur la durée que la position reste tenable au niveau bas du dos et cervicales.", "Garde une cadence ronde de 88 à 95 tours par minute et un regard porté loin sur la route.", "Si une tension s'installe, redresse-toi quelques instants puis reviens en aéro progressivement.", "L'objectif est d'habituer le corps à produire de la puissance en position basse, durablement."], equipment: ["vélo de contre-la-montre ou prolongateurs", "casque"], commonMistakes: "Crisper la nuque et les épaules en position aéro : relâche le haut du corps et garde le dos long."),
            en: ExerciseExplanation(steps: ["Settle onto the aerobars keeping your back flat and neck relaxed.", "Check over time that the position stays sustainable for your low back and neck.", "Keep a round cadence of 88 to 95 rpm with your gaze far down the road.", "If tension builds, sit up for a moment then ease back into the aero position.", "The goal is to teach the body to produce power in a low position, sustainably."], equipment: ["time-trial bike or clip-on aerobars", "helmet"], commonMistakes: "Tensing the neck and shoulders in the aero position: relax the upper body and keep the back long.")),
        SeedEntry(matchers: ["circuit", "clam + calf + y-t-w + plank", "planche + bird-dog"],
            fr: ExerciseExplanation(steps: ["Enchaîne les exercices du circuit avec une récupération courte entre chaque.", "Sur chaque mouvement, garde la technique propre plutôt que de viser le nombre.", "Gaine le ventre et stabilise le bassin sur les exercices de core.", "Respire régulièrement, sans bloquer, tout au long du circuit.", "Adapte le volume si la qualité du geste se dégrade en fin de série."], equipment: ["tapis", "mini-bande élastique"], commonMistakes: "Privilégier le nombre à la qualité : mieux vaut moins de répétitions bien exécutées."),
            en: ExerciseExplanation(steps: ["Move through the circuit exercises with a short recovery between each.", "On every movement, keep clean technique rather than chasing the count.", "Brace the core and stabilize the pelvis on the core exercises.", "Breathe steadily, without holding your breath, throughout the circuit.", "Adjust the volume if movement quality drops late in the set."], equipment: ["mat", "mini-band"], commonMistakes: "Prioritizing reps over quality: fewer well-executed reps are better.")),
        SeedEntry(matchers: ["6-3-6", "drill équilibre", "battements", "battements planche", "battement", "drill 6-3-6", "respiration bilatérale", "étoile sur le dos"],
            fr: ExerciseExplanation(steps: ["Sur les battements avec planche, génère le mouvement depuis la hanche, jambes longues, pas depuis le genou.", "Garde le corps allongé et la position hydrodynamique, tête dans l'alignement.", "Sur le 6-3-6, enchaîne 6 battements sur un côté, 3 coups de bras de transition, puis 6 battements de l'autre côté pour travailler la rotation.", "Sur la respiration bilatérale, inspire toutes les 3 brassées en alternant les côtés pour gagner en symétrie.", "Respire calmement et cherche l'équilibre et la décontraction plutôt que la vitesse."], equipment: ["lunettes", "bonnet", "planche"], commonMistakes: "Battre depuis le genou : le mouvement part de la hanche, jambes quasi tendues."),
            en: ExerciseExplanation(steps: ["On kick with a board, drive from the hip with long legs, not from the knee.", "Keep the body extended and hydrodynamic, head in line with the spine.", "On 6-3-6, link 6 kicks on one side, 3 transition strokes, then 6 kicks on the other side to train rotation.", "On bilateral breathing, inhale every 3 strokes alternating sides to build symmetry.", "Breathe calmly and chase balance and relaxation rather than speed."], equipment: ["goggles", "swim cap", "kickboard"], commonMistakes: "Kicking from the knee: the motion comes from the hip with nearly straight legs.")),
        SeedEntry(matchers: ["mobilité", "routine mobilité", "cat-cow", "foam roller", "mobilité globale", "mobilité 3 disciplines", "mobilité hanches"],
            fr: ExerciseExplanation(steps: ["Enchaîne des cercles lents de hanches, chevilles et épaules, une dizaine dans chaque sens.", "Ajoute quelques cat-cow lents et des fentes basses tenues une trentaine de secondes par côté.", "Termine par un squat profond tenu pour relâcher hanches et chevilles.", "Reste sans intensité, l'objectif est le relâchement et la mobilité, pas l'effort.", "Respire amplement et bouge dans une amplitude confortable."], equipment: ["tapis", "foam roller"], commonMistakes: "Forcer l'amplitude : reste dans une zone confortable et bouge lentement."),
            en: ExerciseExplanation(steps: ["Flow through slow circles of hips, ankles and shoulders, about ten in each direction.", "Add a few slow cat-cows and low lunges held for about thirty seconds per side.", "Finish with a deep squat hold to release hips and ankles.", "Stay easy: the goal is relaxation and mobility, not effort.", "Breathe fully and move within a comfortable range."], equipment: ["mat", "foam roller"], commonMistakes: "Forcing the range: stay in a comfortable zone and move slowly.")),
        SeedEntry(matchers: ["y-t-w", "shoulder activation", "external rotation band", "ytw"],
            fr: ExerciseExplanation(steps: ["Allonge-toi à plat ventre, front au sol, ou debout penché si tu préfères.", "Forme la lettre Y bras tendus en diagonale haute, soulève légèrement les bras du sol en serrant les omoplates.", "Enchaîne avec le T bras à l'horizontale, puis le W coudes pliés ramenés vers le bas.", "Garde un soulevé léger et contrôlé, l'effort vient du haut du dos et des épaules.", "Si tu as une bande élastique, ajoute des rotations externes coude au corps pour compléter."], equipment: ["tapis", "bande élastique (optionnel)"], commonMistakes: "Forcer avec le cou : le mouvement vient des omoplates et du haut du dos, nuque relâchée."),
            en: ExerciseExplanation(steps: ["Lie face down, forehead on the floor, or stand hinged forward if you prefer.", "Form the letter Y with arms extended high in a diagonal, lifting them slightly off the floor by squeezing the shoulder blades.", "Move into the T with arms horizontal, then the W with elbows bent drawn downward.", "Keep the lift light and controlled, the effort comes from the upper back and shoulders.", "If you have a band, add external rotations with the elbow at your side to round it out."], equipment: ["mat", "resistance band (optional)"], commonMistakes: "Straining with the neck: the movement comes from the shoulder blades and upper back, neck relaxed.")),
        SeedEntry(matchers: ["transition", "t1", "t2", "transitions t1", "transition t2", "simulation transition", "transition rapide"],
            fr: ExerciseExplanation(steps: ["Pose ton matériel toujours dans le même ordre pour automatiser les gestes : casque, lunettes, chaussures, race-belt.", "Sur T1, sors de l'eau, enfile casque et chaussures vélo, et démarre en posant le vélo en main, casque clipsé avant d'enfourcher.", "Sur T2, pose le vélo, retire le casque, change de chaussures (lacets élastiques) et boucle ton race-belt.", "Cherche un enchaînement fluide plutôt qu'un chrono : la régularité du geste fait gagner du temps.", "Répète plusieurs fois à sec pour mémoriser l'ordre et fluidifier l'enchaînement."], equipment: ["casque", "chaussures vélo", "chaussures de running", "race-belt", "lunettes"], commonMistakes: "Changer l'ordre des gestes à chaque essai : fige une routine et répète-la jusqu'à l'automatisme."),
            en: ExerciseExplanation(steps: ["Lay out your gear in the same order every time to automate the steps: helmet, goggles, shoes, race belt.", "On T1, exit the water, put on helmet and bike shoes, and start by running with the bike in hand, helmet clipped before mounting.", "On T2, rack the bike, remove the helmet, switch to run shoes (elastic laces) and clip your race belt.", "Aim for a smooth sequence rather than a stopwatch: consistent movement is what saves time.", "Rehearse several times on dry land to lock in the order and smooth the flow."], equipment: ["helmet", "bike shoes", "running shoes", "race belt", "goggles"], commonMistakes: "Changing the order of steps every attempt: lock in a routine and repeat it until it is automatic.")),
        SeedEntry(matchers: ["bulgarian split squat", "single-leg squat", "single leg squat", "split squat"],
            fr: ExerciseExplanation(steps: ["Sur le split squat, place le pied arrière sur un banc, le poids sur la jambe avant.", "Descends en contrôle en gardant le buste droit et le genou avant aligné sur le pied.", "Sur le single-leg squat, descends t'asseoir doucement sur une boîte sur une jambe puis remonte.", "Garde une charge légère ou le poids du corps, l'objectif est l'équilibre et la force unilatérale.", "Si l'équilibre manque, garde deux doigts en appui léger sur un support."], equipment: ["banc ou boîte", "haltères (optionnel)"], commonMistakes: "Laisser le genou avant partir vers l'intérieur : garde-le aligné au-dessus du pied."),
            en: ExerciseExplanation(steps: ["On the split squat, place the rear foot on a bench, weight on the front leg.", "Lower under control keeping the torso tall and the front knee tracking over the foot.", "On the single-leg squat, lower gently to sit on a box on one leg then stand back up.", "Keep a light load or bodyweight, the aim is balance and single-leg strength.", "If balance is lacking, keep two fingers lightly on a support."], equipment: ["bench or box", "dumbbells (optional)"], commonMistakes: "Letting the front knee cave inward: keep it tracking over the foot.")),
        SeedEntry(matchers: ["crawl continu", "crawl 25 m", "crawl conversational", "crawl 4 × 100", "simulation swim", "crawl pull-buoy en1", "crawl récupération"],
            fr: ExerciseExplanation(steps: ["Nage à une allure très facile où tu peux dire une phrase courte au bord du bassin sans haleter.", "Respire sur ton côté favori toutes les 3 brassées et trouve un rythme régulier.", "Touche le mur en virant sans t'arrêter pour construire la nage continue, longueur après longueur.", "Cherche une nage longue et glissée plutôt que de multiplier les coups de bras.", "L'objectif est l'aisance et la confiance dans l'eau, pas la performance chronométrée."], equipment: ["lunettes", "bonnet"], commonMistakes: "Vouloir aller vite : à ce stade, c'est la régularité et l'aisance qui priment."),
            en: ExerciseExplanation(steps: ["Swim at a very easy pace where you can say a short sentence poolside without gasping.", "Breathe to your favorite side every 3 strokes and find a steady rhythm.", "Touch and turn at the wall without stopping to build continuous swimming, length after length.", "Look for a long, gliding stroke rather than piling up arm strokes.", "The goal is ease and confidence in the water, not a timed performance."], equipment: ["goggles", "swim cap"], commonMistakes: "Trying to go fast: at this stage steadiness and ease matter most.")),
        SeedEntry(matchers: ["repos complet", "check liste matériel", "race-pace 70.3", "swim race", "bike race", "run race", "repos"],
            fr: ExerciseExplanation(steps: ["Prépare et vérifie tout ton matériel la veille : combinaison, lunettes, bonnet, casque, chaussures vélo et course, race-belt, dossard, appareils chargés.", "Le jour de course, gère le pacing : départ conservateur sur chaque discipline puis montée progressive vers l'allure cible.", "Sur le vélo, garde une cadence ronde et ravitaille régulièrement comme à l'entraînement.", "Sur la course, attends-toi aux jambes lourdes les premières minutes, puis installe ton allure.", "Le jour de repos, reste tranquille et laisse le corps récupérer pour arriver frais."], equipment: ["combinaison", "casque", "chaussures vélo", "chaussures de running", "race-belt", "appareils GPS"], commonMistakes: "Partir trop vite dès le départ : un pacing conservateur en début d'épreuve protège la fin de course."),
            en: ExerciseExplanation(steps: ["Prepare and check all your gear the day before: wetsuit, goggles, cap, helmet, bike and run shoes, race belt, bib, charged devices.", "On race day, manage your pacing: a conservative start on each discipline then a gradual build toward target pace.", "On the bike, keep a round cadence and fuel regularly as you did in training.", "On the run, expect heavy legs for the first minutes, then settle into your pace.", "On the rest day, stay quiet and let your body recover so you arrive fresh."], equipment: ["wetsuit", "helmet", "bike shoes", "running shoes", "race belt", "GPS devices"], commonMistakes: "Going out too fast from the start: conservative early pacing protects the end of your race.")),
        SeedEntry(matchers: ["sweet spot", "sweet-spot", "bloc sweet spot", "bike sweet-spot", "race-pace pré-brick"],
            fr: ExerciseExplanation(steps: ["Cale-toi entre 84 et 97 % de ta FTP : un effort soutenu mais gérable, RPE 6-7, où la conversation se réduit à des mots isolés.", "Sans capteur de puissance, repère la sensation : exigeant mais répétable, sans la brûlure du seuil.", "Maintiens une cadence ronde de 90 à 95 tours par minute pour limiter la fatigue musculaire.", "Tiens l'allure régulière sur tout le bloc plutôt que d'attaquer fort puis de t'éteindre.", "Récupère vraiment en Z1 entre les blocs si la séance est en intervalles."], equipment: ["vélo", "casque", "bidons", "capteur de puissance ou cardio"], commonMistakes: "Monter dans le rouge du seuil : le sweet spot reste juste sous, répétable et contrôlé."),
            en: ExerciseExplanation(steps: ["Settle between 84 and 97 % of FTP: a sustained but manageable effort, RPE 6-7, where talking drops to single words.", "Without a power meter, use feel: demanding yet repeatable, without the burn of threshold.", "Hold a round cadence of 90 to 95 rpm to limit muscular fatigue.", "Keep the effort steady across the whole block rather than attacking hard then fading.", "Recover genuinely in Z1 between blocks if the session is interval-based."], equipment: ["bike", "helmet", "bottles", "power meter or HR monitor"], commonMistakes: "Drifting up into threshold red zone: sweet spot stays just below, repeatable and controlled.")),
        SeedEntry(matchers: ["single-leg deadlift", "single leg deadlift", "rdl"],
            fr: ExerciseExplanation(steps: ["Tiens une charge légère dans la main opposée à la jambe d'appui, genou légèrement fléchi.", "Bascule le buste vers l'avant en gardant le dos plat, la jambe libre partant vers l'arrière.", "Descends jusqu'à sentir l'étirement de la chaîne postérieure, sans arrondir le dos.", "Reviens en contrôle en poussant la hanche vers l'avant et en serrant le fessier.", "Va lentement à la descente pour stabiliser hanche et chaîne postérieure et repérer les asymétries."], equipment: ["haltère ou kettlebell"], commonMistakes: "Arrondir le dos : garde-le plat et la bascule vient de la hanche, pas des lombaires."),
            en: ExerciseExplanation(steps: ["Hold a light load in the hand opposite the supporting leg, knee slightly bent.", "Hinge your torso forward keeping a flat back, the free leg reaching behind.", "Lower until you feel the posterior chain stretch, without rounding the back.", "Return under control by driving the hip forward and squeezing the glute.", "Go slowly on the descent to stabilize the hip and posterior chain and spot asymmetries."], equipment: ["dumbbell or kettlebell"], commonMistakes: "Rounding the back: keep it flat and hinge from the hip, not the lumbar spine.")),
        SeedEntry(matchers: ["test ftp", "ftp 20 min all-out", "20 min all-out"],
            fr: ExerciseExplanation(steps: ["Échauffe-toi progressivement, puis roule 20 minutes au maximum soutenable et régulier, sans partir trop fort.", "Note ta puissance moyenne sur les 20 minutes.", "Estime ta FTP en prenant environ 95 % de cette puissance moyenne.", "Cette FTP devient la référence pour caler tes zones de travail vélo.", "Termine par un retour au calme très léger pour récupérer."], equipment: ["vélo", "capteur de puissance", "casque"], commonMistakes: "Partir trop fort sur les premières minutes : un test régulier donne une FTP fiable."),
            en: ExerciseExplanation(steps: ["Warm up progressively, then ride 20 minutes at your sustainable maximum, evenly, without going out too hard.", "Note your average power over the 20 minutes.", "Estimate your FTP as about 95 % of that average power.", "This FTP becomes the reference to set your cycling work zones.", "Finish with a very light cooldown to recover."], equipment: ["bike", "power meter", "helmet"], commonMistakes: "Going out too hard in the first minutes: an even test gives a reliable FTP.")),
        SeedEntry(matchers: ["daniels-e", "course continue", "course daniels", "run daniels-e", "run z2", "course z2", "run easy", "simulation run", "course activation"],
            fr: ExerciseExplanation(steps: ["Garde une allure conversationnelle : tu peux dire une phrase entière sans haleter, autour de RPE 3-4.", "Vise une cadence de 170-180 pas par minute, foulée souple et relâchée.", "Pose le pied sous le centre de gravité, regard à l'horizon, épaules basses.", "Sur les sorties longues, prévois de quoi boire et installe-toi dans un rythme régulier que tu pourrais tenir bien au-delà de la durée prévue.", "Si le souffle s'emballe, ralentis : cette allure construit le moteur aérobie, elle reste facile."], equipment: ["chaussures de running", "montre GPS"], commonMistakes: "Courir trop vite : l'allure facile doit rester vraiment confortable, sinon elle perd son intérêt."),
            en: ExerciseExplanation(steps: ["Hold a conversational pace: you can speak a full sentence without gasping, around RPE 3-4.", "Aim for a cadence of 170-180 steps per minute with a relaxed, springy stride.", "Land under your center of gravity, eyes on the horizon, shoulders loose.", "On long runs, carry fluids and settle into a steady rhythm you could hold well past the planned duration.", "If your breathing climbs, ease off: this pace builds the aerobic engine and is meant to stay easy."], equipment: ["running shoes", "GPS watch"], commonMistakes: "Running too fast: the easy pace should feel genuinely comfortable, otherwise it loses its purpose.")),
        SeedEntry(matchers: ["en1", "long swim", "crawl en1", "long swim continu", "crawl en1 long"],
            fr: ExerciseExplanation(steps: ["Nage à une allure régulière et confortable, autour de CSS plus 8 à 12 secondes au 100 m, sans dérive de vitesse.", "Respire de façon régulière et alterne les côtés (1 sur 3) dès que c'est confortable, pour la symétrie.", "Compte tes coups de bras par 25 m pour garder une nage longue et efficace.", "Garde un corps gainé et aligné, le regard vers le fond, la rotation venant des hanches.", "Sur le long, place un repère de sighting de temps en temps pour préparer l'eau libre."], equipment: ["lunettes", "bonnet"], commonMistakes: "Accélérer puis ralentir sans cesse : vise une allure stable que tu pourrais tenir longtemps."),
            en: ExerciseExplanation(steps: ["Swim at a steady, comfortable pace, around CSS plus 8 to 12 seconds per 100 m, without speed drift.", "Breathe rhythmically and alternate sides (1 in 3) as soon as it feels comfortable, for symmetry.", "Count your strokes per 25 m to keep a long, efficient stroke.", "Keep the body braced and aligned, gaze toward the bottom, rotation coming from the hips.", "On long sets, add a sighting cue now and then to prepare for open water."], equipment: ["goggles", "swim cap"], commonMistakes: "Constantly speeding up then slowing down: aim for a stable pace you could hold for a long time.")),
        SeedEntry(matchers: ["sp1", "sprint 4 × 25", "allure 200 m race", "sprint race-pace"],
            fr: ExerciseExplanation(steps: ["Nage court et vif à allure proche de ta vitesse de course sur 200 m, RPE 9.", "Cherche un coup de bras puissant et un appui propre plutôt qu'une fréquence désordonnée.", "Garde la récupération indiquée pour relancer chaque répétition avec de la qualité.", "Reste gainé et aligné même à haute vitesse pour ne pas perdre la glisse.", "En semaine d'affûtage, ces accélérations courtes réveillent le système nerveux sans fatiguer."], equipment: ["lunettes", "bonnet"], commonMistakes: "Battre des bras dans le désordre : la vitesse vient d'un appui propre, pas de la précipitation."),
            en: ExerciseExplanation(steps: ["Swim short and sharp at a pace close to your 200 m race speed, RPE 9.", "Look for a powerful stroke and a clean catch rather than a frantic turnover.", "Keep the prescribed recovery so each rep relaunches with quality.", "Stay braced and aligned even at high speed so you keep your glide.", "During taper, these short accelerations wake up the nervous system without tiring you."], equipment: ["goggles", "swim cap"], commonMistakes: "Thrashing the arms: speed comes from a clean catch, not from rushing.")),
        SeedEntry(matchers: ["strides", "accélérations", "daniels-r", "4 × 100 m", "100 m progressif"],
            fr: ExerciseExplanation(steps: ["Accélère progressivement sur 80 à 100 m, du trot vers une allure rapide et fluide, sans jamais sprinter à fond.", "Cherche une cadence très haute, 185 pas par minute et plus, avec une attaque médio-pied.", "Garde les épaules relâchées et les bras qui rythment, le geste reste tonique mais léger.", "Décélère en douceur puis récupère en marchant ou en trottant avant la suivante.", "Le but est de réveiller les fibres rapides et la raideur tendineuse, pas de te fatiguer."], equipment: ["chaussures de running"], commonMistakes: "Sprinter à fond et se crisper : une stride reste rapide mais relâchée."),
            en: ExerciseExplanation(steps: ["Build up gradually over 80 to 100 m, from a jog to a fast fluid pace, never a full sprint.", "Find a very high cadence, 185 steps per minute and up, with a midfoot landing.", "Keep shoulders loose and arms driving the rhythm, the motion stays crisp but light.", "Decelerate smoothly then recover by walking or jogging before the next one.", "The aim is to wake up fast-twitch fibers and tendon stiffness, not to tire yourself out."], equipment: ["running shoes"], commonMistakes: "Sprinting flat out and tensing up: a stride stays fast but relaxed.")),
        SeedEntry(matchers: ["drill catch", "sculling", "evf", "fingertip drag", "single-arm catch", "paddles", "pull-buoy catch", "catch single-arm", "drill single-arm"],
            fr: ExerciseExplanation(steps: ["Cherche à orienter l'avant-bras tôt et verticalement (coude haut) pour accrocher plus d'eau vers l'arrière.", "Sur le sculling, fais de petits mouvements en huit pour sentir la pression de l'eau sur la main et l'avant-bras.", "Sur le fingertip drag, laisse les doigts effleurer la surface au retour pour garder le coude haut.", "Nage à effort modéré (autour de 60 %) : l'objectif est la sensation, pas la vitesse.", "Si tu utilises des plaquettes, limite leur volume à une petite part de la séance pour préserver l'épaule."], equipment: ["lunettes", "bonnet", "pull-buoy", "plaquettes"], commonMistakes: "Tirer avec le coude qui tombe : garde le coude haut pour orienter l'avant-bras vers l'arrière."),
            en: ExerciseExplanation(steps: ["Aim to set the forearm early and vertical (high elbow) to catch more water and push it back.", "On sculling, make small figure-eight motions to feel pressure on the hand and forearm.", "On fingertip drag, let the fingers skim the surface on recovery to keep the elbow high.", "Swim at moderate effort (around 60 %): the goal is feel, not speed.", "If you use paddles, keep their volume to a small share of the session to protect the shoulder."], equipment: ["goggles", "swim cap", "pull-buoy", "paddles"], commonMistakes: "Pulling with a dropping elbow: keep the elbow high to angle the forearm backward.")),
        SeedEntry(matchers: ["planche ventrale", "planche", "plank", "side plank", "dead bug"],
            fr: ExerciseExplanation(steps: ["Place les coudes directement sous les épaules, avant-bras au sol.", "Aligne le corps en une ligne droite de la tête aux talons.", "Engage les abdominaux et les fessiers pour éviter de creuser ou de relever le bassin.", "Respire calmement et tiens la position le temps indiqué.", "Sur la planche latérale, empile les épaules et garde le bassin haut et stable."], equipment: ["tapis"], commonMistakes: "Laisser le bassin s'affaisser : garde la ligne tête-talons en gainant le ventre et les fessiers."),
            en: ExerciseExplanation(steps: ["Place your elbows directly under your shoulders, forearms on the floor.", "Align your body in a straight line from head to heels.", "Engage your abs and glutes to avoid sagging or piking the hips.", "Breathe calmly and hold the position for the prescribed time.", "On the side plank, stack the shoulders and keep the hips high and stable."], equipment: ["mat"], commonMistakes: "Letting the hips sag: keep the head-to-heels line by bracing the abs and glutes.")),
        SeedEntry(matchers: ["daniels-t", "tempo", "seuil", "threshold run", "cruise interval"],
            fr: ExerciseExplanation(steps: ["Installe une allure « confortablement difficile », celle que tu tiendrais environ une heure en course (autour du 10 km plus 15 à 30 secondes par km).", "Repère parole : 4 à 5 mots d'affilée passent, une phrase entière non.", "Garde la cadence haute, 180 pas par minute, et un effort régulier du début à la fin.", "Sur les versions en intervalles, trotte doucement pendant les récupérations puis relance à la même allure.", "Vise un effort constant plutôt que partir vite : c'est la régularité qui fait progresser le seuil."], equipment: ["chaussures de running", "montre GPS"], commonMistakes: "Partir trop fort et finir en sur-régime : le tempo se court à allure maîtrisée et stable."),
            en: ExerciseExplanation(steps: ["Settle into a comfortably hard pace, one you could hold for about an hour racing (roughly 10K pace plus 15 to 30 seconds per km).", "Speech check: 4 to 5 words in a row come out, a full sentence does not.", "Keep cadence high, around 180 steps per minute, with an even effort start to finish.", "On interval versions, jog gently during recoveries then pick the same pace back up.", "Aim for a constant effort rather than a fast start: steadiness is what lifts your threshold."], equipment: ["running shoes", "GPS watch"], commonMistakes: "Going out too hard and overcooking it: tempo is run at a controlled, steady pace.")),
        SeedEntry(matchers: ["daniels-i", "intervalles", "5 × 1000", "6 × 1000", "vo2max 5 × 1000", "5 km pace"],
            fr: ExerciseExplanation(steps: ["Vise une allure proche de ton 3 à 5 km, un effort fort mais soutenable, autour de RPE 8-9.", "Cadence haute et foulée dynamique, le buste reste droit et le regard à l'horizon.", "Pendant la récupération, trotte ou marche activement pour faire redescendre le souffle.", "Cherche une allure identique sur chaque répétition plutôt qu'un sprint sur la première.", "Si l'allure se dégrade nettement sur la dernière, mieux vaut écourter en gardant la qualité."], equipment: ["chaussures de running", "montre GPS"], commonMistakes: "Démarrer trop vite la première répétition et s'écrouler sur les suivantes."),
            en: ExerciseExplanation(steps: ["Target a pace close to your 3 to 5K, a strong but sustainable effort around RPE 8-9.", "Keep cadence high and the stride dynamic, torso tall, eyes on the horizon.", "During recovery, jog or walk briskly to let your breathing come back down.", "Look for the same pace on every rep rather than sprinting the first one.", "If the pace clearly fades on the last rep, it is better to cut it short and keep the quality."], equipment: ["running shoes", "GPS watch"], commonMistakes: "Starting the first rep too fast and falling apart on the ones that follow.")),
        SeedEntry(matchers: ["ftp-z2", "sortie route", "bike z2", "pédalage ftp-z2", "long ride", "endurance ftp", "bike ftp-z2", "sortie route z2", "bike easy"],
            fr: ExerciseExplanation(steps: ["Roule à allure conversationnelle, autour de 56 à 75 % de ta FTP (RPE 3-4), tu peux discuter sans t'essouffler.", "Garde une cadence souple de 85 à 95 tours par minute plutôt que de tirer de gros braquets.", "Sur le plat reste fluide, en bosse passe en danseuse une demi-minute ou rétrograde pour ne pas surcharger.", "Sur les dernières minutes, monte la cadence vers 95-100 tours par minute pour préparer une transition fluide.", "Bois et ravitaille régulièrement sur les longues sorties pour entraîner l'estomac."], equipment: ["vélo", "casque", "bidons", "ravitaillement glucidique"], commonMistakes: "Pédaler trop gros et trop lent : privilégie une cadence ronde et une allure que tu peux tenir des heures."),
            en: ExerciseExplanation(steps: ["Ride at a conversational effort, around 56 to 75 % of FTP (RPE 3-4), able to chat without getting winded.", "Keep a smooth cadence of 85 to 95 rpm rather than grinding big gears.", "Stay fluid on the flat; on climbs stand for half a minute or shift down to avoid overloading.", "In the last minutes, lift cadence toward 95-100 rpm to set up a smooth transition.", "Drink and fuel regularly on long rides to train your stomach."], equipment: ["bike", "helmet", "bottles", "carbohydrate fuel"], commonMistakes: "Pushing a big gear too slowly: favor a round cadence and a pace you can hold for hours.")),
        SeedEntry(matchers: ["vo2max", "ftp-z5", "ftp-z4", "threshold 3 ×", "5 × 4 min ftp", "4 × 12 min ftp"],
            fr: ExerciseExplanation(steps: ["Sur les blocs FTP-Z4, vise un effort très exigeant et soutenu (RPE 7-8), mots isolés seulement.", "Sur les blocs VO2max (FTP-Z5), monte plus haut encore (RPE 8-9) avec une cadence vive de 95 à 105 tours par minute.", "Dose la première répétition : pacing régulier plutôt que d'exploser d'entrée.", "Récupère activement en Z1 entre les efforts pour pouvoir relancer proprement.", "Sans capteur de puissance, fie-toi au RPE strict et à ta respiration."], equipment: ["vélo", "casque", "capteur de puissance ou cardio"], commonMistakes: "Exploser sur la première répétition et ne plus tenir l'allure ensuite."),
            en: ExerciseExplanation(steps: ["On FTP-Z4 blocks, target a very demanding sustained effort (RPE 7-8), single words only.", "On VO2max blocks (FTP-Z5), go higher still (RPE 8-9) with a brisk cadence of 95 to 105 rpm.", "Meter the first rep: even pacing rather than blowing up from the start.", "Recover actively in Z1 between efforts so you can relaunch cleanly.", "Without a power meter, rely on strict RPE and your breathing."], equipment: ["bike", "helmet", "power meter or HR monitor"], commonMistakes: "Blowing up on the first rep and being unable to hold the pace afterward.")),
        SeedEntry(matchers: ["sighting", "drill sighting", "eau libre", "combinaison"],
            fr: ExerciseExplanation(steps: ["Lève juste les yeux au-dessus de la surface, comme un crocodile, en gardant le menton bas, puis repose la tête pour respirer sur le côté.", "Repère un point fixe devant toi, puis reprends une nage longue et alignée.", "Sur le long, place un sighting toutes les 50 m environ pour t'habituer sans casser le rythme.", "Avec combinaison, vérifie le confort et entraîne-toi à la sortir rapidement au sec après la sortie d'eau.", "Garde les jambes actives pendant le repère pour ne pas couler à l'avant."], equipment: ["lunettes", "bonnet", "combinaison néoprène"], commonMistakes: "Sortir toute la tête : seuls les yeux passent au-dessus de l'eau, le geste reste fluide."),
            en: ExerciseExplanation(steps: ["Lift just your eyes above the surface, like a crocodile, chin low, then drop your head to breathe to the side.", "Spot a fixed point ahead, then resume a long, aligned stroke.", "On long swims, sight roughly every 50 m to get used to it without breaking rhythm.", "With a wetsuit, check the comfort and practice peeling it off quickly on dry land after the water exit.", "Keep your legs active while you sight so your front end does not sink."], equipment: ["goggles", "swim cap", "wetsuit"], commonMistakes: "Lifting the whole head: only the eyes clear the water, the stroke stays fluid.")),
        SeedEntry(matchers: ["post-bike", "brick", "post-t2", "premier brick", "post bike"],
            fr: ExerciseExplanation(steps: ["Sur les 5 à 10 premières minutes, attends-toi aux jambes en coton : c'est physiologique, le corps réorganise le geste vélo vers la course.", "Démarre prudemment avec une foulée raccourcie et une cadence élevée, autour de 180 pas par minute.", "Laisse le rythme se mettre en place naturellement, sans chercher à accélérer trop tôt.", "Vers la 10e minute, la sensation s'estompe et l'allure cible devient plus fluide.", "Garde le buste droit et le regard loin pour stabiliser la coordination dès la descente du vélo."], equipment: ["chaussures de running", "lacets élastiques"], commonMistakes: "Partir trop vite à la descente du vélo : raccourcis la foulée et laisse les jambes se réorganiser."),
            en: ExerciseExplanation(steps: ["For the first 5 to 10 minutes, expect heavy legs: it is physiological, your body is rewiring the cycling motion into running.", "Start cautiously with a shortened stride and a high cadence, around 180 steps per minute.", "Let the rhythm settle naturally without trying to speed up too soon.", "By around minute 10 the feeling fades and your target pace flows more easily.", "Keep your torso tall and gaze far to steady your coordination right off the bike."], equipment: ["running shoes", "elastic laces"], commonMistakes: "Going out too fast off the bike: shorten the stride and let your legs reorganize.")),
        SeedEntry(matchers: ["css", "css pace", "en2", "en3", "css+5s", "css-5s", "set css", "seuil aérobie"],
            fr: ExerciseExplanation(steps: ["Nage à ton allure CSS, le rythme seuil que tu peux tenir de façon soutenue, RPE 7-8 selon le set.", "Respecte la récupération courte indiquée pour maintenir l'intensité d'une répétition à l'autre.", "Vise une dérive minimale : le dernier 100 m doit ressembler au premier en temps.", "Garde un coup de bras stable et compte-les pour vérifier que la technique tient sous fatigue.", "Si tu décroches nettement vers la fin du set, mieux vaut écourter en gardant le pacing propre."], equipment: ["lunettes", "bonnet", "pace-clock ou montre"], commonMistakes: "Partir trop vite sur les premières répétitions et craquer sur les dernières."),
            en: ExerciseExplanation(steps: ["Swim at your CSS pace, the threshold rhythm you can sustain, RPE 7-8 depending on the set.", "Respect the short recovery shown to hold the intensity from one rep to the next.", "Aim for minimal drift: the last 100 m should match the first in time.", "Keep a stable stroke count to check that technique holds under fatigue.", "If you clearly fade near the end of the set, it is better to cut it short and keep the pacing clean."], equipment: ["goggles", "swim cap", "pace clock or watch"], commonMistakes: "Going out too fast on the first reps and cracking on the last ones.")),
        SeedEntry(matchers: ["test css", "400 m all-out", "200 m all-out", "css 400", "css 200"],
            fr: ExerciseExplanation(steps: ["Échauffe-toi bien, puis nage le 400 m en tout-pour-tout régulier, sans sprinter le départ, et note ton temps.", "Récupère complètement une dizaine de minutes au bord du bassin (marche, hydratation, relâchement des épaules).", "Enchaîne le 200 m tout-pour-tout sur la même logique de pacing régulier, et note ton temps.", "Calcule ta CSS : la différence de distance divisée par la différence de temps donne ton allure seuil au 100 m.", "Cette CSS sert ensuite de repère pour caler toutes tes allures de natation."], equipment: ["lunettes", "bonnet", "chronomètre"], commonMistakes: "Sprinter le départ du 400 m : un test fiable se nage à allure régulière du début à la fin."),
            en: ExerciseExplanation(steps: ["Warm up well, then swim the 400 m as a steady all-out effort, no sprint start, and note your time.", "Recover fully for about ten minutes poolside (walk, hydrate, loosen the shoulders).", "Follow with the 200 m all-out using the same even pacing, and note your time.", "Compute your CSS: the distance difference divided by the time difference gives your threshold pace per 100 m.", "This CSS then serves as the reference to set all your swim paces."], equipment: ["goggles", "swim cap", "stopwatch"], commonMistakes: "Sprinting the start of the 400 m: a reliable test is swum at an even pace start to finish.")),
        SeedEntry(matchers: ["pont fessier", "glute bridge"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le dos, genoux pliés, pieds à plat largeur de hanches.", "Pousse dans les talons pour monter le bassin jusqu'à aligner épaules, hanches et genoux.", "Serre les fessiers une à deux secondes en haut sans creuser le bas du dos.", "Redescends lentement et contrôle le mouvement.", "Sur la version unilatérale, garde le bassin bien horizontal sans qu'un côté s'affaisse."], equipment: ["tapis"], commonMistakes: "Cambrer le bas du dos en haut : la poussée vient des fessiers, pas des lombaires."),
            en: ExerciseExplanation(steps: ["Lie on your back, knees bent, feet flat hip-width apart.", "Drive through your heels to lift the hips until shoulders, hips and knees align.", "Squeeze the glutes one to two seconds at the top without arching the low back.", "Lower slowly and control the movement.", "On the single-leg version, keep the pelvis level so neither side drops."], equipment: ["mat"], commonMistakes: "Arching the low back at the top: the drive comes from the glutes, not the lumbar spine.")),
        SeedEntry(matchers: ["nordic curl", "nordic"],
            fr: ExerciseExplanation(steps: ["Place-toi à genoux, chevilles bien bloquées sous un appui stable, corps gréé de la tête aux genoux.", "Garde les fessiers serrés et le bassin dans l'alignement, sans plier au niveau des hanches.", "Descends le buste vers l'avant le plus lentement possible, en freinant (3 à 5 secondes).", "Pose les mains au sol pour amortir en bas, puis aide-toi des bras pour remonter.", "Réduis l'amplitude de descente tant que le freinage n'est pas maîtrisé."], equipment: ["tapis", "appui pour bloquer les chevilles"], commonMistakes: "Plier au niveau des hanches : le corps reste gainé en planche, le mouvement vient des cuisses."),
            en: ExerciseExplanation(steps: ["Kneel with ankles firmly anchored under a stable hold, body rigid from head to knees.", "Keep the glutes squeezed and the pelvis aligned, without folding at the hips.", "Lower your torso forward as slowly as possible, braking the descent (3 to 5 seconds).", "Place your hands on the floor to cushion the bottom, then use your arms to come back up.", "Reduce the range of descent until the braking is well controlled."], equipment: ["mat", "anchor to hold the ankles"], commonMistakes: "Folding at the hips: the body stays rigid like a plank, the motion comes from the thighs.")),
        SeedEntry(matchers: ["calf raises", "calf", "calf raise"],
            fr: ExerciseExplanation(steps: ["Tiens-toi debout, idéalement le bord du pied sur une marche, talons libres dans le vide.", "Monte sur la pointe en une seconde, en cherchant l'amplitude complète vers le haut.", "Sur les versions excentriques, descends lentement (3 à 4 secondes) sous le niveau de la marche.", "Sur les versions unipodales, monte sur deux pieds et descends sur un seul pour augmenter la charge.", "Garde l'équilibre avec une main en appui léger si besoin."], equipment: ["marche ou step"], commonMistakes: "Descendre trop vite : c'est la descente lente et contrôlée qui renforce le mollet et le tendon."),
            en: ExerciseExplanation(steps: ["Stand tall, ideally with the ball of your foot on a step, heels free in the air.", "Rise onto the balls of your feet in one second, reaching full range at the top.", "On eccentric versions, lower slowly (3 to 4 seconds) below the level of the step.", "On single-leg versions, rise on two feet and lower on one to add load.", "Keep your balance with a light hand support if needed."], equipment: ["step"], commonMistakes: "Lowering too fast: it is the slow, controlled descent that strengthens the calf and tendon.")),
        SeedEntry(matchers: ["hip thrust"],
            fr: ExerciseExplanation(steps: ["Cale le haut du dos sur un banc, pieds à plat largeur de hanches.", "Place une charge sur le pli des hanches (haltère ou kettlebell) en la maintenant.", "Pousse dans les talons pour monter le bassin jusqu'à l'horizontale, tibias verticaux.", "Serre les fessiers une à deux secondes en haut, menton légèrement rentré.", "Redescends en contrôle sans laisser le bassin tomber d'un coup."], equipment: ["banc", "haltère ou kettlebell"], commonMistakes: "Pousser le bassin trop haut en cambrant : monte jusqu'à l'horizontale en serrant les fessiers."),
            en: ExerciseExplanation(steps: ["Rest your upper back on a bench, feet flat hip-width apart.", "Place a load across the hip crease (dumbbell or kettlebell) and hold it.", "Drive through your heels to lift the hips to horizontal, shins vertical.", "Squeeze the glutes one to two seconds at the top, chin slightly tucked.", "Lower under control without letting the hips drop suddenly."], equipment: ["bench", "dumbbell or kettlebell"], commonMistakes: "Over-arching at the top: rise to horizontal by squeezing the glutes.")),
        SeedEntry(matchers: ["clamshell", "clam ", "clam+"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le côté, genoux pliés et talons alignés avec le bassin.", "Si tu en as une, place une mini-bande élastique juste au-dessus des genoux.", "Ouvre le genou supérieur en gardant les pieds joints, sans bouger le bassin.", "Contrôle la remontée et la descente, l'effort vient des muscles de la hanche.", "Garde le buste stable, le mouvement reste isolé sur la hanche."], equipment: ["tapis", "mini-bande élastique"], commonMistakes: "Faire rouler le bassin en arrière : seul le genou du dessus s'ouvre, le bassin reste fixe."),
            en: ExerciseExplanation(steps: ["Lie on your side, knees bent and heels in line with your hips.", "If you have one, place a mini-band just above the knees.", "Open the top knee while keeping the feet together, without moving the pelvis.", "Control the lift and the return, the effort comes from the hip muscles.", "Keep the torso stable, the motion stays isolated at the hip."], equipment: ["mat", "mini-band"], commonMistakes: "Rolling the pelvis backward: only the top knee opens, the pelvis stays fixed.")),
        SeedEntry(matchers: ["bird-dog", "bird dog"],
            fr: ExerciseExplanation(steps: ["Place-toi à quatre pattes, mains sous les épaules et genoux sous les hanches.", "Tends simultanément un bras et la jambe opposée, dans le prolongement du corps.", "Garde le bassin et les épaules parallèles au sol, sans rotation ni bascule.", "Tiens une à deux secondes en gainant le ventre, puis reviens lentement contrôlé.", "Alterne les côtés en gardant la colonne neutre du début à la fin."], equipment: ["tapis"], commonMistakes: "Laisser le bassin tourner : garde les hanches bien à plat et le mouvement lent."),
            en: ExerciseExplanation(steps: ["Get on all fours, hands under shoulders and knees under hips.", "Extend one arm and the opposite leg at the same time, in line with the body.", "Keep your hips and shoulders parallel to the floor, no rotation or tilt.", "Hold one to two seconds bracing the core, then return slowly and controlled.", "Alternate sides keeping the spine neutral throughout."], equipment: ["mat"], commonMistakes: "Letting the hips rotate: keep the pelvis flat and the movement slow.")),
        SeedEntry(matchers: ["wall sit"],
            fr: ExerciseExplanation(steps: ["Place le dos plat contre un mur, pieds avancés et écartés largeur de hanches.", "Glisse vers le bas jusqu'à un angle confortable des genoux (autour de 60 à 70 degrés).", "Garde les genoux alignés au-dessus des pieds et le dos en contact avec le mur.", "Respire calmement et tiens la position le temps prévu.", "Si l'effort devient trop intense, remonte un peu pour réduire l'angle."], equipment: ["mur"], commonMistakes: "Descendre trop bas d'emblée : garde un angle confortable et le dos plaqué au mur."),
            en: ExerciseExplanation(steps: ["Place your back flat against a wall, feet forward and hip-width apart.", "Slide down to a comfortable knee angle (around 60 to 70 degrees).", "Keep the knees tracking over the feet and the back in contact with the wall.", "Breathe calmly and hold for the planned time.", "If the effort gets too intense, rise a little to reduce the angle."], equipment: ["wall"], commonMistakes: "Dropping too low right away: keep a comfortable angle with the back against the wall.")),
        SeedEntry(matchers: ["step-up", "step up"],
            fr: ExerciseExplanation(steps: ["Place un pied entier sur une boîte stable d'environ 40 cm.", "Monte en poussant dans la jambe d'appui, sans t'aider de l'élan de l'autre jambe.", "Garde le buste droit et le genou aligné au-dessus du pied.", "Redescends lentement en contrôlant la pose du pied au sol.", "Termine toutes les répétitions d'un côté avant de changer de jambe."], equipment: ["boîte ou step stable"], commonMistakes: "S'aider de l'élan de la jambe libre : la poussée vient de la jambe posée sur la boîte."),
            en: ExerciseExplanation(steps: ["Place your whole foot on a stable box of about 40 cm.", "Step up by driving through the supporting leg, without using momentum from the other leg.", "Keep your torso tall and the knee tracking over the foot.", "Lower slowly, controlling how the foot meets the floor.", "Finish all reps on one side before switching legs."], equipment: ["stable box or step"], commonMistakes: "Using momentum from the free leg: the drive comes from the leg on the box.")),

        // MARK: hiking (23)
        SeedEntry(matchers: ["calf raises excentriques", "single-leg calf raises excentriques", "calf raises bipodal", "calf raises", "excentrique chargé", "single-leg calf raises"],
            fr: ExerciseExplanation(steps: ["Place-toi debout, idéalement l'avant des pieds sur le bord d'une marche, le talon libre de descendre.", "Monte sur la pointe des deux pieds, puis transfère le poids sur une seule jambe et redescends lentement le talon en environ 4 secondes.", "Contrôle toute la descente: c'est cette phase lente, où le mollet freine en s'allongeant, qui renforce le tendon d'Achille sous charge.", "Pour charger davantage, tiens un haltère dans la main du côté travaillé, et garde le mouvement strict sans à-coups."], equipment: ["marche ou step", "haltère (optionnel)"], commonMistakes: "Laisser le talon retomber d'un coup au lieu de contrôler la descente, ce qui annule l'effet recherché sur le tendon."),
            en: ExerciseExplanation(steps: ["Stand tall, ideally with the balls of your feet on the edge of a step so the heel can drop freely.", "Rise onto the toes of both feet, then shift weight onto one leg and lower the heel slowly over about 4 seconds.", "Control the entire descent: that slow lowering phase, where the calf brakes as it lengthens, is what loads the Achilles tendon.", "To add load, hold a dumbbell in the hand on the working side, and keep the movement strict without bouncing."], equipment: ["step or ledge", "dumbbell (optional)"], commonMistakes: "Letting the heel drop suddenly instead of controlling the descent, which cancels the intended tendon effect.")),
        SeedEntry(matchers: ["split squat bulgare", "bulgarian split squat", "split squat bulgare poids du corps", "single-leg squat", "single leg squat"],
            fr: ExerciseExplanation(steps: ["Place le pied arrière surélevé sur un banc (30 à 40 cm), le pied avant assez loin devant pour que le genou reste dans l'axe au moment de la descente.", "Penche très légèrement le buste vers l'avant à partir des hanches, puis descends lentement en 2 à 3 secondes.", "Mets l'essentiel du poids sur le pied avant à plat et pousse à travers le talon pour remonter de façon contrôlée.", "Pour charger, tiens un sac à dos ou des haltères; ce travail jambe par jambe reproduit l'effort de montée et de descente sur sentier."], equipment: ["banc ou step", "sac à dos ou haltères (optionnel)"], commonMistakes: "Laisser le genou avant partir vers l'intérieur ou basculer le poids vers l'avant; garde l'appui solide sous le pied avant."),
            en: ExerciseExplanation(steps: ["Set your rear foot up on a bench (30 to 40 cm), front foot far enough ahead that the knee stays tracking over the toes as you lower.", "Lean your torso slightly forward from the hips, then lower slowly over 2 to 3 seconds.", "Keep most of the weight on your flat front foot and push through the heel to rise back up under control.", "To load it, hold a backpack or dumbbells; this leg-by-leg work mirrors climbing and descending effort on trail."], equipment: ["bench or step", "backpack or dumbbells (optional)"], commonMistakes: "Letting the front knee cave inward or shifting weight forward; keep a solid base under the front foot.")),
        SeedEntry(matchers: ["me workout", "bloc continu montee z3", "bloc montee z3", "muscular endurance", "montee continue z3", "bloc rpe 6-7 sustained climbing", "sustained climb"],
            fr: ExerciseExplanation(steps: ["Le travail d'endurance musculaire se fait en montée chargée continue: l'enjeu n'est pas le souffle mais la capacité des jambes à pousser longtemps.", "Cale un effort comfortably hard (phrases courtes), trouve une pente soutenue autour de 7 à 12% et monte sans pause sur toute la durée du bloc.", "Tiens une cadence régulière (100 à 115 pas par minute) et pousse en extension complète de la hanche et du genou à chaque pas.", "Règle le sac haut et serré sur les hanches; ce poids contre la gravité en montée est exactement le stimulus recherché.", "Garde de quoi finir le bloc: si les jambes brûlent fort à mi-parcours, réduis légèrement l'allure plutôt que la pente."], equipment: ["sac à dos chargé", "bâtons de marche"], commonMistakes: "Faire ce bloc sur du plat avec un sac lourd: c'est la montée contre gravité qui crée l'adaptation, pas le poids sur terrain plat."),
            en: ExerciseExplanation(steps: ["Muscular endurance work is done as a continuous loaded climb: the challenge is not your breathing but your legs' ability to push for a long time.", "Set a comfortably hard effort (short sentences), find a sustained grade around 7 to 12% and climb without pausing for the whole block.", "Hold a steady cadence (100 to 115 steps per minute) and push to full hip and knee extension on every step.", "Set the pack high and snug on your hips; that weight against gravity uphill is exactly the stimulus you want.", "Keep something in reserve to finish: if your legs burn hard at halfway, ease the pace slightly rather than the grade."], equipment: ["loaded backpack", "trekking poles"], commonMistakes: "Doing this block on flat ground with a heavy pack: it is the climb against gravity that builds the adaptation, not weight on flat terrain.")),
        SeedEntry(matchers: ["echauffement mobilite dynamique", "echauffement mobilite", "mobilite dynamique", "y-t-w shoulder mobilite", "y-t-w"],
            fr: ExerciseExplanation(steps: ["Enchaîne des mouvements dynamiques pour réveiller les articulations: cercles de hanches, fentes marchées, balanciers de jambe avant-arrière.", "Ajoute des rotations thoraciques et, à plat ventre, des Y-T-W avec les bras pour activer le haut du dos qui portera le sac.", "Termine par des montées de genoux et talons-fesses pour élever progressivement le rythme cardiaque.", "Garde des amplitudes confortables et progressives; l'objectif est de préparer le corps, pas de s'étirer à froid au maximum."], equipment: [], commonMistakes: "Faire des mouvements brusques ou chercher l'amplitude maximale d'emblée; monte en intensité graduellement."),
            en: ExerciseExplanation(steps: ["Flow through dynamic moves to wake up the joints: hip circles, walking lunges, front-to-back leg swings.", "Add thoracic rotations and, lying face down, Y-T-W arm raises to switch on the upper back that will carry the pack.", "Finish with high knees and heel kicks to gradually lift your heart rate.", "Keep ranges comfortable and progressive; the goal is to prep the body, not to stretch cold at maximum."], equipment: [], commonMistakes: "Doing jerky moves or reaching for maximum range right away; build intensity gradually.")),
        SeedEntry(matchers: ["z2-cardiac", "marche endurance z2-cardiac", "aerobic threshold", "marche z2-cardiac", "bloc z2-cardiac", "bloc z2 base avec inclusions", "z2-z3"],
            fr: ExerciseExplanation(steps: ["Vise un effort soutenu mais tenable: conversational soutenu, tu places des phrases entières même si le souffle se fait sentir. C'est le seuil aérobie.", "Garde la cadence métronome autour de 110-115 pas par minute, surtout en montée où la tentation est d'accélérer la foulée.", "Quand le terrain monte, joue sur des pas plus courts et plus fréquents pour maintenir le rythme cardiaque dans la fenêtre, sans à-coups.", "Sur les inclusions plus intenses prévues, monte d'un cran l'effort quelques minutes puis reviens calmement à la base."], equipment: ["sac à dos", "bâtons de marche", "eau"], commonMistakes: "Laisser l'allure dériver vers le haut sur les longues montées au lieu de tenir une intensité régulière sur toute la durée."),
            en: ExerciseExplanation(steps: ["Aim for a sustained but holdable effort: comfortably talkative, you can speak full sentences even as breathing picks up. This is your aerobic threshold.", "Keep a metronome cadence around 110-115 steps per minute, especially uphill where the urge is to speed up your stride.", "When the terrain rises, use shorter, more frequent steps to keep heart rate in the window smoothly, without surges.", "On the planned higher-intensity inserts, lift the effort one notch for a few minutes then ease back to base."], equipment: ["backpack", "trekking poles", "water"], commonMistakes: "Letting the pace drift upward on long climbs instead of holding a steady intensity across the whole duration.")),
        SeedEntry(matchers: ["checklist autonomie", "checklist autonomie finale", "auto-evaluation"],
            fr: ExerciseExplanation(steps: ["Fais le point sur ta préparation avec des critères mesurables: capacité à tenir une longue journée de marche avec le dénivelé et le poids de sac visés.", "Vérifie le matériel essentiel et le réglage du sac, ainsi que des chaussures bien rodées pour les longues distances.", "Repasse mentalement ta gestion de l'hydratation et de l'alimentation par heure d'effort.", "Note honnêtement les points encore fragiles (technique de descente, gestion d'allure) pour ajuster tes derniers ajustements avant le départ."], equipment: [], commonMistakes: "Surévaluer sa préparation: appuie-toi sur des critères concrets déjà testés en sortie plutôt que sur une impression."),
            en: ExerciseExplanation(steps: ["Take stock of your readiness with measurable criteria: ability to hold a long hiking day at your target elevation gain and pack weight.", "Check your essential gear and pack fit, plus shoes well broken in for long distances.", "Mentally review your hydration and fueling plan per hour of effort.", "Honestly note any still-fragile points (descent technique, pace management) to fine-tune before departure."], equipment: [], commonMistakes: "Overrating your readiness: lean on concrete criteria already tested on outings rather than a gut feeling.")),
        SeedEntry(matchers: ["marche z1", "marche recuperation", "recup marche plate", "recuperation marche plate", "marche plate z1", "marche z1 recup"],
            fr: ExerciseExplanation(steps: ["Marche à allure très facile, en dessous de la zone aérobie de base: aucune sensation d'effort, respiration nasale possible.", "Choisis du terrain plat et laisse la cadence libre, sans chercher à tenir un rythme précis.", "Garde le buste relâché et les épaules basses; l'objectif est de relancer la circulation, pas de progresser.", "Si possible, fais cette marche sans sac pour favoriser un retour au calme complet."], equipment: [], commonMistakes: "Transformer la récup en vraie séance en accélérant: ici, plus c'est facile, mieux c'est."),
            en: ExerciseExplanation(steps: ["Walk at a very easy pace, below your aerobic base zone: no sense of effort, nose-breathing possible.", "Pick flat terrain and let cadence be free, with no target rhythm.", "Keep your torso relaxed and shoulders low; the goal is to get blood flowing, not to make gains.", "If you can, do this walk without a pack to allow a full wind-down."], equipment: [], commonMistakes: "Turning recovery into a real session by speeding up: here, the easier the better.")),
        SeedEntry(matchers: ["rpe 8-9", "steep gradient", "steep gradient heavy load", "hill repeats rpe 8-9"],
            fr: ExerciseExplanation(steps: ["Bloc de haute intensité: l'effort est proche du maximum tenable, tu ne places plus que des mots isolés en montant la pente raide.", "Cherche un gradient soutenu (12 à 18%) et garde une cadence stable même quand l'effort monte; appuie franchement sur les bâtons pour soulager les jambes.", "Reste maître de ta technique: pas réguliers, poussée depuis la hanche, regard en avant pour anticiper les appuis.", "Récupère longuement en descente facile entre les répétitions, le temps que le souffle redevienne posé.", "Si l'essoufflement devient incontrôlable, redescends à un effort comfortably hard plutôt que de t'écrouler."], equipment: ["bâtons de marche", "sac à dos chargé"], commonMistakes: "Sacrifier la régularité de la cadence pour tenir l'intensité, ce qui casse la mécanique de montée."),
            en: ExerciseExplanation(steps: ["High-intensity block: effort sits near your holdable max, you can only say single words while climbing the steep grade.", "Find a sustained gradient (12 to 18%) and keep a steady cadence even as effort rises; press firmly on the poles to spare your legs.", "Stay in control of your technique: even steps, drive from the hip, eyes ahead to anticipate footing.", "Recover fully on an easy descent between reps, until your breathing settles.", "If breathing gets out of control, drop back to a comfortably hard effort rather than blowing up."], equipment: ["trekking poles", "loaded backpack"], commonMistakes: "Sacrificing cadence steadiness to hold the intensity, which breaks your climbing mechanics.")),
        SeedEntry(matchers: ["descente technique", "drills technique descente", "drills descente", "descente technique t2", "descente technique t3", "drills descente technique"],
            fr: ExerciseExplanation(steps: ["Allonge les bâtons de 5 à 10 cm par rapport à ton réglage de marche à plat, pour rester plus droit et garder un bon équilibre en descente.", "Adopte le pas du chamois: petits pas rapprochés et rapides, plutôt que de grandes enjambées qui sollicitent fort les genoux.", "Plante le bâton du côté opposé au pied d'appui, légèrement en avant, pour transférer une partie de l'impact sur les bras à chaque pose.", "Lis le terrain à l'avance (3 à 5 mètres devant) pour choisir tes appuis sans t'arrêter, et garde le bassin bas et centré au-dessus des pieds.", "Sur les portions raides, essaie la séquence planter-poser-glisser pour contrôler la descente avec fluidité."], equipment: ["bâtons de marche"], commonMistakes: "Verrouiller les genoux et bloquer la descente avec de grands pas, ce qui malmène les articulations sur les longues descentes."),
            en: ExerciseExplanation(steps: ["Lengthen your poles by 5 to 10 cm versus your flat-walking setting, to stay more upright and keep balance on the descent.", "Use the chamois step: small, close, quick steps rather than long strides that load the knees heavily.", "Plant the pole on the side opposite your support foot, slightly ahead, to transfer some impact to your arms on each placement.", "Read the terrain ahead (3 to 5 meters) to pick footing without stopping, and keep your hips low and centered over your feet.", "On steep sections, try the plant-step-slide sequence to control the descent smoothly."], equipment: ["trekking poles"], commonMistakes: "Locking the knees and braking with long steps, which hammers the joints on long descents.")),
        SeedEntry(matchers: ["romanian deadlift", "deadlift conventionnel", "deadlift", "single-leg deadlift", "single leg deadlift", "charniere hanche", "romanian deadlift leger"],
            fr: ExerciseExplanation(steps: ["Pieds largeur de bassin, charge devant les jambes; engage les abdominaux et garde le dos en position neutre tout du long.", "Réalise une charnière de hanche: pousse le bassin vers l'arrière en laissant la charge glisser le long des jambes, genoux à peine fléchis.", "Descends jusqu'à sentir l'étirement des ischio-jambiers à l'arrière des cuisses, puis remonte en poussant le bassin vers l'avant.", "Pour la version une jambe, ralentis le geste et fixe un point devant toi pour stabiliser l'équilibre."], equipment: ["barre ou haltères"], commonMistakes: "Plier le dos au lieu de charnière à partir des hanches; le mouvement vient du bassin, pas de la colonne."),
            en: ExerciseExplanation(steps: ["Feet hip-width, load in front of your legs; brace your core and keep a neutral spine throughout.", "Perform a hip hinge: push your hips back as the load slides down your legs, knees only slightly bent.", "Lower until you feel the hamstrings stretch behind your thighs, then rise by driving your hips forward.", "For the single-leg version, slow the movement down and fix a point ahead to steady your balance."], equipment: ["barbell or dumbbells"], commonMistakes: "Bending the back instead of hinging from the hips; the movement comes from the pelvis, not the spine.")),
        SeedEntry(matchers: ["gainage ventral planche", "gainage ventral", "planche", "plank", "plank + pallof", "plank + side plank"],
            fr: ExerciseExplanation(steps: ["Place les coudes directement sous les épaules, les avant-bras au sol, et déroule les jambes en appui sur les pointes de pieds.", "Aligne tout le corps de la tête aux talons: serre les fessiers et engage les abdominaux pour éviter que le bassin ne creuse ou ne remonte.", "Garde la nuque longue, le regard vers le sol légèrement en avant des mains, et respire calmement pendant la tenue.", "Tiens la durée prévue en gardant la ligne stable; arrête la série dès que les hanches commencent à s'affaisser."], equipment: [], commonMistakes: "Laisser le bassin s'affaisser ou remonter en pic: vise une ligne droite et stable de la tête aux talons."),
            en: ExerciseExplanation(steps: ["Set your elbows directly under your shoulders, forearms on the floor, and extend your legs onto your toes.", "Line up the whole body from head to heels: squeeze your glutes and brace your core so the hips neither sag nor pike up.", "Keep your neck long, gaze toward the floor just ahead of your hands, and breathe calmly while holding.", "Hold for the planned time keeping the line stable; end the set as soon as your hips start to drop."], equipment: [], commonMistakes: "Letting the hips sag or pike up: aim for a straight, stable line from head to heels.")),
        SeedEntry(matchers: ["hill repeats", "hill repeats z3", "hill repeats rpe", "hill repeats taper", "intervalle montee", "bondissements alternes", "a-skip"],
            fr: ExerciseExplanation(steps: ["Échauffe-toi en marche facile avant le premier intervalle, puis attaque la montée à un effort comfortably hard: phrases courtes possibles, jamais haletant.", "Cherche une pente régulière (gradient autour de 7 à 12%) et tiens la même cadence métronome du bas au sommet de chaque répétition.", "Garde le regard 3 à 5 mètres devant, le buste légèrement incliné vers la pente, et pousse depuis la hanche plus que depuis le mollet.", "Récupère en descente lente et facile entre les répétitions, en laissant le souffle revenir complètement avant la suivante.", "Si l'essoufflement devient incontrôlable, redescends d'un cran l'effort: l'idée est de tenir le même rythme sur tous les intervalles."], equipment: ["bâtons de marche", "sac à dos"], commonMistakes: "Partir trop fort sur les premières répétitions et s'écrouler sur les dernières, au lieu de répartir l'effort uniformément."),
            en: ExerciseExplanation(steps: ["Warm up with easy walking before the first interval, then take the climb at a comfortably hard effort: short sentences possible, never gasping.", "Find a steady grade (around 7 to 12%) and hold the same metronome cadence from bottom to top of each rep.", "Keep your gaze 3 to 5 meters ahead, torso leaning slightly into the slope, and drive from the hip more than the calf.", "Recover with a slow, easy descent between reps, letting your breathing fully return before the next one.", "If breathing gets out of control, drop the effort one notch: the idea is to hold the same rhythm across all intervals."], equipment: ["trekking poles", "backpack"], commonMistakes: "Going out too hard on the first reps and fading on the last ones, instead of spreading the effort evenly.")),
        SeedEntry(matchers: ["etirements cibles", "etirements doux", "cool-down", "mobilite globale", "foam roller", "etirements post-sortie", "etirements"],
            fr: ExerciseExplanation(steps: ["Après l'effort, enchaîne des étirements doux et tenus sur les zones sollicitées: quadriceps, ischio-jambiers, mollets, fléchisseurs de hanche, fessiers.", "Tiens chaque position environ 30 secondes en respirant calmement, sans forcer ni chercher l'amplitude extrême.", "Si tu utilises un rouleau de massage, passe lentement sur mollets, quadriceps, face externe de cuisse et fessiers, environ une minute par zone.", "Reste sur des sensations confortables; en cas d'inconfort sur une zone, réduis l'amplitude et passe à la suivante."], equipment: ["rouleau de massage (optionnel)"], commonMistakes: "Étirer brutalement ou rebondir dans la position; privilégie un maintien lent et progressif."),
            en: ExerciseExplanation(steps: ["After the effort, move through gentle held stretches on the worked areas: quads, hamstrings, calves, hip flexors, glutes.", "Hold each position about 30 seconds while breathing calmly, without forcing or chasing extreme range.", "If you use a foam roller, roll slowly over calves, quads, outer thigh and glutes, about a minute per area.", "Stay within comfortable sensations; if an area feels uncomfortable, ease the range and move to the next."], equipment: ["foam roller (optional)"], commonMistakes: "Stretching abruptly or bouncing in position; favor a slow, progressive hold.")),
        SeedEntry(matchers: ["marche longue", "long hike", "sortie phare", "day hike", "fastpacking simule", "marche multi-jours", "mini multi-jours", "sortie phare day hike", "sortie longue"],
            fr: ExerciseExplanation(steps: ["Sortie longue à allure seuil aérobie dominant (conversational soutenu): l'objectif est la durée et la gestion, pas la performance instantanée.", "Gère ton énergie comme un budget: bois régulièrement (à la sensation, environ un demi à un litre par heure selon la chaleur) et grignote des glucides toutes les 30 à 45 minutes.", "En montée, raccourcis le pas et garde la cadence métronome; en descente, anticipe la pose des pieds 3 à 5 mètres en avant et utilise les bâtons.", "Sur les enchaînements multi-jours, attends-toi à des jambes plus raides au départ et démarre encore plus facile que la veille.", "Vérifie le réglage du sac et le rodage des chaussures avant de partir, pour porter la charge sur les hanches durant des heures."], equipment: ["sac à dos chargé", "bâtons de marche", "eau", "en-cas glucidiques"], commonMistakes: "Attendre d'avoir soif ou faim pour s'hydrater et s'alimenter: sur plusieurs heures, le retard se rattrape difficilement."),
            en: ExerciseExplanation(steps: ["Long outing at a mostly aerobic-threshold pace (comfortably talkative): the goal is duration and management, not instant performance.", "Manage energy like a budget: drink regularly (by feel, roughly half a liter to a liter per hour depending on heat) and snack on carbs every 30 to 45 minutes.", "Uphill, shorten your stride and hold a metronome cadence; downhill, anticipate foot placement 3 to 5 meters ahead and use your poles.", "On back-to-back multi-day outings, expect stiffer legs at the start and begin even easier than the day before.", "Check pack fit and that your shoes are broken in before leaving, so the load rides on your hips for hours."], equipment: ["loaded backpack", "trekking poles", "water", "carbohydrate snacks"], commonMistakes: "Waiting until you feel thirsty or hungry to drink and eat: over several hours, falling behind is hard to recover from.")),
        SeedEntry(matchers: ["pallof", "gainage anti-rotation", "gainage pallof", "pallof press", "anti-rotation", "pallof + dead bug", "pallof rotation"],
            fr: ExerciseExplanation(steps: ["Fixe une bande élastique à hauteur de la poitrine, place-toi de côté par rapport au point d'ancrage et saisis la bande à deux mains.", "Tends les bras devant toi et résiste à la traction qui cherche à faire tourner ton tronc, en gardant les hanches et les épaules face à toi.", "Garde les abdominaux engagés et les fessiers serrés; le but est de ne pas bouger, pas de produire un mouvement.", "Tiens environ 2 à 3 secondes bras tendus, puis reviens lentement avant de répéter de chaque côté."], equipment: ["bande élastique ou poulie"], commonMistakes: "Laisser le tronc pivoter vers l'ancrage; toute la valeur de l'exercice est de rester gainé et immobile."),
            en: ExerciseExplanation(steps: ["Anchor a resistance band at chest height, stand side-on to the anchor and grab the band with both hands.", "Extend your arms in front and resist the pull that wants to rotate your trunk, keeping hips and shoulders facing forward.", "Keep your core engaged and glutes tight; the goal is not to move, not to produce motion.", "Hold about 2 to 3 seconds with arms extended, then return slowly before repeating on each side."], equipment: ["resistance band or cable"], commonMistakes: "Letting the trunk twist toward the anchor; the whole value of the drill is staying braced and still.")),
        SeedEntry(matchers: ["hip thrust", "pont fessier", "pont fessier bipodal"],
            fr: ExerciseExplanation(steps: ["Pour le hip thrust, appuie le haut du dos sur un banc bas; pour le pont fessier, allonge-toi au sol. Dans les deux cas, pieds à plat largeur de bassin.", "Pousse à travers les talons pour monter le bassin jusqu'à aligner épaules, hanches et genoux, en serrant les fessiers en haut.", "Tiens la position haute environ 2 secondes, puis redescends de façon contrôlée sans relâcher d'un coup.", "Pour charger le hip thrust, place un haltère sur les hanches; cette chaîne postérieure sert la propulsion en montée."], equipment: ["banc bas (pour hip thrust)", "haltère (optionnel)"], commonMistakes: "Cambrer le bas du dos pour monter plus haut au lieu de monter en serrant les fessiers; garde le bassin contrôlé."),
            en: ExerciseExplanation(steps: ["For the hip thrust, rest your upper back on a low bench; for the glute bridge, lie on the floor. Either way, feet flat at hip width.", "Drive through your heels to lift the hips until shoulders, hips and knees line up, squeezing the glutes at the top.", "Hold the top for about 2 seconds, then lower under control without dropping all at once.", "To load the hip thrust, set a dumbbell on your hips; this posterior chain powers uphill propulsion."], equipment: ["low bench (for hip thrust)", "dumbbell (optional)"], commonMistakes: "Arching the lower back to get higher instead of rising by squeezing the glutes; keep the pelvis controlled.")),
        SeedEntry(matchers: ["squat poids du corps", "squat goblet", "squat barre", "squat", "goblet"],
            fr: ExerciseExplanation(steps: ["Place les pieds largeur d'épaules, pointes légèrement ouvertes, et garde le buste droit avec le dos en position neutre.", "Descends de façon contrôlée jusqu'à cuisses environ parallèles au sol, en gardant les genoux dans l'axe des pieds.", "Pousse à travers les talons pour remonter, sans laisser les genoux rentrer vers l'intérieur.", "Pour la version goblet, tiens un haltère ou kettlebell contre la poitrine; pour la barre, garde la charge centrée au-dessus du milieu du pied."], equipment: ["haltère, kettlebell ou barre (optionnel)"], commonMistakes: "Décoller les talons ou arrondir le bas du dos en descendant; garde les pieds ancrés et le dos gainé."),
            en: ExerciseExplanation(steps: ["Set feet shoulder-width, toes slightly turned out, torso tall with a neutral spine.", "Lower under control until your thighs are roughly parallel to the floor, keeping knees tracking over the toes.", "Drive through your heels to rise, without letting the knees cave inward.", "For the goblet version, hold a dumbbell or kettlebell against your chest; for the barbell, keep the load centered over mid-foot."], equipment: ["dumbbell, kettlebell or barbell (optional)"], commonMistakes: "Lifting the heels or rounding the lower back as you descend; keep your feet anchored and core braced.")),
        SeedEntry(matchers: ["side plank", "gainage lateral", "side plank dynamique", "side plank avec lift", "pallof + side plank"],
            fr: ExerciseExplanation(steps: ["Allonge-toi sur le côté, coude sous l'épaule, jambes tendues l'une sur l'autre, et soulève le bassin pour aligner cheville, hanche et épaule.", "Engage les obliques du côté au sol et garde les hanches hautes, sans laisser le bassin retomber vers l'arrière.", "Respire calmement et tiens la position; pour la version dynamique, lève lentement la jambe du dessus sans casser l'alignement.", "Travaille les deux côtés pour équilibrer la stabilité latérale utile au port du sac chargé."], equipment: [], commonMistakes: "Laisser les hanches s'affaisser ou pivoter vers le sol au lieu de garder le corps aligné et le bassin haut."),
            en: ExerciseExplanation(steps: ["Lie on your side, elbow under the shoulder, legs extended and stacked, and lift your hips to line up ankle, hip and shoulder.", "Engage the obliques on the down side and keep the hips high, without letting the pelvis drift backward.", "Breathe calmly and hold; for the dynamic version, slowly raise the top leg without breaking the alignment.", "Work both sides to balance the lateral stability that helps when carrying a loaded pack."], equipment: [], commonMistakes: "Letting the hips sag or rotate toward the floor instead of keeping the body aligned and pelvis high.")),
        SeedEntry(matchers: ["single-leg balance", "single leg balance", "balance proprio", "balance bosu", "balance yeux fermes", "proprio"],
            fr: ExerciseExplanation(steps: ["Tiens-toi debout sur une seule jambe, le pied bien à plat, le genou très légèrement fléchi et le regard fixé sur un point devant toi.", "Garde le bassin de niveau et les abdominaux engagés pour limiter les oscillations; vise une tenue stable d'environ 30 secondes par jambe.", "Quand l'équilibre yeux ouverts devient facile, progresse en fermant les yeux, ce qui sollicite davantage la perception de la cheville.", "Si un BOSU est disponible, monte dessus comme progression: la surface instable renforce le travail neuromusculaire pour les terrains accidentés."], equipment: ["BOSU (optionnel)"], commonMistakes: "S'accrocher du regard partout au lieu de fixer un point stable, ce qui empêche le système d'équilibre de travailler."),
            en: ExerciseExplanation(steps: ["Stand on one leg, foot flat, knee very slightly bent, and lock your gaze on a point ahead of you.", "Keep your hips level and core engaged to limit wobble; aim to hold steady for about 30 seconds per leg.", "Once eyes-open balance feels easy, progress by closing your eyes, which loads ankle proprioception more.", "If a BOSU is available, step onto it as a progression: the unstable surface boosts the neuromuscular work for rough terrain."], equipment: ["BOSU (optional)"], commonMistakes: "Darting your eyes everywhere instead of fixing one stable point, which stops your balance system from working.")),
        SeedEntry(matchers: ["marche cardio z2", "marche endurance", "marche continue z2", "marche z2", "bloc z2", "marche z2 plate", "marche z2 gradient", "base aerobie", "marche z1-z2", "marche plate z1-z2", "bloc z2 base"],
            fr: ExerciseExplanation(steps: ["Cale-toi sur une allure conversational: tu peux tenir des phrases longues sans halètement. C'est le repère de la zone aérobie de base.", "Trouve une cadence régulière de marche, type métronome autour de 110-120 pas par minute, et garde-la stable du début à la fin.", "Sur le faux-plat et les petites montées, raccourcis le pas et ralentis plutôt que de forcer, pour rester dans la zone facile.", "Règle le sac sur les hanches (ceinture serrée) pour que le poids repose sur le bassin plutôt que sur les épaules."], equipment: ["sac à dos léger", "eau"], commonMistakes: "Partir trop vite et basculer en essoufflement: l'intérêt de ce bloc est justement de rester facile et régulier."),
            en: ExerciseExplanation(steps: ["Settle into a conversational pace: you can speak full sentences without gasping. That is your aerobic base zone marker.", "Find a steady metronome-like cadence around 110-120 steps per minute and hold it from start to finish.", "On gentle grades and small climbs, shorten your stride and slow down rather than pushing, to stay in the easy zone.", "Set the pack on your hips (hipbelt snug) so the load rests on your pelvis rather than your shoulders."], equipment: ["light backpack", "water"], commonMistakes: "Starting too fast and tipping into hard breathing: the whole point of this block is to stay easy and steady.")),
        SeedEntry(matchers: ["step-up", "step-ups", "step up", "step-up charge", "step-ups charges"],
            fr: ExerciseExplanation(steps: ["Pose un pied entier à plat sur un banc ou une marche stable (30 à 60 cm selon ton niveau), genou dans l'axe du pied.", "Monte en poussant à travers le talon de la jambe avant jusqu'à extension complète de la hanche et du genou en haut.", "Redescends lentement en contrôlant la phase de descente (environ 2 secondes), sans te laisser tomber.", "Charge un sac à dos sur les épaules pour reproduire directement le geste de montée chargée en dénivelé."], equipment: ["banc ou step", "sac à dos (optionnel)"], commonMistakes: "Prendre de l'élan avec la jambe au sol au lieu de pousser réellement avec la jambe posée sur le banc."),
            en: ExerciseExplanation(steps: ["Place one whole foot flat on a bench or stable step (30 to 60 cm depending on your level), knee tracking over the foot.", "Drive up through the heel of the front leg to full hip and knee extension at the top.", "Lower slowly, controlling the descent phase (about 2 seconds), without dropping down.", "Load a backpack on your shoulders to directly mirror the loaded uphill step on elevation gain."], equipment: ["bench or step", "backpack (optional)"], commonMistakes: "Pushing off with the ground leg for momentum instead of really driving with the leg on the bench.")),
        SeedEntry(matchers: ["box jumps", "box jump"],
            fr: ExerciseExplanation(steps: ["Place-toi face à une boîte basse et stable (30 à 40 cm), pieds largeur de bassin.", "Fléchis légèrement les hanches et les genoux, balance les bras, puis monte d'un saut explosif en réceptionnant les deux pieds à plat sur la boîte.", "Amortis la réception genoux légèrement fléchis, buste droit, sans verrouiller les articulations.", "Redescends en posant un pied après l'autre (step-down) plutôt qu'en sautant, pour ménager les genoux."], equipment: ["boîte basse stable"], commonMistakes: "Sauter pour redescendre de la boîte; descends toujours en posant les pieds pour limiter l'impact."),
            en: ExerciseExplanation(steps: ["Stand facing a low, stable box (30 to 40 cm), feet hip-width apart.", "Slightly bend hips and knees, swing your arms, then jump up explosively and land both feet flat on the box.", "Absorb the landing with knees slightly bent and torso tall, without locking the joints.", "Come down by stepping off one foot at a time rather than jumping, to spare your knees."], equipment: ["low stable box"], commonMistakes: "Jumping back down off the box; always step down to limit impact.")),
        SeedEntry(matchers: ["bird-dog", "bird dog", "dead bug"],
            fr: ExerciseExplanation(steps: ["Place-toi à quatre pattes, mains sous les épaules et genoux sous les hanches, le dos en position neutre.", "Tends simultanément un bras et la jambe opposée jusqu'à l'horizontale, en gardant le bassin parfaitement stable.", "Engage les abdominaux pour éviter toute rotation du tronc; imagine garder un verre d'eau en équilibre sur le bas du dos.", "Tiens environ 2 secondes, reviens lentement et alterne les côtés sans précipitation."], equipment: [], commonMistakes: "Laisser le bassin basculer quand on tend le bras et la jambe; la stabilité du tronc prime sur l'amplitude."),
            en: ExerciseExplanation(steps: ["Get on all fours, hands under shoulders and knees under hips, spine in a neutral position.", "Extend one arm and the opposite leg to horizontal at the same time, keeping the pelvis perfectly stable.", "Brace your core to avoid any trunk rotation; imagine balancing a glass of water on your lower back.", "Hold about 2 seconds, return slowly and alternate sides without rushing."], equipment: [], commonMistakes: "Letting the pelvis tilt when you extend the arm and leg; trunk stability matters more than range.")),
    ]
}
